  11	export class SecurityIsolationError extends Error {
  12	  readonly code: 'TENANT_ACCESS_DENIED' | 'VALIDATION_ERROR';
  13	  readonly status: number;
  14	
  15	  constructor(code: 'TENANT_ACCESS_DENIED' | 'VALIDATION_ERROR', message: string) {
  16	    super(message);
  17	    this.name = 'SecurityIsolationError';
  18	    this.code = code;
  19	    this.status = code === 'TENANT_ACCESS_DENIED' ? 403 : 400;
