  22	
  23	export function assertValidScope(scope: TenantUserScope): void {
  24	  if (!scope.tenantId || scope.tenantId.trim().length === 0) {
  25	    throw new SecurityIsolationError('VALIDATION_ERROR', 'tenantId is required');
  26	  }
  27	  if (!scope.userId || scope.userId.trim().length === 0) {
  28	    throw new SecurityIsolationError('VALIDATION_ERROR', 'userId is required');
  29	  }
  30	}
  31	
  32	export function assertScopedAccess(scope: TenantUserScope, record: ScopedRecord): void {
  33	  assertValidScope(scope);
  34	  if (scope.tenantId !== record.tenantId || scope.userId !== record.userId) {
  35	    throw new SecurityIsolationError('TENANT_ACCESS_DENIED', 'cross-tenant access denied');
  36	  }
  37	}
  38	
  39	export function filterScopedRecords<T extends ScopedRecord>(
  40	  records: T[],
  41	  scope: TenantUserScope
  42	): T[] {
  43	  assertValidScope(scope);
  44	  return records.filter((record) => record.tenantId === scope.tenantId && record.userId === scope.userId);
  45	}
  46	
  47	export function getScopedRecordById<T extends ScopedRecord & { id: string }>(
  48	  records: T[],
  49	  id: string,
  50	  scope: TenantUserScope
  51	): T | null {
  52	  assertValidScope(scope);
  53	  const direct = records.find(
  54	    (record) => record.id === id && record.tenantId === scope.tenantId && record.userId === scope.userId
  55	  );
  56	  if (direct) {
