  3	/**
  4	 * Basic authentication handler
  5	 */
  6	export class BasicAuthHandler {
  7	  constructor() {}
  8	
  9	  /**
 10	   * Add Basic auth to request headers
 11	   */
 12	  addToHeaders(headers: Record<string, string>, credentials: BasicAuthCredentials): Record<string, string> {
 13	    const encoded = this.encodeCredentials(credentials.username, credentials.password);
 14	    
 15	    return {
 16	      ...headers,
 17	      Authorization: `Basic ${encoded}`,
 18	    };
 19	  }
 20	
 21	  /**
 22	   * Encode credentials in Base64
 23	   */
 24	  private encodeCredentials(username: string, password: string): string {
 25	    const credentials = `${username}:${password}`;
 26	    return Buffer.from(credentials).toString('base64');
 27	  }
 28	
 29	  /**
 30	   * Decode Basic auth header
 31	   */
 32	  decodeHeader(authHeader: string): BasicAuthCredentials | null {
 33	    if (!authHeader.startsWith('Basic ')) {
 34	      return null;
 35	    }
 36	
 37	    const encoded = authHeader.slice(6);
 38	    const decoded = Buffer.from(encoded, 'base64').toString('utf8');
 39	    const separatorIndex = decoded.indexOf(':');
 40	    if (separatorIndex <= 0) {
 41	      return null;
 42	    }
 43	
 44	    const username = decoded.slice(0, separatorIndex);
 45	    const password = decoded.slice(separatorIndex + 1);
 46	    if (!password) {
 47	      return null;
 48	    }
 49	
 50	    return {
 51	      type: 'basic',
 52	      username,
 53	      password,
 54	    };
 55	  }
 56	
 57	  /**
 58	   * Validate credentials format
 59	   */
 60	  validate(credentials: BasicAuthCredentials): boolean {
 61	    return (
 62	      typeof credentials.username === 'string' &&
 63	      credentials.username.length > 0 &&
 64	      typeof credentials.password === 'string' &&
 65	      credentials.password.length > 0
 66	    );
 67	  }
 68	}
