  5	import type { Router } from '@superfunctions/http';
  6	import type { Context } from 'hono';
  7	import { Hono } from 'hono';
  8	
  9	export interface ToHonoOptions {
 10	  /** Override mount prefix when Hono routePath inference is unavailable */
 11	  mountPath?: string;
 12	}
 13	
 14	/**
 15	 * Convert a @superfunctions/http Router to a Hono instance
 16	 *
 17	 * Hono uses Web Standards natively, so translation is minimal.
 18	 * When mounted with `app.route('/api', toHono(router))`, the adapter
 19	 * rewrites the request path relative to the mount point (same behavior
 20	 * as the Express adapter's use of `req.url`).
 21	 *
 22	 * Usage:
 23	 * ```typescript
 24	 * const router = createRouter({ routes: [...] });
 25	 * app.route('/api', toHono(router));
 26	 * ```
 27	 */
 28	export function toHono(
 29	  router: Router,
 30	  options: ToHonoOptions = {}
 31	): import('hono').Hono {
 32	  const app = new Hono();
 33	
 34	  app.all('*', async (c: Context) => {
 35	    const routePath =
 36	      c.req.matchedRoutes?.at(-1)?.path ?? c.req.routePath;
 37	    const mountPrefix =
 38	      options.mountPath ??
 39	      getMountPrefixFromRoutePath(routePath, c.req.raw.url, c.req.param());
 40	    if (hasConsumedBody(c.req.raw)) {
 41	      return Response.json(
 42	        {
 43	          error:
 44	            'Request body was already consumed by Hono middleware before reaching the Superfunctions router',
 45	        },
 46	        { status: 400 }
 47	      );
 48	    }
 49	    const webRequest = toMountedRequest(c.req.raw, mountPrefix);
 50	    return router.handle(webRequest);
 51	  });
 52	
 53	  return app;
 54	}
 55	
 56	function getMountPrefixFromRoutePath(
 57	  routePath: unknown,
 58	  requestUrl?: string,
 59	  params: Record<string, string> = {}
 60	): string {
 61	  if (typeof routePath !== 'string' || routePath.length === 0) {
 62	    return '';
 63	  }
 64	
 65	  if (routePath.endsWith('/*')) {
 66	    return resolveConcreteMountPrefix(routePath.slice(0, -2), requestUrl, params);
 67	  }
 68	
 69	  return routePath === '*' ? '' : resolveConcreteMountPrefix(routePath, requestUrl, params);
 70	}
 71	
 72	function resolveConcreteMountPrefix(
 73	  routePath: string,
 74	  requestUrl?: string,
 75	  params: Record<string, string> = {}
 76	): string {
 77	  if (!routePath.includes(':') || !requestUrl) {
 78	    return routePath;
 79	  }
 80	
 81	  const url = new URL(requestUrl);
 82	  const routeSegments = routePath.split('/').filter(Boolean);
 83	  const pathSegments = url.pathname.split('/').filter(Boolean);
 84	
 85	  if (routeSegments.length > pathSegments.length) {
 86	    return routePath;
 87	  }
 88	
 89	  const resolvedSegments = routeSegments.map((segment, index) => {
 90	    if (!segment.startsWith(':')) {
 91	      return segment;
 92	    }
 93	
 94	    const rawSegment = pathSegments[index];
 95	    if (rawSegment !== undefined) {
 96	      return rawSegment;
 97	    }
 98	
 99	    const paramName = segment.slice(1);
100	    const paramValue = params[paramName];
101	    return paramValue !== undefined ? encodeURIComponent(paramValue) : segment;
102	  });
103	
104	  return `/${resolvedSegments.join('/')}`;
105	}
106	
107	function toMountedRequest(request: Request, mountPrefix: string): Request {
108	  if (!mountPrefix) {
109	    return request;
110	  }
111	
112	  const url = new URL(request.url);
113	  if (
114	    url.pathname === mountPrefix ||
115	    url.pathname.startsWith(`${mountPrefix}/`)
116	  ) {
117	    url.pathname = url.pathname.slice(mountPrefix.length) || '/';
118	  }
119	
120	  return new Request(url, request);
121	}
