188	export function createRateLimiter(config: RateLimitConfig): RateLimiter {
189	  const now = config.now ?? Date.now;
190	  const {
191	    windowMs,
192	    maxRequests,
193	    keyPrefix = 'ratelimit:',
194	    persistence = createInMemoryKVStore(now),
195	    algorithm = 'fixed-window',
196	  } = config;
197	
198	  const kv = ensureKV(persistence, now);
199	  const keyLocks = new Map<string, Promise<void>>();
200	
201	  async function withKeyLock<T>(key: string, work: () => Promise<T>): Promise<T> {
202	    const prior = keyLocks.get(key) ?? Promise.resolve();
203	    let resolveLock!: () => void;
204	    const current = new Promise<void>((resolve) => {
205	      resolveLock = resolve;
206	    });
207	    const queued = prior.then(() => current);
208	    keyLocks.set(key, queued);
209	
210	    await prior;
211	    try {
212	      return await work();
213	    } finally {
214	      resolveLock();
215	      if (keyLocks.get(key) === queued) {
216	        keyLocks.delete(key);
217	      }
218	    }
219	  }
220	
221	  async function withKeyLocks<T>(keys: string[], work: () => Promise<T>): Promise<T> {
222	    const uniqueKeys = [...new Set(keys)].sort();
223	    const releases: Array<() => void> = [];
224	    const queuedLocks: Array<{ key: string; queued: Promise<void> }> = [];
225	
226	    try {
227	      for (const key of uniqueKeys) {
228	        const prior = keyLocks.get(key) ?? Promise.resolve();
229	        let resolveLock!: () => void;
230	        const current = new Promise<void>((resolve) => {
231	          resolveLock = resolve;
232	        });
233	        const queued = prior.then(() => current);
234	        keyLocks.set(key, queued);
235	        queuedLocks.push({ key, queued });
236	        releases.push(resolveLock);
237	        await prior;
238	      }
239	
240	      return await work();
241	    } finally {
242	      for (let index = releases.length - 1; index >= 0; index -= 1) {
243	        releases[index]();
244	      }
245	      for (const { key, queued } of queuedLocks) {
246	        if (keyLocks.get(key) === queued) {
247	          keyLocks.delete(key);
248	        }
249	      }
250	    }
251	  }
252	
253	  async function evaluateKey(
254	    key: string,
255	    currentTime: number,
256	    effectiveWindowMs: number,
257	    effectiveLimit: number,
258	    commit: boolean
259	  ): Promise<RateLimitResult> {
260	    if (!Number.isFinite(effectiveWindowMs) || effectiveWindowMs <= 0) {
261	      throw new Error('RATE_LIMIT_WINDOW_INVALID');
262	    }
263	    if (!Number.isFinite(effectiveLimit) || effectiveLimit < 0) {
264	      throw new Error('RATE_LIMIT_LIMIT_INVALID');
265	    }
266	
267	    if (algorithm === 'sliding-window') {
268	      const state = (await getState<SlidingWindowState>(kv, key)) ?? { timestamps: [] };
269	      const floor = currentTime - effectiveWindowMs;
270	      const timestamps = state.timestamps.filter((timestamp) => timestamp > floor);
271	      const allowed = timestamps.length < effectiveLimit;
272	      if (allowed && commit) {
273	        timestamps.push(currentTime);
274	      }
275	
276	      const oldest = timestamps[0] ?? currentTime;
277	      const resetAt = oldest + effectiveWindowMs;
278	      if (commit) {
279	        await setState(kv, key, { timestamps }, Math.max(1, resetAt - currentTime));
280	      }
281	
282	      return {
283	        allowed,
284	        remaining: Math.max(0, effectiveLimit - timestamps.length),
285	        resetAt: new Date(resetAt).toISOString(),
286	        total: effectiveLimit,
287	      };
288	    }
289	
290	    if (algorithm === 'token-bucket') {
291	      if (effectiveLimit <= 0) {
292	        const resetAt = currentTime + Math.max(0, effectiveWindowMs);
293	        return {
294	          allowed: false,
295	          remaining: 0,
296	          resetAt: new Date(resetAt).toISOString(),
297	          total: effectiveLimit,
298	        };
299	      }
300	
301	      const refillRatePerMs = effectiveLimit / effectiveWindowMs;
302	      const state = (await getState<TokenBucketState>(kv, key)) ?? {
303	        tokens: effectiveLimit,
304	        lastRefill: currentTime,
305	      };
306	
307	      const elapsed = Math.max(0, currentTime - state.lastRefill);
308	      const tokens = Math.min(effectiveLimit, state.tokens + elapsed * refillRatePerMs);
309	      const allowed = tokens >= 1;
310	      const nextTokens = allowed && commit ? tokens - 1 : tokens;
311	      const msUntilNextToken = nextTokens >= 1 ? 0 : Math.ceil((1 - nextTokens) / refillRatePerMs);
312	      const msUntilFull = Math.ceil((effectiveLimit - nextTokens) / refillRatePerMs);
313	      const resetAt = currentTime + msUntilNextToken;
314	
315	      if (commit) {
316	        await setState(
317	          kv,
318	          key,
319	          {
320	            tokens: nextTokens,
321	            lastRefill: currentTime,
322	          },
323	          Math.max(1, msUntilFull)
324	        );
325	      }
326	
327	      return {
328	        allowed,
329	        remaining: Math.max(0, Math.floor(nextTokens)),
330	        resetAt: new Date(resetAt).toISOString(),
331	        total: effectiveLimit,
332	      };
333	    }
334	
335	    const state = (await getState<FixedWindowState>(kv, key)) ?? {
336	      count: 0,
337	      windowStart: currentTime,
338	    };
339	    const windowState =
340	      currentTime >= state.windowStart + effectiveWindowMs
341	        ? { count: 0, windowStart: currentTime }
342	        : { ...state };
343	
344	    const allowed = windowState.count < effectiveLimit;
345	    if (allowed && commit) {
346	      windowState.count += 1;
347	    }
348	
349	    const resetAt = windowState.windowStart + effectiveWindowMs;
350	    if (commit) {
351	      await setState(kv, key, windowState, Math.max(1, resetAt - currentTime));
352	    }
353	
354	    return {
355	      allowed,
356	      remaining: Math.max(0, effectiveLimit - windowState.count),
357	      resetAt: new Date(resetAt).toISOString(),
358	      total: effectiveLimit,
359	    };
360	  }
