    34	/**
    35	 * Convert Express Request to Web Standard Request
    36	 */
    37	async function convertToWebRequest(req: express.Request): Promise<Request> {
    38	  // Build full URL
    39	  // Use req.url (not originalUrl) to get path relative to router mount point
    40	  const protocol = req.protocol;
    41	  const host = req.get('host') || 'localhost';
    42	  const url = `${protocol}://${host}${req.url}`;
    43	
    44	  // Convert headers
    45	  const headers = new Headers();
    46	  for (const [key, value] of Object.entries(req.headers)) {
    47	    if (value) {
    48	      if (Array.isArray(value)) {
    49	        value.forEach((v) => headers.append(key, v));
    50	      } else {
    51	        headers.set(key, value);
    52	      }
    53	    }
    54	  }
    55	
    56	  // Handle body
    57	  let body: BodyInit | null = null;
    58	  if (req.method !== 'GET' && req.method !== 'HEAD') {
    59	    // If body is already parsed (e.g., by express.json() middleware)
    60	    if (req.body && Object.keys(req.body).length > 0) {
    61	      body = JSON.stringify(req.body);
    62	      // Ensure Content-Type is set
    63	      if (!headers.has('Content-Type')) {
    64	        headers.set('Content-Type', 'application/json');
    65	      }
    66	    }
    67	  }
    68	
    69	  return new Request(url, {
    70	    method: req.method,
    71	    headers,
    72	    body,
    73	  });
    74	}
