import { RateLimiter } from '../middleware/rate-limiter.js';
import { ProviderRateLimitedError, RetryMiddleware } from '../middleware/retry.js';
import { SendQueue } from './queue.js';
import { defaultSendPolicyModel, evaluateSendPolicy, type SendPolicyModel } from './policies.js';
import {
  SendGovernanceError,
  type SendRequest,
  type SendBlockedDecision,
  type SendProcessResult,
  type SendQueueResult,
  type SendScope,
} from './types.js';

interface SendGovernorDependencies {
  queue?: SendQueue;
  policies?: SendPolicyModel;
  now?: () => string;
  retryMiddleware?: RetryMiddleware;
  rateLimiter?: RateLimiter;
}

export interface SendTransport {
  send(input: {
    providerId: string;
    tenantId: string;
    userId: string;
    jobId: string;
    payload?: SendRequest['payload'];
  }): Promise<{ providerMessageId?: string }>;
}

export class SendGovernor {
  private readonly queue: SendQueue;
  private readonly policies: SendPolicyModel;
  private readonly now: () => string;
  private readonly retryMiddleware: RetryMiddleware;
  private readonly rateLimiter: RateLimiter;
  private readonly blockedByScope = new Map<string, SendBlockedDecision[]>();

  constructor(dependencies: SendGovernorDependencies = {}) {
    this.queue = dependencies.queue ?? new SendQueue({ now: dependencies.now });
    this.policies = dependencies.policies ?? defaultSendPolicyModel;
    this.now = dependencies.now ?? (() => new Date().toISOString());
    this.retryMiddleware = dependencies.retryMiddleware ?? new RetryMiddleware();
    this.rateLimiter = dependencies.rateLimiter ?? new RateLimiter();
  }

  async scheduleSend(request: SendRequest): Promise<SendQueueResult> {
    const decision = evaluateSendPolicy(request, this.policies);
    if (!decision.allowed) {
      this.persistBlockedDecision({
        decisionId: buildDecisionId(request),
        tenantId: request.tenantId,
        userId: request.userId,
        providerId: request.providerId,
        idempotencyKey: request.idempotencyKey,
        code: 'MAIL_SEND_BLOCKED',
        message: decision.message ?? 'send policy limit exceeded',
        retryable: decision.retryable,
        reason: decision.reason,
        blockedAt: this.now(),
      });

      throw new SendGovernanceError(
        'MAIL_SEND_BLOCKED',
        decision.message ?? 'send policy limit exceeded',
        decision.retryable
      );
    }

    const queued = await this.queue.enqueue(request);
    return {
      queued: true,
      jobId: queued.job.jobId,
      policyPassed: true,
      duplicate: queued.duplicate,
    };
  }

  async processQueuedSend(
    input: {
      jobId: string;
      scope: SendScope;
      transport: SendTransport;
    }
  ): Promise<SendProcessResult> {
    const job = this.queue.get(input.jobId, input.scope);
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${input.jobId}`);
    }

    const providerLimitConfig = {
      requests: 1,
      window: 60000,
    };
    await this.rateLimiter.acquireMany(
      [
        `provider:${job.providerId}`,
        `provider:${job.providerId}:tenant:${job.tenantId}`,
      ],
      providerLimitConfig
    );

    this.queue.updateStatus(job.jobId, input.scope, 'processing');

    try {
      const result = await this.retryMiddleware.execute(
        () =>
          input.transport.send({
            providerId: job.providerId,
            tenantId: job.tenantId,
            userId: job.userId,
            jobId: job.jobId,
            payload: job.payload,
          }),
        `send:${job.jobId}`
      );

      this.queue.updateStatus(job.jobId, input.scope, 'sent');
      return {
        sent: true,
        jobId: job.jobId,
        retries: result.retries,
      };
    } catch (error) {
      if (error instanceof ProviderRateLimitedError) {
        this.queue.updateStatus(job.jobId, input.scope, 'failed', {
          code: 'PROVIDER_RATE_LIMITED',
          message: error.message,
          retryable: false,
        });
        throw new SendGovernanceError('PROVIDER_RATE_LIMITED', error.message);
      }

      this.queue.updateStatus(job.jobId, input.scope, 'failed', {
        code: 'VALIDATION_ERROR',
        message: (error as Error).message,
        retryable: false,
      });
      throw error;
    }
  }

  getQueuedSend(jobId: string, scope: SendScope) {
    return this.queue.get(jobId, scope);
  }

  listQueuedSends(scope: SendScope) {
    return this.queue.list(scope);
  }

  listBlockedDecisions(scope: SendScope): SendBlockedDecision[] {
    return [...(this.blockedByScope.get(scopeKey(scope)) ?? [])];
  }

  wouldExceedRateLimit(providerId: string, tenantId: string): { provider: boolean; tenant: boolean } {
    const config = {
      requests: 1,
      window: 60000,
    };
    return {
      provider: this.rateLimiter.wouldExceed(`provider:${providerId}`, config),
      tenant: this.rateLimiter.wouldExceed(`provider:${providerId}:tenant:${tenantId}`, config),
    };
  }

  private persistBlockedDecision(decision: SendBlockedDecision): void {
    const key = scopeKey(decision);
    const existing = this.blockedByScope.get(key) ?? [];
    this.blockedByScope.set(key, [...existing, decision]);
  }
}

function buildDecisionId(request: SendRequest): string {
  const entropy = Math.random().toString(36).slice(2, 10);
  return `blocked_${request.providerId}_${request.idempotencyKey}_${entropy}`;
}

function scopeKey(scope: SendScope): string {
  return `${scope.tenantId}:${scope.userId}`;
}
import { MemoryQueueAdapter, type QueueAdapter } from '@superfunctions/queue';
import {
  SendGovernanceError,
  type SendRequest,
  type SendJob,
  type SendJobError,
  type SendJobStatus,
  type SendScope,
  assertSendRequest,
  assertSendScope,
  assertTenantUserAccess,
} from './types.js';

interface QueueDependencies {
  now?: () => string;
  retentionMs?: number;
  queueAdapter?: QueueAdapter<SendJob>;
}

export interface QueueEnqueueResult {
  job: SendJob;
  duplicate: boolean;
}

export class SendQueue {
  private readonly now: () => string;
  private readonly retentionMs: number;
  private readonly queueAdapter: QueueAdapter<SendJob>;
  private readonly jobByScopeAndId = new Map<string, SendJob>();
  private readonly jobScopeByJobId = new Map<string, SendScope>();
  private readonly idempotencyByScope = new Map<string, string>();
  private readonly enqueueLocks = new Map<string, Promise<void>>();

  constructor(dependencies: QueueDependencies = {}) {
    this.now = dependencies.now ?? (() => new Date().toISOString());
    this.retentionMs = dependencies.retentionMs ?? 24 * 60 * 60 * 1000;
    this.queueAdapter = dependencies.queueAdapter ?? new MemoryQueueAdapter<SendJob>();
  }

  async enqueue(request: SendRequest): Promise<QueueEnqueueResult> {
    assertSendRequest(request);
    this.cleanupExpiredTerminalJobs();

    const idempotencyKey = scopedIdempotencyKey(request);
    return this.withEnqueueLock(idempotencyKey, async () => {
      const existingJobId = this.idempotencyByScope.get(idempotencyKey);
      if (existingJobId) {
        const existing = this.mustGetByScopedId(existingJobId, request);
        return {
          job: existing,
          duplicate: true,
        };
      }

      const timestamp = this.now();
      const jobId = createSendJobId(request.providerId, request.idempotencyKey);
      const job: SendJob = {
        ...request,
        jobId,
        status: 'queued',
        createdAt: timestamp,
        updatedAt: timestamp,
        attempts: 0,
      };

      const scopedId = scopedJobId(jobId, request);
      this.jobByScopeAndId.set(scopedId, job);
      this.jobScopeByJobId.set(jobId, { tenantId: request.tenantId, userId: request.userId });
      this.idempotencyByScope.set(idempotencyKey, jobId);
      try {
        await this.queueAdapter.enqueue(scopedQueueName(request), job);
      } catch (error) {
        this.jobByScopeAndId.delete(scopedId);
        this.jobScopeByJobId.delete(jobId);
        this.idempotencyByScope.delete(idempotencyKey);
        throw error;
      }

      return {
        job,
        duplicate: false,
      };
    });
  }

  get(jobId: string, scope: SendScope): SendJob | undefined {
    assertSendScope(scope);
    const existingScope = this.jobScopeByJobId.get(jobId);
    if (!existingScope) {
      return undefined;
    }

    assertTenantUserAccess(scope, existingScope);
    return this.jobByScopeAndId.get(scopedJobId(jobId, scope));
  }

  list(scope: SendScope): SendJob[] {
    assertSendScope(scope);
    this.cleanupExpiredTerminalJobs();
    const prefix = scopedPrefix(scope);
    return [...this.jobByScopeAndId.entries()]
      .filter(([key]) => key.startsWith(prefix))
      .map(([, value]) => value);
  }

  updateStatus(jobId: string, scope: SendScope, status: SendJobStatus, error?: SendJobError): SendJob {
    const job = this.get(jobId, scope);
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${jobId}`);
    }

    const updated: SendJob = {
      ...job,
      status,
      attempts: job.attempts + 1,
      updatedAt: this.now(),
      lastError: error,
    };

    this.jobByScopeAndId.set(scopedJobId(jobId, scope), updated);
    this.cleanupExpiredTerminalJobs();
    return updated;
  }

  private mustGetByScopedId(jobId: string, scope: SendScope): SendJob {
    const job = this.jobByScopeAndId.get(scopedJobId(jobId, scope));
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${jobId}`);
    }
    return job;
  }

  private async withEnqueueLock<T>(key: string, work: () => Promise<T>): Promise<T> {
    const prior = this.enqueueLocks.get(key) ?? Promise.resolve();
    let release!: () => void;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });
    const tail = prior.then(() => current);
    this.enqueueLocks.set(key, tail);

    await prior;
    try {
      return await work();
    } finally {
      release();
      if (this.enqueueLocks.get(key) === tail) {
        this.enqueueLocks.delete(key);
      }
    }
  }

  private cleanupExpiredTerminalJobs(): void {
    const cutoff = Date.parse(this.now()) - this.retentionMs;
    for (const [scopedId, job] of this.jobByScopeAndId.entries()) {
      if (!isTerminalStatus(job.status) || Date.parse(job.updatedAt) >= cutoff) {
        continue;
      }

      this.jobByScopeAndId.delete(scopedId);
      this.jobScopeByJobId.delete(job.jobId);
      this.idempotencyByScope.delete(scopedIdempotencyKey(job));
    }
  }
}

function scopedQueueName(scope: SendScope): string {
  return `send:${scope.tenantId}:${scope.userId}`;
}

function isTerminalStatus(status: SendJobStatus): boolean {
  return status === 'sent' || status === 'failed';
}

function scopedPrefix(scope: SendScope): string {
  return `${scope.tenantId}:${scope.userId}:`;
}

function scopedJobId(jobId: string, scope: SendScope): string {
  return `${scope.tenantId}:${scope.userId}:${jobId}`;
}

function scopedIdempotencyKey(request: SendRequest): string {
  return `${request.tenantId}:${request.userId}:${request.providerId}:${request.idempotencyKey}`;
}

function createSendJobId(providerId: string, idempotencyKey: string): string {
  const entropy = Math.random().toString(36).slice(2, 10);
  const provider = providerId.toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 8);
  const idem = idempotencyKey.toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 8);
  return `send_${provider}_${idem}_${entropy}`;
}
