"""Shared adapter helpers for PlugFn web framework integrations."""

from inspect import isawaitable
from typing import Any, Optional


class AdapterSecurityError(Exception):
    """Deterministic adapter-layer security error."""

    def __init__(
        self, code: str, message: str, status_code: int, details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message)
        self.code = code
        self.status_code = status_code
        self.details = details or {}


async def resolve_principal(request_obj: Any, plug: Any, auth_override: Optional[Any]) -> dict[str, Any]:
    auth_provider = auth_override or getattr(getattr(plug, "config", None), "auth", None)
    if auth_provider is None:
        raise AdapterSecurityError("PLUGFN_AUTH_REQUIRED", "Authentication is required", 401)

    principal = await invoke_auth_provider(auth_provider, request_obj)
    normalized = normalize_principal(principal)
    if normalized is None:
        raise AdapterSecurityError("PLUGFN_AUTH_REQUIRED", "Authentication is required", 401)
    return normalized


async def invoke_auth_provider(auth_provider: Any, request_obj: Any) -> Any:
    for attribute in ("authenticate", "require_auth", "requireAuth", "get_user_id", "getUserId"):
        method = getattr(auth_provider, attribute, None)
        if callable(method):
            result = method(request_obj)
            return await result if isawaitable(result) else result

    if callable(auth_provider):
        result = auth_provider(request_obj)
        return await result if isawaitable(result) else result

    return None


def normalize_principal(principal: Any) -> Optional[dict[str, Any]]:
    if principal is None:
        return None

    if isinstance(principal, str):
        return {"user_id": principal}

    if isinstance(principal, dict):
        user_id = principal.get("user_id") or principal.get("userId")
        if isinstance(user_id, str) and user_id:
            return {
                "user_id": user_id,
                "tenant_id": principal.get("tenant_id") or principal.get("tenantId"),
            }

    return None


def assert_identity_match(principal: dict[str, Any], requested_user_id: Any) -> None:
    if requested_user_id is None:
        return

    if requested_user_id != principal["user_id"]:
        raise AdapterSecurityError(
            "TENANT_ACCESS_DENIED",
            "Caller identity does not match the authenticated principal",
            403,
            {"userId": principal["user_id"]},
        )


def normalize_scopes(value: Any) -> Optional[list[str]]:
    if value is None:
        return None
    if isinstance(value, list):
        scopes = [scope for scope in value if isinstance(scope, str) and scope]
        return scopes or None
    if isinstance(value, str):
        scopes = [scope.strip() for scope in value.split(",") if scope.strip()]
        return scopes or None
    return None


def resolve_webhook_secret(plug: Any, provider: str) -> Optional[str]:
    connection_manager = getattr(plug, "_connection_manager", None)
    if connection_manager and hasattr(connection_manager, "resolve_webhook_secret"):
        return connection_manager.resolve_webhook_secret(provider)

    integrations = getattr(getattr(plug, "config", None), "integrations", {}) or {}
    provider_config = integrations.get(provider, {})
    for key in ("webhook_secret", "signing_secret", "webhookSigningSecret", "signingSecret"):
        value = provider_config.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def normalize_headers(headers: dict[str, Any]) -> dict[str, str]:
    normalized: dict[str, str] = {}
    for key, value in headers.items():
        if isinstance(value, str):
            normalized[key.lower()] = value
    return normalized


def success_payload(data: dict[str, Any]) -> dict[str, Any]:
    return {"ok": True, "data": data}


def error_payload(error: Exception) -> tuple[dict[str, Any], int]:
    if isinstance(error, AdapterSecurityError):
        return (
            {
                "ok": False,
                "error": {
                    "code": error.code,
                    "message": str(error),
                    "status": error.status_code,
                    "details": error.details,
                },
            },
            error.status_code,
        )

    error_code = getattr(error, "code", "VALIDATION_ERROR")
    status_code = getattr(error, "status", 400)
    return (
        {
            "ok": False,
            "error": {
                "code": error_code,
                "message": str(error),
                "status": status_code,
                "details": {},
            },
        },
        status_code,
    )
"""FastAPI adapter for PlugFn."""

from typing import Any, Optional

try:
    from fastapi import APIRouter, Request
    from fastapi.responses import JSONResponse
except ImportError:
    raise ImportError(
        "FastAPI is required for this adapter. Install it with: pip install plugfn[fastapi]"
    )

from ._shared import (
    AdapterSecurityError,
    assert_identity_match,
    error_payload,
    normalize_headers,
    normalize_scopes,
    resolve_principal,
    resolve_webhook_secret,
    success_payload,
)


def mount_plugfn(
    app: Any,
    plug: Any,
    prefix: str = "/api/plugfn",
    auth: Optional[Any] = None,
) -> APIRouter:
    """Mount PlugFn routes to a FastAPI app."""
    router = APIRouter(prefix=prefix, tags=["plugfn"])

    @router.post("/connections/auth")
    async def create_connection_auth(request: Request):
        return await _handle_auth_url_request(request, plug, auth)

    @router.get("/auth/{provider}")
    async def legacy_get_auth_url(provider: str, request: Request):
        return await _handle_auth_url_request(request, plug, auth, provider_override=provider)

    @router.get("/callback")
    async def canonical_callback(code: str, state: str, provider: Optional[str] = None):
        return await _handle_callback(provider, code, state, plug)

    @router.get("/auth/{provider}/callback")
    async def legacy_callback(provider: str, code: str, state: str):
        return await _handle_callback(provider, code, state, plug)

    @router.get("/connections")
    async def list_connections(request: Request, provider: Optional[str] = None):
        try:
            principal = await resolve_principal(request, plug, auth)
            requested_user_id = _request_value(request, "user_id") or _request_value(request, "userId")
            assert_identity_match(principal, requested_user_id)
            connections = await plug.connections.list(user_id=principal["user_id"], provider=provider)
            return _success({"userId": principal["user_id"], "connections": [_connection_json(item) for item in connections]})
        except Exception as error:
            return _error_from_exception(error)

    @router.post("/connections/disconnect")
    async def disconnect_connection(request: Request):
        try:
            payload = await _read_json_body(request)
            principal = await resolve_principal(request, plug, auth)
            assert_identity_match(principal, payload.get("user_id") or payload.get("userId"))
            connection_id = payload.get("connection_id") or payload.get("connectionId")
            if not isinstance(connection_id, str) or not connection_id:
                raise AdapterSecurityError("VALIDATION_ERROR", "connection_id is required", 400)
            await plug.connections.disconnect(connection_id=connection_id, user_id=principal["user_id"])
            return _success({"connectionId": connection_id, "disconnected": True})
        except Exception as error:
            return _error_from_exception(error)

    @router.delete("/connections/{connection_id}")
    async def legacy_disconnect(connection_id: str, request: Request):
        try:
            principal = await resolve_principal(request, plug, auth)
            await plug.connections.disconnect(connection_id=connection_id, user_id=principal["user_id"])
            return _success({"connectionId": connection_id, "disconnected": True})
        except Exception as error:
            return _error_from_exception(error)

    @router.post("/webhooks/{provider}/{event}")
    async def handle_webhook(provider: str, event: str, request: Request):
        try:
            raw_body = await request.body()
            headers = normalize_headers(dict(request.headers))
            secret = resolve_webhook_secret(plug, provider)
            results = await plug._webhook_handler.handle_webhook(
                provider=provider,
                event=event,
                payload=None,
                headers=headers,
                secret=secret,
                raw_body=raw_body,
            )
            return _success({"results": results})
        except Exception as error:
            return _error_from_exception(error)

    @router.get("/providers")
    async def list_providers(request: Request):
        try:
            await resolve_principal(request, plug, auth)
            providers = plug.providers.list()
            return _success({"providers": [_provider_json(provider) for provider in providers]})
        except Exception as error:
            return _error_from_exception(error)

    app.include_router(router)
    return router


async def _handle_auth_url_request(
    request: Request,
    plug: Any,
    auth_override: Optional[Any],
    provider_override: Optional[str] = None,
) -> JSONResponse:
    try:
        if request.method == "POST":
            payload = await _read_json_body(request)
            provider = provider_override or payload.get("provider")
            redirect_uri = payload.get("redirect_uri") or payload.get("redirectUri")
            scopes_value = payload.get("scopes")
            requested_user_id = payload.get("user_id") or payload.get("userId")
            connection_name = payload.get("connection_name") or payload.get("connectionName")
        else:
            provider = provider_override or _request_value(request, "provider")
            redirect_uri = _request_value(request, "redirect_uri")
            scopes_value = _request_value(request, "scopes")
            requested_user_id = _request_value(request, "user_id") or _request_value(request, "userId")
            connection_name = _request_value(request, "connection_name") or _request_value(request, "connectionName")

        if not isinstance(provider, str) or not provider:
            raise AdapterSecurityError("VALIDATION_ERROR", "provider is required", 400)
        if not isinstance(redirect_uri, str) or not redirect_uri:
            raise AdapterSecurityError("VALIDATION_ERROR", "redirect_uri is required", 400)

        principal = await resolve_principal(request, plug, auth_override)
        assert_identity_match(principal, requested_user_id)
        url = await plug.connections.get_auth_url(
            provider=provider,
            user_id=principal["user_id"],
            redirect_uri=redirect_uri,
            scopes=normalize_scopes(scopes_value),
            connection_name=connection_name,
        )
        return _success({"url": url, "userId": principal["user_id"]})
    except Exception as error:
        return _error_from_exception(error)


async def _handle_callback(
    provider: Optional[str], code: str, state: str, plug: Any
) -> JSONResponse:
    try:
        connection = await plug.connections.handle_callback(provider=provider, code=code, state=state)
        return _success({"connection": {"id": connection.id, "provider": connection.provider, "status": connection.status}})
    except Exception as error:
        return _error_from_exception(error)


async def _read_json_body(request: Request) -> dict[str, Any]:
    payload = await request.json()
    if not isinstance(payload, dict):
        raise AdapterSecurityError("VALIDATION_ERROR", "JSON body must be an object", 400)
    return payload


def _request_value(request: Request, key: str) -> Optional[str]:
    value = request.query_params.get(key)
    return value if isinstance(value, str) else None


def _connection_json(connection: Any) -> dict[str, Any]:
    connected_at = getattr(connection, "connected_at", None)
    return {
        "id": connection.id,
        "provider": connection.provider,
        "name": connection.name,
        "status": connection.status,
        "connected_at": connected_at.isoformat() if connected_at else None,
    }
