/**
 * In-memory adapter for testing
 */

import { createAdapterFactory } from '../../adapter/factory.js';
import { NotFoundError, OperationNotSupportedError } from '../../adapter/errors.js';
import type {
  Adapter,
  AdapterSchemaInput,
  CreateParams,
  FindOneParams,
  FindManyParams,
  UpdateParams,
  DeleteParams,
  CreateManyParams,
  UpdateManyParams,
  DeleteManyParams,
  UpsertParams,
  CountParams,
  WhereClause,
  OrderBy,
  TransactionAdapter,
  TableSchema,
  ValidationResult,
  HealthStatus,
  InternalCrud,
  InternalColumnDef,
} from '../../adapter/types.js';
import { normalizeAdapterSchema } from '../../adapter/schema-codecs.js';

export interface MemoryAdapterConfig {
  /**
   * @deprecated Function authors should wrap incoming adapters with
   * `wrapWithSchema(adapter, getSchema(...))` inside their create/init function.
   * This option remains for compatibility and app-level direct adapter usage.
   */
  adapterSchema?: AdapterSchemaInput;
  namespace?: {
    enabled: boolean;
    separator?: string;
    prefix?: string;
  };
  debug?: boolean;
}

function createMemoryInternalCrud(): InternalCrud {
  const internalStore = new Map<string, Map<string, Record<string, unknown>>>();
  const ensuredTables = new Set<string>();
  const TABLE_NAME_RE = /^__datafn_[a-z0-9_]+$/;

  function matchesInternalWhere(
    record: Record<string, unknown>,
    where: Array<{ field: string; op: string; value: unknown }>,
  ): boolean {
    return where.every((w) => {
      const val = record[w.field];
      switch (w.op) {
        case 'eq': return val === w.value;
        case 'ne': return val !== w.value;
        case 'in':
          return Array.isArray(w.value) && w.value.includes(val);
        case 'gt': return (val as number) > (w.value as number);
        case 'gte': return (val as number) >= (w.value as number);
