    const idempotencyKey = scopedIdempotencyKey(request);
    return this.withEnqueueLock(idempotencyKey, async () => {
      const existingJobId = this.idempotencyByScope.get(idempotencyKey);
      if (existingJobId) {
        const existing = this.mustGetByScopedId(existingJobId, request);
        return {
          job: existing,
          duplicate: true,
        };
      }

      const timestamp = this.now();
      const jobId = createSendJobId(request.providerId, request.idempotencyKey);
      const job: SendJob = {
        ...request,
        jobId,
        status: 'queued',
        createdAt: timestamp,
        updatedAt: timestamp,
        attempts: 0,
      };

      const scopedId = scopedJobId(jobId, request);
      this.jobByScopeAndId.set(scopedId, job);
      this.jobScopeByJobId.set(jobId, { tenantId: request.tenantId, userId: request.userId });
      this.idempotencyByScope.set(idempotencyKey, jobId);
      try {
        await this.queueAdapter.enqueue(scopedQueueName(request), job);
      } catch (error) {
        this.jobByScopeAndId.delete(scopedId);
        this.jobScopeByJobId.delete(jobId);
        this.idempotencyByScope.delete(idempotencyKey);
        throw error;
      }

      return {
        job,
        duplicate: false,
      };
    });
  }

  get(jobId: string, scope: SendScope): SendJob | undefined {
    assertSendScope(scope);
    const existingScope = this.jobScopeByJobId.get(jobId);
    if (!existingScope) {
      return undefined;
    }

    assertTenantUserAccess(scope, existingScope);
    return this.jobByScopeAndId.get(scopedJobId(jobId, scope));
  }

  list(scope: SendScope): SendJob[] {
    assertSendScope(scope);
    this.cleanupExpiredTerminalJobs();
    const prefix = scopedPrefix(scope);
    return [...this.jobByScopeAndId.entries()]
      .filter(([key]) => key.startsWith(prefix))
      .map(([, value]) => value);
  }

  updateStatus(jobId: string, scope: SendScope, status: SendJobStatus, error?: SendJobError): SendJob {
    const job = this.get(jobId, scope);
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${jobId}`);
    }

    const updated: SendJob = {
      ...job,
      status,
      attempts: job.attempts + 1,
      updatedAt: this.now(),
      lastError: error,
    };

    this.jobByScopeAndId.set(scopedJobId(jobId, scope), updated);
    this.cleanupExpiredTerminalJobs();
    return updated;
  }

  private mustGetByScopedId(jobId: string, scope: SendScope): SendJob {
    const job = this.jobByScopeAndId.get(scopedJobId(jobId, scope));
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${jobId}`);
    }
    return job;
  async processQueuedSend(
    input: {
      jobId: string;
      scope: SendScope;
      transport: SendTransport;
    }
  ): Promise<SendProcessResult> {
    const job = this.queue.get(input.jobId, input.scope);
    if (!job) {
      throw new SendGovernanceError('VALIDATION_ERROR', `send job not found: ${input.jobId}`);
    }
    if (job.status !== 'queued') {
      throw new SendGovernanceError(
        'VALIDATION_ERROR',
        `send job is not queued: ${input.jobId} (${job.status})`
      );
    }

    const providerLimitConfig = {
      requests: 1,
      window: 60000,
    };
    this.queue.updateStatus(job.jobId, input.scope, 'processing');
    try {
      await this.rateLimiter.acquireMany(
        [
          `provider:${job.providerId}`,
          `provider:${job.providerId}:tenant:${job.tenantId}`,
        ],
        providerLimitConfig
      );
    } catch (error) {
      this.queue.updateStatus(job.jobId, input.scope, 'queued');
      throw error;
    }

    try {
      const result = await this.retryMiddleware.execute(
        () =>
          input.transport.send({
            providerId: job.providerId,
            tenantId: job.tenantId,
            userId: job.userId,
            jobId: job.jobId,
            payload: job.payload,
          }),
        `send:${job.jobId}`
      );

      this.queue.updateStatus(job.jobId, input.scope, 'sent');
      return {
        sent: true,
        jobId: job.jobId,
        retries: result.retries,
      };
    } catch (error) {
      if (error instanceof ProviderRateLimitedError) {
        this.queue.updateStatus(job.jobId, input.scope, 'failed', {
          code: 'PROVIDER_RATE_LIMITED',
          message: error.message,
          retryable: false,
        });
        throw new SendGovernanceError('PROVIDER_RATE_LIMITED', error.message);
      }

      this.queue.updateStatus(job.jobId, input.scope, 'failed', {
        code: 'VALIDATION_ERROR',
        message: (error as Error).message,
        retryable: false,
      });
      throw error;
    }
  }

  getQueuedSend(jobId: string, scope: SendScope) {
    return this.queue.get(jobId, scope);
  }

  listQueuedSends(scope: SendScope) {
    return this.queue.list(scope);
  }

  listBlockedDecisions(scope: SendScope): SendBlockedDecision[] {
    return [...(this.blockedByScope.get(scopeKey(scope)) ?? [])];
  }

import type { WebhookEvent, TriggerHandler } from '../types/trigger.js';
import type { Logger } from '../types/action.js';
import { ProviderRegistry } from '../core/provider-registry.js';
import type { WebhookVerificationContext } from '../types/trigger.js';

export class WebhookHandlerError extends Error {
  readonly code:
    | 'WEBHOOK_SECRET_NOT_FOUND'
    | 'WEBHOOK_SIGNATURE_INVALID'
    | 'VALIDATION_ERROR';
  readonly status: number;

  constructor(
    code: 'WEBHOOK_SECRET_NOT_FOUND' | 'WEBHOOK_SIGNATURE_INVALID' | 'VALIDATION_ERROR',
    message: string,
    status = 400
  ) {
    super(message);
    this.name = 'WebhookHandlerError';
    this.code = code;
    this.status = status;
  }
}

export class WebhookHandler {
  private handlers = new Map<string, Set<TriggerHandler>>();
  private processedEventIds = new Map<string, number>();
  private readonly maxProcessedEventIds = 10000;

  constructor(
    private providerRegistry: ProviderRegistry,
    private logger: Logger
  ) {}

  async handleWebhook(
    provider: string,
    event: string,
    payload: any,
    headers: Record<string, string>,
    secret?: string,
    options: {
      rawBody?: Uint8Array;
    } = {}
  ): Promise<WebhookEvent> {
    const prepared = await this.verifyWebhook(provider, event, payload, headers, secret, options);
    const { triggerKey, trigger, transformedPayload, normalizedHeaders, signature, verified } = prepared;

    const webhookEvent: WebhookEvent = {
      id: this.generateEventId(),
      provider,
      event: triggerKey,
      payload: transformedPayload,
      signature,
      receivedAt: new Date(),
      verified,
      headers: normalizedHeaders,
    };

    const eventId = getEventId(transformedPayload, normalizedHeaders);
    const idempotencyKey = eventId ? `${provider}:${eventId}` : null;
    if (idempotencyKey && this.processedEventIds.has(idempotencyKey)) {
      this.logger.info(`Webhook duplicate ignored: ${provider}.${triggerKey}`, { eventId });
      return webhookEvent;
    }

    const triggerEvent = await trigger.handler(transformedPayload);
    await this.emit(provider, triggerKey, { ...triggerEvent, ...webhookEvent });

    if (idempotencyKey) {
      this.rememberProcessedEvent(idempotencyKey);
    }

    this.logger.info(`Webhook handled: ${provider}.${triggerKey}`, { verified, eventId });
    return webhookEvent;
  }

  async verifyWebhook(
    provider: string,
    event: string,
    payload: any,
    headers: Record<string, string>,
    secret?: string,
    options: {
      rawBody?: Uint8Array;
    } = {}
  ): Promise<{
    triggerKey: string;
    trigger: any;
    transformedPayload: any;
    normalizedHeaders: Record<string, string>;
    signature: string;
    verified: boolean;
  }> {
    const providerObj = this.providerRegistry.get(provider);
    if (!providerObj) {
      throw new WebhookHandlerError('VALIDATION_ERROR', `Provider ${provider} not found`, 404);
    }

    const { triggerKey, trigger } = this.resolveTrigger(provider, event, providerObj.triggers ?? {});
    const normalizedHeaders = normalizeHeaders(headers);
    const signature = getSignature(provider, normalizedHeaders);
    const verificationContext: WebhookVerificationContext = {
      rawBody: options.rawBody,
      headers: normalizedHeaders,
    };

    let verified = true;
    if (trigger.webhookConfig?.verifySignature) {
      if (!secret) {
        throw new WebhookHandlerError('WEBHOOK_SECRET_NOT_FOUND', `secret not configured for ${provider}`);
      }

      try {
        verified = await trigger.webhookConfig.verifySignature(
          payload,
          signature,
          secret,
          verificationContext
        );
      } catch (error) {
        this.logger.error(`Webhook signature verification failed for ${provider}.${triggerKey}`, { error });
        throw new WebhookHandlerError('WEBHOOK_SIGNATURE_INVALID', 'signature verification failed');
      }

      if (!verified) {
        throw new WebhookHandlerError('WEBHOOK_SIGNATURE_INVALID', 'signature verification failed');
      }
    }

    const parsedPayload = payload ?? parseWebhookPayload(options.rawBody);
    const transformedPayload = trigger.webhookConfig?.transformPayload
      ? trigger.webhookConfig.transformPayload(parsedPayload)
      : parsedPayload;
    let validatedPayload: unknown;
    try {
      validatedPayload = trigger.schema.parse(transformedPayload);
    } catch {
      throw new WebhookHandlerError('VALIDATION_ERROR', 'webhook payload validation failed');
    }

    return {
      triggerKey,
      trigger,
      transformedPayload: validatedPayload,
      normalizedHeaders,
      signature,
      verified,
    };
  }

  on(provider: string, event: string, handler: TriggerHandler): void {
    const key = `${provider}:${event}`;

    if (!this.handlers.has(key)) {
      this.handlers.set(key, new Set());
    }

    this.handlers.get(key)!.add(handler);
    this.logger.debug(`Handler registered for ${provider}.${event}`);
  }

  off(provider: string, event: string, handler: TriggerHandler): void {
    const key = `${provider}:${event}`;
    const handlers = this.handlers.get(key);

    if (handlers) {
      handlers.delete(handler);

      if (handlers.size === 0) {
        this.handlers.delete(key);
      }
    }
  }

  getHandlerCount(provider?: string, event?: string): number {
    if (provider && event) {
      const key = `${provider}:${event}`;
      return this.handlers.get(key)?.size || 0;
    }

