import { WebhookHandler } from '../src/webhooks/webhook-handler.js';
import { NoopLogger } from '../src/utils/logger.js';

const encoder = new TextEncoder();

describe('raw-body webhook verification', () => {
  it('passes raw bytes from the router to webhook handling before verification', async () => {
    const handleWebhook = vi.fn(async () => ({ id: 'evt_1', verified: true }));
    const router = createPlugFnRouter(createRouterPlugMock(handleWebhook), {
      webhookSecret: {
        github: 'router-secret',
      },
    });
    const rawBody = '{\n  "action":"opened",\n  "issue":{"id":1}\n}';

    const response = await router.handle(
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-hub-signature-256': signRawBody(rawBody, 'router-secret'),
        },
        body: rawBody,
      })
    );

    expect(response.status).toBe(200);
    expect(handleWebhook).toHaveBeenCalledTimes(1);
    expect(handleWebhook.mock.calls[0]?.[0]).toBe('github');
    expect(handleWebhook.mock.calls[0]?.[1]).toBe('issues.opened');
    expect(handleWebhook.mock.calls[0]?.[2]).toBeUndefined();
    expect(decodeBytes(handleWebhook.mock.calls[0]?.[5]?.rawBody)).toBe(rawBody);
  });

  it('falls back to a registered GitHub family trigger for unknown actions', async () => {
    const handleWebhook = vi.fn(async () => ({ id: 'evt_family', verified: true }));
    const router = createPlugFnRouter(createRouterPlugMock(handleWebhook), {
      webhookSecret: { github: 'router-secret' },
    });
    const rawBody = '{"action":"transferred","issue":{"id":1}}';

    const response = await router.handle(
      new Request('http://localhost/webhooks/github', {
        method: 'POST',
        headers: {
          'x-github-event': 'issues',
          'x-hub-signature-256': signRawBody(rawBody, 'router-secret'),
        },
        body: rawBody,
      })
    );

    expect(response.status).toBe(200);
    expect(handleWebhook).toHaveBeenCalledWith(
      'github',
      'issues',
      undefined,
      expect.any(Object),
      'router-secret',
      expect.any(Object)
    );
  });

  it('does not dispatch when another request already claimed the delivery key', async () => {
    const handleWebhook = vi.fn(async () => ({ id: 'evt_duplicate', verified: true }));
    const plug = createRouterPlugMock(handleWebhook);
    plug.runtime.webhooks.createReceipt = vi.fn(async () => ({
      id: 'receipt_existing',
      metadata: { receiptClaimToken: 'claim_from_other_request' },
    }));
    const router = createPlugFnRouter(plug, {
      webhookSecret: { github: 'router-secret' },
    });
    const rawBody = '{"action":"opened","issue":{"id":1}}';

    const response = await router.handle(
      new Request('http://localhost/webhooks/github/issues', {
        method: 'POST',
        headers: {
          'x-github-delivery': 'delivery_1',
          'x-hub-signature-256': signRawBody(rawBody, 'router-secret'),
        },
        body: rawBody,
      })
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({
      data: { duplicate: true, receiptId: 'receipt_existing' },
    });
    expect(handleWebhook).not.toHaveBeenCalled();
  });

  it.each([
    {
      provider: 'github',
      event: 'issues.opened',
      header: 'x-hub-signature-256',
      secret: 'github-secret',
      rawBody:
        '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}',
    },
    {
      provider: 'linear',
      event: 'issue.updated',
      header: 'x-linear-signature',
      secret: 'linear-secret',
      rawBody: '{"action":"update","data":{"id":"issue_1","identifier":"ENG-1","title":"Updated title"}}',
    },
    {
      provider: 'clickup',
      event: 'task.updated',
      event: 'task.updated',
      header: 'x-signature',
      secret: 'clickup-secret',
      rawBody: '{"event":"taskUpdated","task_id":"task_1"}',
    },
    {
      provider: 'gmail',
      event: 'mail.update',
      header: 'x-goog-signature-256',
      secret: 'gmail-secret',
      rawBody: '{"message":{"data":"eyJoaXN0b3J5SWQiOiIxMjMifQ=="}}',
    },
  ])(
    'verifies $provider signatures against raw bytes',
    async ({ provider, event, header, secret, rawBody }) => {
      const webhookHandler = createWebhookHandler();

      const accepted = await webhookHandler.handleWebhook(
        provider,
        event,
        undefined,
        { [header]: signRawBody(rawBody, secret) },
        secret,
        { rawBody: encoder.encode(rawBody) }
      );

      expect(accepted.verified).toBe(true);
    }
  );

  it.each([
    {
      provider: 'github',
      event: 'issues.opened',
      header: 'x-hub-signature-256',
      secret: 'github-secret',
      originalRawBody:
        '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}',
      alteredRawBody:
        '{"repository":{"owner":{"login":"octo"},"name":"repo"},"issue":{"user":{"login":"octo"},"html_url":"https://example.test/issues/10","body":null,"title":"Bug","number":10,"id":1},"action":"opened"}',
    },
    {
      provider: 'linear',
      event: 'issue.updated',
      header: 'x-linear-signature',
      secret: 'linear-secret',
      originalRawBody: '{"action":"update","data":{"id":"issue_1","identifier":"ENG-1","title":"Updated title"}}',
      alteredRawBody: '{"data":{"title":"Updated title","identifier":"ENG-1","id":"issue_1"},"action":"update"}',
    },
    {
      provider: 'clickup',
      event: 'task.updated',
      header: 'x-signature',
      secret: 'clickup-secret',
      originalRawBody: '{"event":"taskUpdated","task_id":"task_1"}',
      alteredRawBody: '{"task_id":"task_1","event":"taskUpdated"}',
    },
    {
      provider: 'gmail',
      event: 'mail.update',
      header: 'x-goog-signature-256',
      secret: 'gmail-secret',
      originalRawBody: '{"message":{"data":"eyJoaXN0b3J5SWQiOiIxMjMifQ=="}}',
      alteredRawBody: '{"message":{"data":"eyJoaXN0b3J5SWQiOiIxMjMifQ=="}, "historyId":"123"}',
    },
  ])(
    'rejects $provider when parsed JSON matches but raw bytes differ',
    async ({ provider, event, header, secret, originalRawBody, alteredRawBody }) => {
      const webhookHandler = createWebhookHandler();

      await expect(
        webhookHandler.handleWebhook(
          provider,
          event,
          undefined,
          { [header]: signRawBody(originalRawBody, secret) },
          secret,
          { rawBody: encoder.encode(alteredRawBody) }
        )
      ).rejects.toMatchObject({
        code: 'WEBHOOK_SIGNATURE_INVALID',
      });
    }
  );

  it('rejects signed payloads that do not satisfy the trigger schema', async () => {
    const webhookHandler = createWebhookHandler();
    const rawBody = '{"action":"opened","issue":{"id":1}}';

    await expect(
      webhookHandler.handleWebhook(
        'github',
        'issues.opened',
        undefined,
        { 'x-hub-signature-256': signRawBody(rawBody, 'github-secret') },
        'github-secret',
        { rawBody: encoder.encode(rawBody) }
      )
    ).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
      message: 'webhook payload validation failed',
    });
  });
});

function createWebhookHandler(): WebhookHandler {
import { createHmac } from 'node:crypto';
import { describe, expect, it, vi } from 'vitest';
import { createPlugFnRouter } from '../../src/router/http-router.js';
import { plugFn } from '../../src/core/plug-fn.js';
import { githubProvider } from '../../../providers/src/github/index.js';
import { MemoryAdapter } from '../../src/storage/adapters/memory.js';

describe('PlugFn webhook verification e2e', () => {
  it('verifies a signed webhook through the router using raw request bytes', async () => {
    const plug = createPlug();
    const handler = vi.fn();
    plug.providers.register(githubProvider);
    plug.webhooks.on('github', 'issues.opened', handler);

    const router = createPlugFnRouter(plug, {
      webhookSecret: {
        github: 'whsec_github',
      },
    });
    const rawBody =
      '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}';

    const response = await router.handle(
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_1',
          'x-hub-signature-256': signRawBody(rawBody, 'whsec_github'),
        },
        body: rawBody,
      })
    );

    expect(response.status).toBe(200);
    const payload = (await response.json()) as {
      ok: boolean;
      data: {
        event: {
          provider: string;
          event: string;
          verified: boolean;
        };
      };
    };

    expect(payload.ok).toBe(true);
    expect(payload.data.event.provider).toBe('github');
    expect(payload.data.event.event).toBe('issues.opened');
    expect(payload.data.event.verified).toBe(true);
    expect(handler).toHaveBeenCalledTimes(1);
    expect(handler.mock.calls[0]?.[0]?.verified).toBe(true);

    const receipt = await plug.runtime.webhooks.findReceiptByIdempotencyKey(
      'github',
      'delivery_1'
    );
    expect(receipt?.verificationStatus).toBe('verified');
  });

  it('resolves canonical GitHub webhook routes to action-specific triggers', async () => {
    const plug = createPlug();
    const handler = vi.fn();
    plug.providers.register(githubProvider);
    plug.webhooks.on('github', 'pull_request.closed', handler);

    const router = createPlugFnRouter(plug, {
      webhookSecret: { github: 'whsec_github' },
    });
    const rawBody = JSON.stringify({
      action: 'closed',
      pull_request: {
        id: 9,
        number: 42,
        title: 'PR title',
        html_url: 'https://example.test/pulls/42',
        merged: true,
      },
      repository: {
        name: 'repo',
        owner: { login: 'octo' },
      },
    });

    const response = await router.handle(
      new Request('http://localhost/webhooks/github', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_action_specific',
          'x-github-event': 'pull_request',
          'x-hub-signature-256': signRawBody(rawBody, 'whsec_github'),
        },
        body: rawBody,
      })
    );

    expect(response.status).toBe(200);
    const payload = (await response.json()) as {
      data: { event: { event: string } };
    };
    expect(payload.data.event.event).toBe('pull_request.closed');
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it('rejects a signature when the signed bytes and transmitted bytes differ', async () => {
    const plug = createPlug();
    plug.providers.register(githubProvider);

    const router = createPlugFnRouter(plug, {
      webhookSecret: {
        github: 'whsec_github',
      },
    });
    const signedBody =
      '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}';
    const transmittedBody =
      '{"repository":{"owner":{"login":"octo"},"name":"repo"},"issue":{"user":{"login":"octo"},"html_url":"https://example.test/issues/10","body":null,"title":"Bug","number":10,"id":1},"action":"opened"}';

    const response = await router.handle(
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_bad',
          'x-hub-signature-256': signRawBody(signedBody, 'whsec_github'),
        },
        body: transmittedBody,
      })
    );

    expect(response.status).toBe(400);
    const payload = (await response.json()) as {
      ok: boolean;
      error: {
        code: string;
      };
    };

    expect(payload.ok).toBe(false);
    expect(payload.error.code).toBe('WEBHOOK_SIGNATURE_INVALID');

    const receipt = await plug.runtime.webhooks.findReceiptByIdempotencyKey(
      'github',
      'delivery_bad'
    );
    expect(receipt?.verificationStatus).toBe('failed');
  });

  it('rejects idempotency key reuse when the payload hash changes', async () => {
    const plug = createPlug();
    const handler = vi.fn();
    plug.providers.register(githubProvider);
    plug.webhooks.on('github', 'issues.opened', handler);

    const router = createPlugFnRouter(plug, {
      webhookSecret: {
        github: 'whsec_github',
      },
    });
    const firstBody =
      '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}';
    const secondBody =
      '{"action":"opened","issue":{"id":2,"number":11,"title":"Different","body":null,"html_url":"https://example.test/issues/11","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}';

    const firstResponse = await router.handle(
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_same',
          'x-hub-signature-256': signRawBody(firstBody, 'whsec_github'),
        },
        body: firstBody,
      })
    );

    const secondResponse = await router.handle(
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_same',
          'x-hub-signature-256': signRawBody(secondBody, 'whsec_github'),
        },
        body: secondBody,
      })
    );

    expect(firstResponse.status).toBe(200);
    expect(secondResponse.status).toBe(409);
    const payload = (await secondResponse.json()) as {
      ok: boolean;
      error: {
        code: string;
      };
    };
    expect(payload.ok).toBe(false);
    expect(payload.error.code).toBe('WEBHOOK_IDEMPOTENCY_CONFLICT');
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it('dispatches concurrent duplicate deliveries only once', async () => {
    const plug = createPlug();
    const handler = vi.fn();
    plug.providers.register(githubProvider);
    plug.webhooks.on('github', 'issues.opened', handler);
    const router = createPlugFnRouter(plug, {
      webhookSecret: { github: 'whsec_github' },
    });
    const rawBody =
      '{"action":"opened","issue":{"id":1,"number":10,"title":"Bug","body":null,"html_url":"https://example.test/issues/10","user":{"login":"octo"}},"repository":{"name":"repo","owner":{"login":"octo"}}}';
    const createRequest = () =>
      new Request('http://localhost/webhooks/github/issues.opened', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-github-delivery': 'delivery_concurrent',
          'x-hub-signature-256': signRawBody(rawBody, 'whsec_github'),
        },
        body: rawBody,
      });

    const responses = await Promise.all([
      router.handle(createRequest()),
      router.handle(createRequest()),
    ]);
    const payloads = await Promise.all(responses.map((response) => response.json())) as Array<{
      data: { duplicate?: boolean };
    }>;

