  private resolveTrigger(
    provider: string,
    incomingEvent: string,
    triggers: Record<string, any>
  ): { triggerKey: string; trigger: any } {
    const canonicalEvent = canonicalizeEvent(incomingEvent);
    const eventMap = new Map<string, string>();

