export type PlugFnOwnerKind = 'user' | 'organization' | 'delegated';

export type PlugFnConnectionOwner =
  | { kind: 'user'; userId: string; tenantId?: string }
  | { kind: 'organization'; organizationId: string; installedByUserId: string; tenantId?: string }
  | {
      kind: 'delegated';
      organizationId: string;
      delegatedToUserId: string;
      installedByUserId: string;
      grants: string[];
      tenantId?: string;
    };

export interface PlugFnActor {
  userId: string;
  tenantId?: string;
  organizationId?: string;
  roles?: string[];
  grants?: string[];
}

export interface PlugFnProviderRuntimeContext {
  provider: string;
  tenantId?: string;
  owner?: PlugFnConnectionOwner;
  actor?: PlugFnActor;
}

export interface PlugFnOAuthClientConfig {
  clientId: string;
  clientSecret: string;
  redirectUris?: string[];
  scopes?: string[];
}

export interface PlugFnSecretResolverConfig {
  resolveOAuthClient(
    context: PlugFnProviderRuntimeContext
  ): Promise<PlugFnOAuthClientConfig | null> | PlugFnOAuthClientConfig | null;
}

export interface PlugFnProviderInstallation {
  id: string;
  provider: string;
  ownerKind: PlugFnOwnerKind;
  ownerId: string;
  tenantId?: string;
  organizationId?: string;
  installedByUserId?: string;
  delegatedToUserId?: string;
  status: 'active' | 'disabled' | 'revoked' | 'error';
  scopes?: string[];
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface PlugFnConnectionGrant {
  id: string;
  connectionId: string;
  granteeUserId: string;
  grant: string;
  createdAt: Date;
  expiresAt?: Date;
}

export interface PlugFnWebhookReceipt {
  id: string;
  provider: string;
  event: string;
  idempotencyKey?: string;
  connectionId?: string;
  ownerKind?: PlugFnOwnerKind;
  ownerId?: string;
  headersRedacted?: Record<string, string>;
  payloadHash: string;
  verificationStatus: 'verified' | 'failed' | 'not-required';
  receivedAt: Date;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

export interface PlugFnWebhookDelivery {
  id: string;
  receiptId: string;
  sinkId?: string;
  handlerName?: string;
  status: 'pending' | 'running' | 'success' | 'failed' | 'dead-lettered';
  attempts: number;
  nextAttemptAt?: Date;
  error?: string;
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface PlugFnSyncJob {
  id: string;
  provider: string;
  connectionId: string;
  resource: string;
  mode: 'full' | 'incremental';
  status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
  ownerKind?: PlugFnOwnerKind;
  ownerId?: string;
  cursor?: string;
  checkpoint?: unknown;
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  error?: string;
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface PlugFnSyncCheckpoint {
  id: string;
  provider: string;
  connectionId: string;
  resource: string;
  checkpoint: unknown;
  updatedAt: Date;
}

export interface PlugFnProviderEvent {
  id: string;
  provider: string;
  event: string;
 * OAuth callback completion result
 */
export interface HandleCallbackResult {
  connection: Connection;
  returnTo?: string;
}

/**
 * List connections options
 */
export interface ListConnectionsOptions {
  userId: string;
  provider?: string;
  status?: ConnectionStatus;
  owner?: PlugFnConnectionOwner;
}

/**
 * Disconnect options
 */
export interface DisconnectOptions {
  userId: string;
  provider: string;
  connectionId?: string;
  owner?: PlugFnConnectionOwner;
  actor?: PlugFnActor;
}

export interface StartConnectionOptions extends GetAuthUrlOptions {}
function assertMatchingWebhookReceipt(
  receipt: PlugFnWebhookReceipt,
  payloadHash: string
): PlugFnWebhookReceipt {
  if (receipt.payloadHash !== payloadHash) {
    throw new Error('webhook idempotency key was reused with a different payload');
  }
  return receipt;
}

export function ownerFields(owner: PlugFnConnectionOwner | undefined): {
  ownerKind?: PlugFnConnectionOwner['kind'];
  ownerId?: string;
  tenantId?: string;
  organizationId?: string;
  installedByUserId?: string;
  delegatedToUserId?: string;
  grants?: string[];
} {
  if (!owner) {
    return {};
  }

  if (owner.kind === 'user') {
    return {
      ownerKind: owner.kind,
      ownerId: owner.userId,
      tenantId: owner.tenantId,
    };
  }

  if (owner.kind === 'organization') {
    return {
      ownerKind: owner.kind,
      ownerId: owner.organizationId,
      tenantId: owner.tenantId,
      organizationId: owner.organizationId,
      installedByUserId: owner.installedByUserId,
    };
  }

  return {
    ownerKind: owner.kind,
    ownerId: owner.organizationId,
    tenantId: owner.tenantId,
    organizationId: owner.organizationId,
    installedByUserId: owner.installedByUserId,
    delegatedToUserId: owner.delegatedToUserId,
    grants: [...owner.grants],
  };
}

function generateId(prefix: string): string {
  const random = Math.random().toString(36).slice(2, 10);
  return `${prefix}_${Date.now().toString(36)}_${random}`;
}

function checkpointId(connectionId: string, resource: string): string {
  return `ckpt_${connectionId}_${resource}`.replace(/[^a-zA-Z0-9_:-]/g, '_');
}

