export class WebhookHandlerError extends Error {
  readonly code:
    | 'WEBHOOK_SECRET_NOT_FOUND'
    | 'WEBHOOK_SIGNATURE_INVALID'
    | 'VALIDATION_ERROR';
  readonly status: number;

  constructor(
