              action: async () => ({}),
            },
            {
              id: 'branch',
              type: 'branch',
              condition: () => true,
              then: [
                {
                  id: 'duplicate',
                  type: 'action',
                  action: async () => ({}),
                },
              ],
            },
          ],
        },
      })
    ).rejects.toMatchObject({
      code: 'WORKFLOW_DEFINITION_INVALID',
      details: { duplicateStepIds: ['duplicate'] },
    });
  });
