"""Action executor for executing provider actions with middleware."""

import asyncio
import time
from collections import deque
from datetime import datetime
from typing import Any, Deque, Dict, List, Optional


class RateLimitExceededError(RuntimeError):
    """Raised when an action exceeds its configured provider quota."""


class InMemoryRateLimiter:
    """Atomic sliding-window limiter shared by an action executor instance."""

    def __init__(self) -> None:
        self._buckets: Dict[str, Deque[float]] = {}
        self._lock = asyncio.Lock()

    async def acquire(self, keys: List[str], requests: int, window_ms: int) -> None:
        if requests <= 0 or window_ms <= 0:
            raise ValueError("rate limit requests and window must be positive")

        now = time.monotonic()
        cutoff = now - (window_ms / 1000)
        async with self._lock:
            buckets = [self._buckets.setdefault(key, deque()) for key in keys]
            for bucket in buckets:
                while bucket and bucket[0] <= cutoff:
                    bucket.popleft()
            if any(len(bucket) >= requests for bucket in buckets):
                raise RateLimitExceededError("provider action rate limit exceeded")
            for bucket in buckets:
                bucket.append(now)


class ActionExecutor:
    """Executes provider actions with retry, rate limiting, and caching."""

    def __init__(
        self,
        connection_manager: Any,
        provider_registry: Any,
        logger: Any,
        enable_retry: bool = True,
        enable_rate_limit: bool = True,
        enable_cache: bool = True,
    ):
        """Initialize action executor.

        Args:
            connection_manager: Connection manager
            provider_registry: Provider registry
            logger: Logger instance
            enable_retry: Enable retry middleware
            enable_rate_limit: Enable rate limiting
            enable_cache: Enable caching
        """
        self.connection_manager = connection_manager
        self.provider_registry = provider_registry
        self.logger = logger
        self.enable_retry = enable_retry
        self.enable_rate_limit = enable_rate_limit
        self.enable_cache = enable_cache
        self._rate_limiter = InMemoryRateLimiter()

        # Store action logs for metrics
        self._action_logs: List[Dict[str, Any]] = []

    async def execute(
        self,
        provider: str,
        action: str,
        user_id: str,
        params: Dict[str, Any],
        connection_id: Optional[str] = None,
        retry: Optional[Dict[str, Any]] = None,
        timeout: Optional[int] = None,
        cache: Optional[bool] = None,
    ) -> Dict[str, Any]:
        """Execute a provider action.

        Args:
            provider: Provider name
            action: Action name
            user_id: User ID
            params: Action parameters
            connection_id: Optional specific connection ID
            retry: Optional retry configuration
            timeout: Optional timeout in seconds
            cache: Optional cache flag

        Returns:
            Action result dict with success, data, error, etc.

        Raises:
            ValueError: If provider or action not found
        """
        start_time = time.time()
        retries = 0

        # Get provider
        provider_obj = self.provider_registry.get_provider(provider)
        if not provider_obj:
            raise ValueError(f"Provider {provider} not found")

        # Get action
        if not hasattr(provider_obj, "actions") or action not in provider_obj.actions:
            raise ValueError(f"Action {action} not found in provider {provider}")

        action_obj = provider_obj.actions[action]

        # Get or select connection
        if connection_id:
            connection = await self.connection_manager.get_connection(connection_id)
            if connection.user_id != user_id:
                raise ValueError("Connection does not belong to user")
            if connection.provider != provider:
                raise ValueError("Connection provider does not match requested provider")
        else:
            # Find active connection for this provider and user
            connections = await self.connection_manager.list_connections(
                user_id, provider
            )
            active_connections = [c for c in connections if c.status == "active"]

            if not active_connections:
                raise ValueError(
                    f"No active connection found for provider {provider} and user {user_id}"
                )

            connection = active_connections[0]

        # Update last used
        await self.connection_manager.update_last_used(connection.id)

        # Get credentials
        credentials = await self.connection_manager.get_credentials(connection.id)

        try:
            if self.enable_rate_limit and provider_obj.rate_limit:
                await self._rate_limiter.acquire(
                    [f"provider:{provider}", f"provider:{provider}:user:{user_id}"],
                    provider_obj.rate_limit["requests"],
                    provider_obj.rate_limit["window"],
                )

            # Execute action (with retry if enabled)
            max_attempts = 1
            if self.enable_retry and retry:
                max_attempts = retry.get("max_attempts", 3)

            last_error = None
            for attempt in range(max_attempts):
                try:
                    # Create action context
                    from ..http.http_client import HttpClient

                    http_client = HttpClient(
                        base_url=provider_obj.base_url,
                        credentials=credentials,
                        auth_type=provider_obj.auth_type,
                        logger=self.logger,
                        timeout=timeout if timeout is not None else 30,
                    )

                    context = ActionContext(
                        user_id=user_id,
                        connection_id=connection.id,
                        provider_name=provider,
                        provider_base_url=provider_obj.base_url,
                        auth_type=provider_obj.auth_type,
                        credentials=credentials,
                        http=http_client,
                        logger=self.logger,
                    )

                    # Execute the action
                    result_data = await action_obj.execute(params, context)

                    # Success!
                    duration = int((time.time() - start_time) * 1000)

                    result = {
                        "success": True,
                        "data": result_data,
                        "error": None,
                        "provider": provider,
                        "action": action,
                        "cached": False,
                        "duration": duration,
                        "retries": retries,
                        "timestamp": datetime.now(),
                    }

                    # Log action
                    self._log_action(result, user_id, connection.id)

                    return result

                except Exception as e:
                    last_error = e
                    retries += 1

                    if attempt < max_attempts - 1:
                        # Wait before retry
                        delay = retry.get("delay", 1000) if retry else 1000
                        backoff = retry.get("backoff", "exponential") if retry else "exponential"

                        if backoff == "exponential":
                            wait_time = (delay / 1000) * (2 ** attempt)
                        else:
                            wait_time = delay / 1000

                        self.logger.warn(
                            f"Action failed, retrying in {wait_time}s",
                            {
                                "provider": provider,
                                "action": action,
                                "attempt": attempt + 1,
                                "error": str(e),
                            },
                        )

                        await asyncio.sleep(wait_time)

            # All retries exhausted
            duration = int((time.time() - start_time) * 1000)

"""Webhook handler for processing provider webhooks."""

import hashlib
import hmac
import json
import time
from typing import Any, Callable, Dict, List, Optional


class WebhookHandlerError(Exception):
    """Deterministic webhook verification error."""

    def __init__(self, code: str, message: str, status: int = 400):
        super().__init__(message)
        self.code = code
        self.status = status


SIGNED_PROVIDERS = {"github", "linear", "slack"}
INVALID_WEBHOOK_SIGNATURE = "Invalid webhook signature"


class WebhookHandler:
    """Handles incoming webhooks from providers."""

    def __init__(self, provider_registry: Any, logger: Any):
        self.provider_registry = provider_registry
        self.logger = logger
        self._handlers: Dict[str, Dict[str, List[Callable]]] = {}

    def register_handler(self, provider: str, event: str, handler: Callable) -> None:
        if provider not in self._handlers:
            self._handlers[provider] = {}
        if event not in self._handlers[provider]:
            self._handlers[provider][event] = []

        self._handlers[provider][event].append(handler)
        self.logger.info(f"Registered webhook handler for {provider}.{event}")

    def unregister_handler(self, provider: str, event: str, handler: Callable) -> None:
        if (
            provider in self._handlers
            and event in self._handlers[provider]
            and handler in self._handlers[provider][event]
        ):
            self._handlers[provider][event].remove(handler)
            self.logger.info(f"Unregistered webhook handler for {provider}.{event}")

    async def handle_webhook(
        self,
        provider: str,
        event: str,
        payload: Optional[Dict[str, Any]],
        headers: Dict[str, str],
        secret: Optional[str] = None,
        raw_body: Optional[bytes] = None,
    ) -> List[Any]:
        provider_obj = self.provider_registry.get_provider(provider)
        if not provider_obj:
            raise WebhookHandlerError("VALIDATION_ERROR", f"Provider {provider} not found", 404)

        normalized_headers = _normalize_headers(headers)
        signed_provider = provider in SIGNED_PROVIDERS
        if signed_provider:
            if not secret:
                raise WebhookHandlerError(
                    "WEBHOOK_SECRET_NOT_FOUND",
                    f"secret not configured for {provider}",
                    400,
                )
            if raw_body is None:
                raise WebhookHandlerError(
                    "WEBHOOK_RAW_BODY_REQUIRED",
                    f"raw request body is required for {provider}",
                    400,
                )
            self._verify_signature(provider, raw_body, normalized_headers, secret)

        parsed_payload = payload if payload is not None else _parse_payload(raw_body)
        handlers = self._handlers.get(provider, {}).get(event, [])
        if not handlers:
            self.logger.warn(f"No handlers registered for {provider}.{event}")
            return []

        results: List[Any] = []
        for handler in handlers:
            try:
                results.append(await handler(parsed_payload))
            except Exception as error:
                self.logger.error(
                    f"Error in webhook handler for {provider}.{event}: {str(error)}",
                    {"error": str(error)},
                )
                results.append({"error": str(error)})

        return results

    def _verify_signature(
        self, provider: str, raw_body: bytes, headers: Dict[str, str], secret: str
    ) -> None:
        if provider == "github":
            _verify_github_signature(raw_body, headers, secret)
        elif provider == "slack":
            _verify_slack_signature(raw_body, headers, secret)
        elif provider == "linear":
            _verify_linear_signature(raw_body, headers, secret)


def _verify_github_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = headers.get("x-hub-signature-256", "")
    if not signature_header:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature header")

    expected_signature = "sha256=" + hmac.new(
        secret.encode("utf-8"), raw_body, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature_header, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _verify_slack_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = headers.get("x-slack-signature", "")
    timestamp = headers.get("x-slack-request-timestamp", "")
    if not signature_header or not timestamp:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature headers")
    try:
        timestamp_value = int(timestamp)
    except (TypeError, ValueError) as error:
        raise WebhookHandlerError(
            "WEBHOOK_SIGNATURE_INVALID", "Invalid request timestamp"
        ) from error
    if abs(time.time() - timestamp_value) > 60 * 5:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Request timestamp too old")

    signature_payload = f"v0:{timestamp}:".encode("utf-8") + raw_body
    expected_signature = "v0=" + hmac.new(
        secret.encode("utf-8"), signature_payload, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature_header, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _verify_linear_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = (
        headers.get("linear-signature", "")
        or headers.get("x-linear-signature", "")
        or headers.get("x-signature", "")
    )
    if not signature_header:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature header")

    expected_signature = hmac.new(
        secret.encode("utf-8"), raw_body, hashlib.sha256
    ).hexdigest()
    normalized_signature = signature_header.removeprefix("sha256=")
    if not hmac.compare_digest(normalized_signature, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _normalize_headers(headers: Dict[str, str]) -> Dict[str, str]:
    normalized: Dict[str, str] = {}
    for key, value in headers.items():
        normalized[key.lower()] = value
    return normalized


def _parse_payload(raw_body: Optional[bytes]) -> Dict[str, Any]:
    if not raw_body:
        return {}

    try:
        parsed = json.loads(raw_body.decode("utf-8"))
    except Exception as error:
        raise WebhookHandlerError("VALIDATION_ERROR", f"invalid webhook payload: {error}") from error

    if not isinstance(parsed, dict):
        raise WebhookHandlerError("VALIDATION_ERROR", "webhook payload must be a JSON object")

    return parsed
