class InMemoryWorkflowStorage implements WorkflowStorage {
  private readonly workflows = new Map<string, Workflow>();
  private readonly executions = new Map<string, WorkflowExecution>();
  private workflowCounter = 0;
  private executionCounter = 0;

  async create(workflow: Omit<Workflow, 'id' | 'createdAt' | 'updatedAt'>): Promise<Workflow> {
    const created: Workflow = {
      ...workflow,
      id: `wf_${++this.workflowCounter}`,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.workflows.set(created.id, created);
    return created;
  }

  async get(id: string): Promise<Workflow | null> {
    return this.workflows.get(id) ?? null;
  }

  async list(userId?: string, status?: WorkflowStatus): Promise<Workflow[]> {
    return [...this.workflows.values()].filter((workflow) => {
      if (userId && workflow.userId !== userId) {
        return false;
      }
      if (status && workflow.status !== status) {
        return false;
      }
      return true;
    });
  }

  async update(id: string, updates: Partial<Workflow>): Promise<Workflow> {
    const current = this.workflows.get(id);
    if (!current) {
      throw new Error(`Workflow ${id} not found`);
    }

    const updated: Workflow = {
      ...current,
      ...updates,
      id: current.id,
      updatedAt: new Date(),
    };
    this.workflows.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<void> {
    this.workflows.delete(id);
  }

  async createExecution(
    execution: Omit<WorkflowExecution, 'id' | 'startedAt'>
  ): Promise<WorkflowExecution> {
    const created: WorkflowExecution = {
      ...execution,
      id: `wfx_${++this.executionCounter}`,
      startedAt: new Date(),
    };
    this.executions.set(created.id, created);
    return created;
  }

  async getExecution(id: string): Promise<WorkflowExecution | null> {
    return this.executions.get(id) ?? null;
  }

  async updateExecution(id: string, updates: Partial<WorkflowExecution>): Promise<void> {
    const current = this.executions.get(id);
    if (!current) {
      throw new Error(`Workflow execution ${id} not found`);
    }

    this.executions.set(id, {
      ...current,
      ...updates,
      id: current.id,
      workflowId: current.workflowId,
      startedAt: current.startedAt,
    });
  }

  async listExecutions(workflowId: string, limit = 50): Promise<WorkflowExecution[]> {
    return [...this.executions.values()]
      .filter((execution) => execution.workflowId === workflowId)
      .sort((left, right) => right.startedAt.getTime() - left.startedAt.getTime())
      .slice(0, limit);
  }

/**
 * Workflow status
 */
export enum WorkflowStatus {
  Enabled = 'enabled',
  Disabled = 'disabled',
  Draft = 'draft',
}

/**
 * Workflow execution status
 */
export enum WorkflowExecutionStatus {
  Pending = 'pending',
  Running = 'running',
  Completed = 'completed',
  Failed = 'failed',
  Cancelled = 'cancelled',
}

/**
 * Workflow definition stored in database
 */
export interface Workflow {
  id: string;
  userId: string;
  name: string;
  description?: string;
  definition: WorkflowDefinition;
  status: WorkflowStatus;
  metadata?: Record<string, any>;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Workflow definition structure
 */
export interface WorkflowDefinition {
  trigger: WorkflowTrigger;
  steps: WorkflowStep[];
  errorHandlers?: WorkflowErrorHandler[];
}

/**
 * Workflow trigger configuration
 */
export interface WorkflowTrigger {
  provider: string;
  event: string;
  filter?: (context: WorkflowContext) => boolean;
}

/**
 * Workflow step types
 */
export type WorkflowStep =
  | ActionStep
  | FilterStep
  | BranchStep
  | ParallelStep
  | DelayStep;

export interface ActionStep {
  type: 'action';
  id: string;
  action: (context: WorkflowContext) => Promise<any>;
}

export interface FilterStep {
  type: 'filter';
  id: string;
  condition: (context: WorkflowContext) => boolean;
}

export interface BranchStep {
  type: 'branch';
  id: string;
  condition: (context: WorkflowContext) => boolean;
  then: WorkflowStep[];
  else?: WorkflowStep[];
}

export interface ParallelStep {
  type: 'parallel';
  id: string;
  actions: Array<(context: WorkflowContext) => Promise<any>>;
}

export interface DelayStep {
  type: 'delay';
  id: string;
  duration: number;
  unit?: 'ms' | 'seconds' | 'minutes' | 'hours' | 'days';
}

/**
 * Workflow execution context
 */
export interface WorkflowContext {
  workflowId: string;
  executionId: string;
  userId: string;
  trigger: {
    provider: string;
    event: string;
    payload: any;
  };
  data: Record<string, any>;
  metadata?: Record<string, any>;
}

/**
 * Error handler
 */
export interface WorkflowErrorHandler {
  stepId?: string;
  handler: (error: Error, context: WorkflowContext) => Promise<void>;
}

/**
 * Workflow execution record
 */
export interface WorkflowExecution {
  id: string;
  workflowId: string;
  status: WorkflowExecutionStatus;
  input?: any;
  output?: any;
  error?: string;
  durationMs?: number;
  startedAt: Date;
  completedAt?: Date;
}

/**
 * Workflow statistics
 */
export interface WorkflowStats {
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  successRate: number;
  avgDuration: number;
  lastExecutedAt?: Date;
}

/**
 * List workflows options
 */
export interface ListWorkflowsOptions {
  userId?: string;
  status?: WorkflowStatus;
  provider?: string;
}

