      ...provider.headers,
    };

    // Add authentication headers based on auth type
    switch (provider.auth.type) {
      case AuthType.OAuth2:
        if (credentials.type === 'oauth2') {
          baseHeaders.Authorization = `Bearer ${credentials.accessToken}`;
        }
        break;

      case AuthType.ApiKey:
