"""Shared adapter helpers for PlugFn web framework integrations."""

from inspect import isawaitable
from typing import Any, Optional


class AdapterSecurityError(Exception):
    """Deterministic adapter-layer security error."""

    def __init__(
        self, code: str, message: str, status_code: int, details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message)
        self.code = code
        self.public_message = message
        self.status_code = status_code
        self.details = details or {}


PUBLIC_ERROR_MESSAGES = {
    "VALIDATION_ERROR": "Invalid request",
    "WEBHOOK_RAW_BODY_REQUIRED": "Raw webhook body is required",
    "WEBHOOK_SECRET_NOT_FOUND": "Webhook secret is not configured",
    "WEBHOOK_SIGNATURE_INVALID": "Webhook signature is invalid",
}


async def resolve_principal(request_obj: Any, plug: Any, auth_override: Optional[Any]) -> dict[str, Any]:
    auth_provider = auth_override or getattr(getattr(plug, "config", None), "auth", None)
    if auth_provider is None:
        raise AdapterSecurityError("PLUGFN_AUTH_REQUIRED", "Authentication is required", 401)

    principal = await invoke_auth_provider(auth_provider, request_obj)
    normalized = normalize_principal(principal)
    if normalized is None:
        raise AdapterSecurityError("PLUGFN_AUTH_REQUIRED", "Authentication is required", 401)
    return normalized


async def invoke_auth_provider(auth_provider: Any, request_obj: Any) -> Any:
    for attribute in ("authenticate", "require_auth", "requireAuth", "get_user_id", "getUserId"):
        method = getattr(auth_provider, attribute, None)
        if callable(method):
            result = method(request_obj)
            return await result if isawaitable(result) else result

    if callable(auth_provider):
        result = auth_provider(request_obj)
        return await result if isawaitable(result) else result

    return None


def normalize_principal(principal: Any) -> Optional[dict[str, Any]]:
    if principal is None:
        return None

    if isinstance(principal, str):
        return {"user_id": principal}

    if isinstance(principal, dict):
        user_id = principal.get("user_id") or principal.get("userId")
        if isinstance(user_id, str) and user_id:
            return {
                "user_id": user_id,
                "tenant_id": principal.get("tenant_id") or principal.get("tenantId"),
            }

    return None


def assert_identity_match(principal: dict[str, Any], requested_user_id: Any) -> None:
    if requested_user_id is None:
        return

    if requested_user_id != principal["user_id"]:
        raise AdapterSecurityError(
            "TENANT_ACCESS_DENIED",
            "Caller identity does not match the authenticated principal",
            403,
            {"userId": principal["user_id"]},
        )


def normalize_scopes(value: Any) -> Optional[list[str]]:
    if value is None:
        return None
    if isinstance(value, list):
        scopes = [scope for scope in value if isinstance(scope, str) and scope]
        return scopes or None
    if isinstance(value, str):
        scopes = [scope.strip() for scope in value.split(",") if scope.strip()]
        return scopes or None
    return None


def resolve_webhook_secret(plug: Any, provider: str) -> Optional[str]:
    connection_manager = getattr(plug, "_connection_manager", None)
    if connection_manager and hasattr(connection_manager, "resolve_webhook_secret"):
        secret = connection_manager.resolve_webhook_secret(provider)
        return secret if isinstance(secret, str) and secret else None

    integrations = getattr(getattr(plug, "config", None), "integrations", {}) or {}
    provider_config = integrations.get(provider, {})
    for key in ("webhook_secret", "signing_secret", "webhookSigningSecret", "signingSecret"):
        value = provider_config.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def normalize_headers(headers: dict[str, Any]) -> dict[str, str]:
    normalized: dict[str, str] = {}
    for key, value in headers.items():
        if isinstance(value, str):
            normalized[key.lower()] = value
    return normalized


def success_payload(data: dict[str, Any]) -> dict[str, Any]:
    return {"ok": True, "data": data}


def error_payload(error: Exception) -> tuple[dict[str, Any], int]:
    if isinstance(error, AdapterSecurityError):
        return (
            {
                "ok": False,
                "error": {
                    "code": error.code,
                    "message": error.public_message,
                    "status": error.status_code,
                    "details": error.details,
                },
            },
            error.status_code,
        )

    error_code = getattr(error, "code", None)
    if error_code not in PUBLIC_ERROR_MESSAGES:
        return (
            {
                "ok": False,
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "An internal error occurred",
                    "status": 500,
                    "details": {},
                },
            },
            500,
        )

    raw_status = getattr(error, "status", 400)
    status_code = raw_status if isinstance(raw_status, int) and 400 <= raw_status <= 599 else 400
    return (
        {
            "ok": False,
            "error": {
                "code": error_code,
                "message": PUBLIC_ERROR_MESSAGES[error_code],
                "status": status_code,
                "details": {},
            },
        },
        status_code,
    )
"""Webhook handler for processing provider webhooks."""

import hashlib
import hmac
import json
import time
from typing import Any, Callable, Dict, List, Optional


class WebhookHandlerError(Exception):
    """Deterministic webhook verification error."""

    def __init__(self, code: str, message: str, status: int = 400):
        super().__init__(message)
        self.code = code
        self.status = status


SIGNED_PROVIDERS = {"github", "linear", "slack"}
INVALID_WEBHOOK_SIGNATURE = "Invalid webhook signature"


class WebhookHandler:
    """Handles incoming webhooks from providers."""

    def __init__(self, provider_registry: Any, logger: Any):
        self.provider_registry = provider_registry
        self.logger = logger
        self._handlers: Dict[str, Dict[str, List[Callable]]] = {}

    def register_handler(self, provider: str, event: str, handler: Callable) -> None:
        if provider not in self._handlers:
            self._handlers[provider] = {}
        if event not in self._handlers[provider]:
            self._handlers[provider][event] = []

        self._handlers[provider][event].append(handler)
        self.logger.info(f"Registered webhook handler for {provider}.{event}")

    def unregister_handler(self, provider: str, event: str, handler: Callable) -> None:
        if (
            provider in self._handlers
            and event in self._handlers[provider]
            and handler in self._handlers[provider][event]
        ):
            self._handlers[provider][event].remove(handler)
            self.logger.info(f"Unregistered webhook handler for {provider}.{event}")

    async def handle_webhook(
        self,
        provider: str,
        event: str,
        payload: Optional[Dict[str, Any]],
        headers: Dict[str, str],
        secret: Optional[str] = None,
        raw_body: Optional[bytes] = None,
    ) -> List[Any]:
        provider_obj = self.provider_registry.get_provider(provider)
        if not provider_obj:
            raise WebhookHandlerError("VALIDATION_ERROR", f"Provider {provider} not found", 404)

        normalized_headers = _normalize_headers(headers)
        signed_provider = provider in SIGNED_PROVIDERS
        if signed_provider:
            if not secret:
                raise WebhookHandlerError(
                    "WEBHOOK_SECRET_NOT_FOUND",
                    f"secret not configured for {provider}",
                    400,
                )
            if raw_body is None:
                raise WebhookHandlerError(
                    "WEBHOOK_RAW_BODY_REQUIRED",
                    f"raw request body is required for {provider}",
                    400,
                )
            self._verify_signature(provider, raw_body, normalized_headers, secret)

        parsed_payload = payload if payload is not None else _parse_payload(raw_body)
        handlers = self._handlers.get(provider, {}).get(event, [])
        if not handlers:
            self.logger.warn(f"No handlers registered for {provider}.{event}")
            return []

        results: List[Any] = []
        failures: List[Exception] = []
        for handler in handlers:
            try:
                results.append(await handler(parsed_payload))
            except Exception as error:
                self.logger.error(
                    f"Error in webhook handler for {provider}.{event}: {str(error)}",
                    {"error": str(error)},
                )
                failures.append(error)

        if failures:
            raise WebhookHandlerError(
                "WEBHOOK_HANDLER_FAILED", "Webhook handler failed", 503
            ) from failures[0]

        return results

    def _verify_signature(
        self, provider: str, raw_body: bytes, headers: Dict[str, str], secret: str
    ) -> None:
        if provider == "github":
            _verify_github_signature(raw_body, headers, secret)
        elif provider == "slack":
            _verify_slack_signature(raw_body, headers, secret)
        elif provider == "linear":
            _verify_linear_signature(raw_body, headers, secret)


def _verify_github_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = headers.get("x-hub-signature-256", "")
    if not signature_header:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature header")

    expected_signature = "sha256=" + hmac.new(
        secret.encode("utf-8"), raw_body, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature_header, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _verify_slack_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = headers.get("x-slack-signature", "")
    timestamp = headers.get("x-slack-request-timestamp", "")
    if not signature_header or not timestamp:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature headers")
    try:
        timestamp_value = int(timestamp)
    except (TypeError, ValueError) as error:
        raise WebhookHandlerError(
            "WEBHOOK_SIGNATURE_INVALID", "Invalid request timestamp"
        ) from error
    if abs(time.time() - timestamp_value) > 60 * 5:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Request timestamp too old")

    signature_payload = f"v0:{timestamp}:".encode("utf-8") + raw_body
    expected_signature = "v0=" + hmac.new(
        secret.encode("utf-8"), signature_payload, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature_header, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _verify_linear_signature(
    raw_body: bytes, headers: Dict[str, str], secret: str
) -> None:
    signature_header = (
        headers.get("linear-signature", "")
        or headers.get("x-linear-signature", "")
        or headers.get("x-signature", "")
    )
    if not signature_header:
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", "Missing signature header")

    expected_signature = hmac.new(
        secret.encode("utf-8"), raw_body, hashlib.sha256
    ).hexdigest()
    normalized_signature = signature_header.removeprefix("sha256=")
    if not hmac.compare_digest(normalized_signature, expected_signature):
        raise WebhookHandlerError("WEBHOOK_SIGNATURE_INVALID", INVALID_WEBHOOK_SIGNATURE)


def _normalize_headers(headers: Dict[str, str]) -> Dict[str, str]:
    normalized: Dict[str, str] = {}
    for key, value in headers.items():
        normalized[key.lower()] = value
    return normalized


def _parse_payload(raw_body: Optional[bytes]) -> Dict[str, Any]:
    if not raw_body:
        return {}

    try:
        parsed = json.loads(raw_body.decode("utf-8"))
    except Exception as error:
        raise WebhookHandlerError("VALIDATION_ERROR", f"invalid webhook payload: {error}") from error

    if not isinstance(parsed, dict):
        raise WebhookHandlerError("VALIDATION_ERROR", "webhook payload must be a JSON object")

    return parsed
