}

/**
 * Cache configuration
 */
export interface CacheOptions {
  ttl?: number;
  key?: string;
}

/**
 * Action execution result
 */
export interface ActionResult<T = any> {
  success: boolean;
  data?: T;
  error?: Error;
  provider: string;
  action: string;
  cached?: boolean;
  duration: number;
  retries: number;
  timestamp: Date;
}

