  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(rawBody)) as Record<string, unknown>;
    const message = payload.message;
    return (
      typeof message === 'object' &&
      message !== null &&
      typeof (message as Record<string, unknown>).data === 'string'
    );
  } catch {
    return false;
  }
