export class ConnectionSelectionError extends Error {
  readonly code = 'CONNECTION_AMBIGUOUS';
  readonly status = 409;

  constructor(message = 'multiple active connections require explicit connectionId') {
    super(message);
    this.name = 'ConnectionSelectionError';
  }
}

