export class ConnectionError extends AdapterError {
  public override readonly name = 'ConnectionError';

  constructor(message: string, options?: AdapterErrorOptions) {
    super(AdapterErrorCode.CONNECTION_FAILED, message, {
      ...options,
      severity: 'fatal',
      retryable: true,
    });
  }
}

