      enableRetry?: boolean;
      enableRateLimit?: boolean;
      enableCache?: boolean;
      enableLogging?: boolean;
      enableMetrics?: boolean;
      maxConcurrentSyncPerConnection?: number;
      database?: DbAdapter;
      cacheStore?: KVStoreAdapter;
      cacheTtl?: number;
