  /**
   * Execute an action
   */
  async execute<T>(
    provider: string,
    action: string,
    options: ActionOptions
  ): Promise<ActionResult<T>> {
    const startTime = Date.now();
    let retries = 0;
    let cached = false;

    try {
      // Get provider
      const providerObj = this.providerRegistry.get(provider);
      if (!providerObj) {
        throw new Error(`Provider ${provider} not found`);
      }

      // Get action
      const actionObj = providerObj.actions[action];
      if (!actionObj) {
        throw new Error(`Action ${action} not found in provider ${provider}`);
      }

      // Validate parameters
      const validatedParams = actionObj.parameters.parse(options.params);
      const shouldUseCache =
        this.enableCache &&
        options.cache !== false &&
        (options.cache !== undefined || actionObj.cacheable === true);

      // Get or select connection
      const connection = await this.connectionManager.resolveConnectionForAction({
        userId: options.userId,
        provider,
        connectionId: options.connectionId,
      });

      if (!connection) {
        throw new Error(`No connection found for provider ${provider} and user ${options.userId}`);
      }

      const cacheKey = shouldUseCache
        ? typeof options.cache === 'object' && options.cache.key
          ? options.cache.key
          : this.cacheMiddleware.generateKey(
              provider,
              action,
              validatedParams,
              options.userId,
              connection.id
            )
        : undefined;

      // Check cache only after resolving the concrete connection.
      if (cacheKey) {
        const cachedResult = await this.cacheMiddleware.getEntry<T>(cacheKey);
        if (cachedResult.hit) {
          this.logger.debug(`Cache hit for ${provider}.${action}`);

          return {
            success: true,
            data: cachedResult.data,
            provider,
            action,
            cached: true,
            duration: Date.now() - startTime,
            retries: 0,
            timestamp: new Date(),
          };
        }
      }

      // Get credentials
      const credentials = await this.connectionManager.getCredentials(connection.id);

      // Apply rate limiting
      const acquireRateLimit = () =>
        this.acquireRateLimits(providerObj, provider, options.userId);

      // Build action context
      const context: ActionContext = {
        userId: options.userId,
        connectionId: connection.id,
        provider: {
          name: providerObj.name,
          baseUrl: providerObj.baseUrl,
        },
        auth: {
          type: providerObj.auth.type,
          credentials,
        },
        http: this.createAuthenticatedHttpClient(
          providerObj,
          credentials,
          options.timeout,
          acquireRateLimit
        ),
        logger: this.logger,
        acquireRateLimit,
      };

      // Execute action with retry
      const executeAction = async () => {
        return actionObj.execute(validatedParams, context);
      };

      const result = await this.executeWithSyncConcurrencyGuard(action, connection.id, async () => {
        if (!this.enableRetry) {
          return { data: await executeAction(), retries: 0 };
        }
        return this.retryMiddleware.execute(
          executeAction,
          `${provider}.${action}`,
          options.retry ?? (actionObj.idempotent === true ? {} : { maxAttempts: 1 })
        );
      });

      retries = result.retries;
      const data = result.data;

      // Validate response
      const validatedData = actionObj.returns.parse(data);

      // Cache result
      if (cacheKey) {
        const ttl = typeof options.cache === 'object' ? options.cache.ttl : undefined;
        await this.cacheMiddleware.set(cacheKey, validatedData, ttl);
      }

      // Mark connection as used
      await this.connectionManager.markUsed(connection.id);

      // Log success
      const duration = Date.now() - startTime;
      if (this.enableLogging) {
        this.loggingMiddleware.logActionSuccess(provider, action, duration, cached, options.userId);
        await this.loggingMiddleware.persistActionLog({
          provider,
          action,
          userId: options.userId,
          connectionId: connection.id,
      ConnectionStatus.Active
    );

    if (activeConnections.length === 0) {
      return null;
    }

    if (activeConnections.length === 1) {
      return activeConnections[0];
    }

    const sortedConnections = [...activeConnections].sort(compareConnectionPriority);
    if (compareConnectionPriority(sortedConnections[0], sortedConnections[1]) === 0) {
      throw new ConnectionSelectionError();
    }

    return sortedConnections[0];
  }

  async disconnect(options: DisconnectOptions): Promise<DisconnectResult> {
    const startedAt = Date.now();
    const targetConnection = options.connectionId
      ? await this.connectionStorage.get(options.connectionId)
      : await this.connectionStorage.getByUserAndProvider(options.userId, options.provider);

    if (!targetConnection) {
      return {
        disconnected: false,
        remoteRevokeAttempted: false,
        remoteRevokeSucceeded: false,
        localDeleted: false,
        connectionDeleted: false,
      };
    }

    if (targetConnection.provider !== options.provider) {
      throw new ConnectionResolutionError(
        'VALIDATION_ERROR',
        'connection provider mismatch',
        400
      );
    }

    const actor = options.actor ?? { userId: options.userId };
    if (
      actor.userId !== options.userId ||
      !tenantMatches(targetConnection.tenantId, actor.tenantId) ||
      !connectionMatchesActor(targetConnection, actor)
    ) {
      throw new ConnectionResolutionError(
        'TENANT_ACCESS_DENIED',
        'connection owner mismatch',
        403
      );
    }

    if (options.owner) {
      const expected = ownerFields(options.owner);
      if (
        targetConnection.ownerKind &&
        (targetConnection.ownerKind !== expected.ownerKind ||
          targetConnection.ownerId !== expected.ownerId ||
          !tenantMatches(targetConnection.tenantId, expected.tenantId))
      ) {
        throw {
          code: 'TENANT_ACCESS_DENIED',
          message: 'connection owner mismatch',
          status: 403,
        };
      }
    }

    const provider = this.providers.get(targetConnection.provider);
    if (!provider || provider.auth.type !== AuthType.OAuth2) {
      await this.connectionStorage.delete(targetConnection.id);
      const result: DisconnectResult = {
        disconnected: true,
        connectionId: targetConnection.id,
        remoteRevokeAttempted: false,
        remoteRevokeSucceeded: false,
        localDeleted: true,
        connectionDeleted: true,
      };
      this.logger.info(`Connection deleted: ${targetConnection.id}`);
      await this.persistDisconnectActionLog(options.userId, targetConnection, result, startedAt);
      return result;
  }
}

function connectionBelongsToUser(connection: Connection, userId: string): boolean {
  if (connection.userId === userId) {
    return true;
  }

  if (connection.ownerKind === 'user' && connection.ownerId === userId) {
    return true;
  }

  if (connection.ownerKind === 'organization' && connection.installedByUserId === userId) {
    return true;
  }

  if (connection.ownerKind === 'delegated' && connection.delegatedToUserId === userId) {
    return true;
  }

  return false;
}

function connectionMatchesActor(
  connection: Connection,
  actor: NonNullable<DisconnectOptions['actor']>
): boolean {
  if (
    connection.userId === actor.userId ||
    (connection.ownerKind === 'user' && connection.ownerId === actor.userId)
  ) {
    return true;
  }

  if (connection.ownerKind === 'organization') {
    return (
      connection.installedByUserId === actor.userId ||
      (Boolean(connection.organizationId) &&
        Boolean(actor.organizationId) &&
        connection.organizationId === actor.organizationId &&
        hasAny(actor.roles, ['admin', 'owner', 'org:admin']))
    );
  }

  if (connection.ownerKind === 'delegated') {
    return (
      connection.delegatedToUserId === actor.userId ||
      connection.installedByUserId === actor.userId ||
      hasAny(actor.grants, connection.grants ?? [])
    );
  }

  return false;
}

