actions: {
  // List repositories available to the authenticated user
  "repos.list": {
    name: "repos.list",
    displayName: "List Repositories",
    description: "List repositories available to the authenticated user",

    parameters: z.object({
      visibility: z
        .enum(["all", "public", "private"])
        .optional()
        .default("all"),
      affiliation: z
        .array(z.enum(["owner", "collaborator", "organization_member"]))
        .optional(),
      sort: z
        .enum(["created", "updated", "pushed", "full_name"])
        .optional()
        .default("updated"),
      direction: z.enum(["asc", "desc"]).optional().default("desc"),
      maxPages: z.number().int().min(1).max(100).optional().default(100),
    }),

    returns: z.array(
      z
        .object({
          id: z.number(),
          name: z.string(),
          full_name: z.string(),
          private: z.boolean(),
          html_url: z.string(),
          description: z.string().nullable(),
          default_branch: z.string(),
          archived: z.boolean().optional(),
          disabled: z.boolean().optional(),
          pushed_at: z.string().nullable().optional(),
          updated_at: z.string().optional(),
          owner: z.object({
            login: z.string(),
            avatar_url: z.string().optional(),
          }),
          permissions: z
            .object({
              admin: z.boolean(),
              maintain: z.boolean().optional(),
              push: z.boolean(),
              triage: z.boolean().optional(),
              pull: z.boolean(),
            })
            .optional(),
        })
        .passthrough(),
    ),

    execute: async (params: any, context: ActionContext) => {
      const queryParams: Record<string, unknown> = {
        visibility: params.visibility ?? "all",
        sort: params.sort ?? "updated",
        direction: params.direction ?? "desc",
        per_page: 100,
      };
      if (params.affiliation?.length)
        queryParams.affiliation = params.affiliation.join(",");
      const rows: any[] = [];
      for (let page = 1; page <= (params.maxPages ?? 100); page += 1) {
        const response = await context.http.get(
          `${context.provider.baseUrl}/user/repos`,
          {
            params: { ...queryParams, page },
          },
        );
        const pageRows = Array.isArray(response.data) ? response.data : [];
        rows.push(...pageRows);
        if (pageRows.length < 100) break;
      }
      return rows;
    },
  },

  // Get repository
  "repos.get": {
    name: "repos.get",
    displayName: "Get Repository",
    description: "Get a repository by owner and name",

    parameters: z.object({
      owner: z.string().describe("Repository owner"),
      repo: z.string().describe("Repository name"),
    }),

    returns: z.object({
      id: z.number(),
      name: z.string(),
      full_name: z.string(),
      description: z.string().nullable(),
      html_url: z.string(),
      clone_url: z.string(),
      default_branch: z.string(),
      stargazers_count: z.number(),
      watchers_count: z.number(),
      forks_count: z.number(),
    }),

    execute: async (params: any, context: ActionContext) => {
      const response = await context.http.get(
        `${context.provider.baseUrl}/repos/${params.owner}/${params.repo}`,
      );
      return response.data;
    },
  },

  // List issues
  "issues.list": {
    name: "issues.list",
    displayName: "List Issues",
    description: "List issues for a repository",

    parameters: z.object({
      owner: z.string().describe("Repository owner"),
      repo: z.string().describe("Repository name"),
      state: z
        .enum(["open", "closed", "all"])
        .optional()
        .describe("Issue state"),
      labels: z.array(z.string()).optional().describe("Filter by labels"),
      maxPages: z
        .number()
        .int()
        .min(1)
        .max(100)
        .optional()
        .default(100)
        .describe("Maximum 100-item pages to fetch"),
    }),

    returns: z.array(
      z
        .object({
        id: z.number(),
        number: z.number(),
        title: z.string(),
        body: z.string().nullable(),
        state: z.string(),
        html_url: z.string(),
        user: z.object({
          login: z.string(),
          avatar_url: z.string(),
        }),
        labels: z.array(
          z.object({
          z.object({
            name: z.string(),
            color: z.string(),
            }),
        ),
        created_at: z.string(),
        updated_at: z.string(),
          closed_at: z.string().nullable().optional(),
          comments: z.number().optional(),
          assignees: z
            .array(z.object({ login: z.string(), avatar_url: z.string() }))
            .optional(),
          milestone: z
            .object({
              id: z.number(),
              number: z.number(),
              title: z.string(),
              description: z.string().nullable(),
              due_on: z.string().nullable(),
            })
            .nullable()
            .optional(),
          pull_request: z
            .object({
              url: z.string(),
              html_url: z.string().optional(),
              diff_url: z.string().optional(),
              patch_url: z.string().optional(),
      })
            .optional(),
        })
        .passthrough(),
    ),

    execute: async (params: any, context: ActionContext) => {
      const queryParams: any = {};
      if (params.state) queryParams.state = params.state;
      if (params.labels) queryParams.labels = params.labels.join(",");

      queryParams.per_page = 100;
      const rows: any[] = [];
      for (let page = 1; page <= (params.maxPages ?? 100); page += 1) {
      const response = await context.http.get(
        `${context.provider.baseUrl}/repos/${params.owner}/${params.repo}/issues`,
          { params: { ...queryParams, page } },
      );
        const pageRows = Array.isArray(response.data) ? response.data : [];
        rows.push(...pageRows);
        if (pageRows.length < 100) break;
      }
      return rows;
    },
  },

  // Get issue
  "issues.get": {
    name: "issues.get",
    displayName: "Get Issue",
    description: "Get a single issue by number",

    parameters: z.object({
      owner: z.string().describe("Repository owner"),
      repo: z.string().describe("Repository name"),
      issueNumber: z.number().describe("Issue number"),
    }),

    returns: z.object({
      id: z.number(),
      number: z.number(),
      title: z.string(),
      body: z.string().nullable(),
      state: z.enum(["open", "closed"]).or(z.string()),
      html_url: z.string(),
    }),

    execute: async (params: any, context: ActionContext) => {
      const response = await context.http.get(
        `${context.provider.baseUrl}/repos/${params.owner}/${params.repo}/issues/${params.issueNumber}`,
      );
      return response.data;
    },
  },

  // Create issue
  "issues.create": {
    name: "issues.create",
    displayName: "Create Issue",
    description: "Create a new issue in a repository",

    parameters: z.object({
      owner: z.string().describe("Repository owner"),
      repo: z.string().describe("Repository name"),
      title: z.string().describe("Issue title"),
      body: z.string().optional().describe("Issue body"),
      labels: z.array(z.string()).optional().describe("Issue labels"),
      assignees: z.array(z.string()).optional().describe("Assignees"),
    }),

    returns: z.object({
      id: z.number(),
      number: z.number(),
      title: z.string(),
      body: z.string().nullable(),
      html_url: z.string(),
      state: z.string(),
      created_at: z.string(),
    }),

    execute: async (params: any, context: ActionContext) => {
      const response = await context.http.post(
        `${context.provider.baseUrl}/repos/${params.owner}/${params.repo}/issues`,
        {
          title: params.title,
          body: params.body,
          labels: params.labels,
          assignees: params.assignees,
        },
      );

      return response.data;
    },
  },

  // Update issue
  "issues.update": {
    name: "issues.update",
    displayName: "Update Issue",
    description: "Update an existing issue in a repository",

