  payload: unknown,
  expectedClientState: string
): boolean {
  if (!payload || typeof payload !== 'object' || !expectedClientState) {
    return false;
  }

  const entries = (payload as Record<string, unknown>).value;
  if (!Array.isArray(entries) || entries.length === 0) {
    return false;
