      accessToken: tokenSet.accessToken,
      refreshToken: tokenSet.refreshToken,
      expiresAt: tokenSet.expiresAt ? new Date(tokenSet.expiresAt) : undefined,
      tokenType: tokenSet.tokenType,
      scope: tokenSet.scope,
    };
  }

