      | 'VALIDATION_ERROR'
      | 'OAUTH_SCOPE_DISALLOWED'
      | 'MAIL_SYNC_CHECKPOINT_INVALID'
      | 'PROVIDER_POLICY_BLOCKED',
    message: string
  ) {
    super(message);
