import { z } from 'zod';

/**
 * Trigger type
 */
export enum TriggerType {
  Webhook = 'webhook',
  Polling = 'polling',
}

/**
 * Webhook configuration
 */
export interface WebhookVerificationContext {
  rawBody?: Uint8Array;
  headers: Record<string, string>;
}

export interface WebhookConfig {
  path: string;
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  verifySignature?: (
    payload: any,
    signature: string,
    secret: string,
    context: WebhookVerificationContext
  ) => Promise<boolean> | boolean;
  transformPayload?: (payload: any) => any;
  shouldDispatch?: (payload: any) => boolean;
}

/**
 * Polling configuration
 */
export interface PollingConfig {
  interval: number; // milliseconds
  action: string;
  compareField?: string;
}

/**
 * Trigger definition
 */
export interface Trigger<TPayload = any> {
  name: string;
  displayName: string;
  description: string;
  type: TriggerType;
  webhookConfig?: WebhookConfig;
  pollingConfig?: PollingConfig;
  schema: z.ZodSchema<TPayload>;
  handler: (payload: any) => Promise<TriggerEvent<TPayload>>;
}

/**
 * Webhook event
 */
export interface WebhookEvent {
  id: string;
  provider: string;
  event: string;
  payload: any;
  signature?: string;
  receivedAt: Date;
  verified: boolean;
  userId?: string;
  connectionId?: string;
  headers?: Record<string, string>;
}

/**
 * Trigger event emitted to handlers
 */
export interface TriggerEvent<TPayload = any> {
  event: string;
  data: TPayload;
  metadata?: Record<string, any>;
}

/**
 * Trigger handler function
 */
export type TriggerHandler<TPayload = any> = (
  event: TriggerEvent<TPayload> & WebhookEvent
) => Promise<void> | void;

/**
 * Polling trigger options
 */
export interface PollingTriggerOptions {
  provider: string;
  action: string;
  interval: number;
  params: Record<string, any>;
  onChange: (newItems: any[], prevItems: any[]) => Promise<void>;
  compareField?: string;
}
import type { Action } from './action.js';
import type { Trigger } from './trigger.js';
import type { PlugFnConnectionOwner, PlugFnPersistenceSink } from './runtime.js';

/**
 * Authentication types supported by providers
 */
export enum AuthType {
  OAuth2 = 'oauth2',
  ApiKey = 'api-key',
  JWT = 'jwt',
  Basic = 'basic',
  None = 'none',
}

/**
 * OAuth 2.0 configuration
 */
export interface OAuth2Config {
  authorizationUrl: string;
  tokenUrl: string;
  scopes: string[];
  scopeSeparator?: string;
  getAuthParams?: (config: OAuth2RuntimeConfig) => Record<string, string>;
  getTokenParams?: (config: OAuth2RuntimeConfig, code: string) => Record<string, any>;
  refreshToken?: (config: OAuth2RuntimeConfig, refreshToken: string) => Promise<TokenResponse>;
}

export interface OAuth2RuntimeConfig {
  clientId: string;
  clientSecret: string;
  redirectUri: string;
  scopes: string[];
  state?: string;
}

export interface TokenResponse {
  access_token: string;
  refresh_token?: string;
  expires_in?: number;
  token_type?: string;
  scope?: string;
}

/**
 * API Key configuration
 */
export interface ApiKeyConfig {
  headerName?: string;
  paramName?: string;
  prefix?: string;
}

/**
 * JWT configuration
 */
export interface JWTConfig {
  algorithm: string;
  publicKey?: string;
  privateKey?: string;
  issuer?: string;
  audience?: string;
}

/**
 * Basic Auth configuration
 */
export interface BasicAuthConfig {
  usernameField?: string;
  passwordField?: string;
}

/**
 * Authentication configuration union
 */
export type AuthConfig =
  | { type: AuthType.OAuth2; config: OAuth2Config }
  | { type: AuthType.ApiKey; config: ApiKeyConfig }
  | { type: AuthType.JWT; config: JWTConfig }
  | { type: AuthType.Basic; config: BasicAuthConfig }
  | { type: AuthType.None; config?: never };

/**
 * Rate limit configuration
 */
export interface RateLimitConfig {
  requests: number;
  window: number; // milliseconds
  strategy?: 'sliding' | 'fixed';
}

/**
 * Provider metadata and configuration
 */
export interface Provider<TActions extends Record<string, Action<any, any>> = any> {
  name: string;
  displayName: string;
  version: string;
  description: string;
  iconUrl?: string;
  auth: AuthConfig;
  baseUrl: string;
  actions: TActions;
  triggers?: Record<string, Trigger<any>>;
  rateLimit?: RateLimitConfig;
  headers?: Record<string, string>;
  transformRequest?: (request: any) => any;
  transformResponse?: (response: any) => any;
  webhooks?: PlugFnWebhookDefinition[];
  sync?: Record<string, PlugFnSyncResourceDefinition<any, any>>;
  capabilities?: PlugFnProviderCapabilities;
  defaultPolicies?: PlugFnProviderPolicy[];
}

export type PlugFnProviderDefinition<
  TActions extends Record<string, Action<any, any>> = Record<string, Action<any, any>>,
> = Provider<TActions> & {
  id?: string;
};

