export interface PlugFnWebhookReceipt {
  id: string;
  provider: string;
  event: string;
  idempotencyKey?: string;
  connectionId?: string;
  ownerKind?: PlugFnOwnerKind;
  ownerId?: string;
  headersRedacted?: Record<string, string>;
  payloadHash: string;
  verificationStatus: 'verified' | 'failed' | 'not-required';
  receivedAt: Date;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

export interface PlugFnWebhookDelivery {
  id: string;
  receiptId: string;
  sinkId?: string;
  handlerName?: string;
  status: 'pending' | 'running' | 'success' | 'failed' | 'dead-lettered';
  attempts: number;
  nextAttemptAt?: Date;
  error?: string;
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

export interface PlugFnSyncJob {
  id: string;
  provider: string;
  connectionId: string;
  resource: string;
  mode: 'full' | 'incremental';
  status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
  ownerKind?: PlugFnOwnerKind;
  ownerId?: string;
  cursor?: string;
  checkpoint?: unknown;
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  error?: string;
  metadata?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
  }

  updateWebhookReceipt(
    id: string,
    updates: Partial<PlugFnWebhookReceipt>
  ): Promise<PlugFnWebhookReceipt> {
    return this.adapter.updateWebhookReceipt(id, {
      ...updates,
      metadata: {
        ...(updates.metadata ?? {}),
        updatedAt: new Date().toISOString(),
      },
    });
  }

  createWebhookDelivery(input: CreateWebhookDeliveryInput): Promise<PlugFnWebhookDelivery> {
    const now = new Date();
    return this.adapter.createWebhookDelivery({
      id: generateId('whdel'),
      receiptId: input.receiptId,
      sinkId: input.sinkId,
      handlerName: input.handlerName,
      status: input.status ?? 'pending',
      attempts: 0,
      nextAttemptAt: input.nextAttemptAt,
      metadata: input.metadata,
      createdAt: now,
      updatedAt: now,
    });
  }

  updateWebhookDelivery(
    id: string,
    updates: Partial<PlugFnWebhookDelivery>
  ): Promise<PlugFnWebhookDelivery> {
    return this.adapter.updateWebhookDelivery(id, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  listWebhookDeliveries(receiptId: string): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.listWebhookDeliveries(receiptId);
  }

  listWebhookDeliveriesForRetry(now = new Date(), limit = 100): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.listWebhookDeliveriesForRetry(now, limit);
  }

  claimWebhookDeliveriesForRetry(
    now = new Date(),
    limit = 100,
    workerId = generateId('webhook_worker')
  ): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.claimWebhookDeliveriesForRetry(now, limit, workerId);
  }

  createSyncJob(input: CreateSyncJobInput): Promise<PlugFnSyncJob> {
    const now = new Date();
    return this.adapter.createSyncJob({
      id: generateId('sync'),
      provider: input.provider,
      connectionId: input.connectionId,
      resource: input.resource,
      mode: input.mode,
      status: 'queued',
      ...ownerFields(input.owner),
      cursor: input.cursor,
      checkpoint: input.checkpoint,
      fetchedCount: 0,
      persistedCount: 0,
  async updateWebhookDelivery(
    id: string,
    updates: Partial<PlugFnWebhookDelivery>
  ): Promise<PlugFnWebhookDelivery> {
    return this.database.update<PlugFnWebhookDelivery>({
      model: this.models.webhookDeliveries,
      where: [{ field: 'id', operator: 'eq', value: id }],
      data: cloneRecord(updates),
    });
  }

  async listWebhookDeliveries(receiptId: string): Promise<PlugFnWebhookDelivery[]> {
    return this.database.findMany<PlugFnWebhookDelivery>({
      model: this.models.webhookDeliveries,
      where: [{ field: 'receiptId', operator: 'eq', value: receiptId }],
      orderBy: [{ field: 'createdAt', direction: 'desc' }],
    });
  }

  async listWebhookDeliveriesForRetry(
    now: Date,
    limit = 100
  ): Promise<PlugFnWebhookDelivery[]> {
    const pending = await this.database.findMany<PlugFnWebhookDelivery>({
      model: this.models.webhookDeliveries,
      where: [{ field: 'status', operator: 'eq', value: 'pending' }],
      orderBy: [{ field: 'createdAt', direction: 'asc' }],
      limit,
    });

    const failed = await this.database.findMany<PlugFnWebhookDelivery>({
      model: this.models.webhookDeliveries,
      where: [
        { field: 'status', operator: 'eq', value: 'failed' },
        { field: 'nextAttemptAt', operator: 'lte', value: now },
      ],
      orderBy: [{ field: 'updatedAt', direction: 'asc' }],
      limit,
    });

    const staleBefore = new Date(now.getTime() - WEBHOOK_DELIVERY_LEASE_MS);
    const staleRunning = await this.database.findMany<PlugFnWebhookDelivery>({
      model: this.models.webhookDeliveries,
      where: [
        { field: 'status', operator: 'eq', value: 'running' },
        { field: 'updatedAt', operator: 'lte', value: staleBefore },
      ],
      orderBy: [{ field: 'updatedAt', direction: 'asc' }],
      limit,
    });

    return [...pending, ...failed, ...staleRunning]
      .filter((delivery) => !delivery.nextAttemptAt || toTime(delivery.nextAttemptAt) <= now.getTime())
      .sort((left, right) => {
        const leftTime = toTime(left.nextAttemptAt ?? left.createdAt);
        const rightTime = toTime(right.nextAttemptAt ?? right.createdAt);
        return leftTime - rightTime;
      })
      .slice(0, limit);
  }

  async claimWebhookDeliveriesForRetry(
    now: Date,
    limit: number,
    workerId: string
  ): Promise<PlugFnWebhookDelivery[]> {
    const candidates = await this.listWebhookDeliveriesForRetry(now, limit);
    const claimed: PlugFnWebhookDelivery[] = [];
    const claimedAt = new Date();

    for (const delivery of candidates) {
      const where: WhereClause[] = [
        { field: 'id', operator: 'eq', value: delivery.id },
