import {
  createDefaultProviderPolicyRegistry,
  ProviderPolicyError,
  type ProviderFeatureMode,
  type ProviderPolicyRegistry,
} from '@superfunctions/oauth-providers';
import {
  normalizeGmailMessages,
  type GmailApiMessage,
  type NormalizedMailMessage,
} from 'plugfn';

export type MailSyncMode = 'full' | 'incremental';

export interface GmailSyncRequest {
  tenantId: string;
  userId: string;
  connectionId: string;
  mode: MailSyncMode;
  checkpoint?: string;
  maxMessages?: number;
  featureMode?: ProviderFeatureMode;
}

export interface GmailSyncCheckpoint {
  historyId: string;
  updatedAt: string;
}

export interface GmailSyncResult {
  checkpoint: string;
  fetched: number;
  upserted: number;
  skipped: number;
  partial: boolean;
  messages: NormalizedMailMessage[];
}

export interface GmailCheckpointStore {
  get(connectionId: string): Promise<GmailSyncCheckpoint | null>;
  set(connectionId: string, checkpoint: GmailSyncCheckpoint): Promise<void>;
}

export interface GmailMessageStore {
  upsert(
    connectionId: string,
    messages: NormalizedMailMessage[]
  ): Promise<{ upserted: number; skipped: number }>;
}

export interface GmailSyncSource {
  listBaseline(input: {
    maxMessages: number;
    pageToken?: string;
  }): Promise<{
    messages: GmailApiMessage[];
    nextPageToken?: string;
    historyId?: string;
  }>;
  listIncremental(input: {
    startHistoryId: string;
    maxMessages: number;
  }): Promise<{
    messages: GmailApiMessage[];
    historyId: string;
    partial?: boolean;
  }>;
}

export interface RunGmailSyncDependencies {
  source: GmailSyncSource;
  checkpointStore: GmailCheckpointStore;
  messageStore?: GmailMessageStore;
  policyRegistry?: ProviderPolicyRegistry;
  now?: () => string;
}

export class GmailSyncError extends Error {
  readonly code: 'MAIL_SYNC_CHECKPOINT_INVALID' | 'PROVIDER_POLICY_BLOCKED' | 'VALIDATION_ERROR';
  readonly status: number;
  readonly retryable: boolean;

  constructor(
    code: 'MAIL_SYNC_CHECKPOINT_INVALID' | 'PROVIDER_POLICY_BLOCKED' | 'VALIDATION_ERROR',
    message: string
  ) {
    super(message);
    this.name = 'GmailSyncError';
    this.code = code;
    this.status = code === 'MAIL_SYNC_CHECKPOINT_INVALID' ? 409 : 400;
    this.retryable = code !== 'PROVIDER_POLICY_BLOCKED';
  }
}

export async function runGmailSync(
  request: GmailSyncRequest,
  dependencies: RunGmailSyncDependencies
): Promise<GmailSyncResult> {
  const now = dependencies.now ?? (() => new Date().toISOString());
  const policyRegistry = dependencies.policyRegistry ?? createDefaultProviderPolicyRegistry();
  assertReadPolicy(policyRegistry, request.featureMode);
  const maxMessages = clampMaxMessages(request.maxMessages);
  const messageStore = dependencies.messageStore ?? new MemoryGmailMessageStore();

  if (request.mode === 'full') {
    const baseline = await dependencies.source.listBaseline({
      maxMessages,
    });
    const normalizedMessages = normalizeGmailMessages(baseline.messages, {
      mailbox: 'inbox',
    });
    const writeResult = await messageStore.upsert(request.connectionId, normalizedMessages);
    const checkpoint = baseline.historyId ?? extractHistoryId(baseline.messages) ?? '0';

    await dependencies.checkpointStore.set(request.connectionId, {
      historyId: checkpoint,
      updatedAt: now(),
    });

    return {
      checkpoint,
      fetched: normalizedMessages.length,
      upserted: writeResult.upserted,
      skipped: writeResult.skipped,
      partial: typeof baseline.nextPageToken === 'string' && baseline.nextPageToken.length > 0,
      messages: normalizedMessages,
    };
  }

  const checkpoint = request.checkpoint
    ? { historyId: request.checkpoint, updatedAt: now() }
    : await dependencies.checkpointStore.get(request.connectionId);
  if (!checkpoint || !checkpoint.historyId) {
    throw new GmailSyncError(
      'MAIL_SYNC_CHECKPOINT_INVALID',
      'gmail checkpoint invalid; rebaseline required'
    );
  }

  let incremental: Awaited<ReturnType<GmailSyncSource['listIncremental']>>;
  try {
    incremental = await dependencies.source.listIncremental({
      startHistoryId: checkpoint.historyId,
      maxMessages,
    });
  } catch (error) {
    if (isInvalidCheckpointError(error)) {
      throw new GmailSyncError(
        'MAIL_SYNC_CHECKPOINT_INVALID',
        'gmail checkpoint invalid; rebaseline required'
      );
    }
    throw error;
  }

  const normalizedMessages = normalizeGmailMessages(incremental.messages, {
    mailbox: 'inbox',
  });
  const writeResult = await messageStore.upsert(request.connectionId, normalizedMessages);

  await dependencies.checkpointStore.set(request.connectionId, {
    historyId: incremental.historyId,
    updatedAt: now(),
  });

  return {
    checkpoint: incremental.historyId,
    fetched: normalizedMessages.length,
    upserted: writeResult.upserted,
    skipped: writeResult.skipped,
    partial: incremental.partial === true,
    messages: normalizedMessages,
  };
}

export class MemoryGmailCheckpointStore implements GmailCheckpointStore {
  private readonly checkpoints = new Map<string, GmailSyncCheckpoint>();

  async get(connectionId: string): Promise<GmailSyncCheckpoint | null> {
    return this.checkpoints.get(connectionId) ?? null;
  }

  async set(connectionId: string, checkpoint: GmailSyncCheckpoint): Promise<void> {
    this.checkpoints.set(connectionId, { ...checkpoint });
  }
}

export class MemoryGmailMessageStore implements GmailMessageStore {
  private readonly messagesByConnection = new Map<string, Map<string, NormalizedMailMessage>>();

  async upsert(
    connectionId: string,
    messages: NormalizedMailMessage[]
  ): Promise<{ upserted: number; skipped: number }> {
    let connectionStore = this.messagesByConnection.get(connectionId);
    if (!connectionStore) {
      connectionStore = new Map<string, NormalizedMailMessage>();
      this.messagesByConnection.set(connectionId, connectionStore);
    }

    let upserted = 0;
    let skipped = 0;
    for (const message of messages) {
      if (connectionStore.has(message.providerMessageId)) {
        skipped += 1;
        continue;
      }

      connectionStore.set(message.providerMessageId, message);
      upserted += 1;
    }

    return {
      upserted,
      skipped,
    };
  }

  list(connectionId: string): NormalizedMailMessage[] {
    return [...(this.messagesByConnection.get(connectionId)?.values() ?? [])];
  }
}

function assertReadPolicy(
  policyRegistry: ProviderPolicyRegistry,
  featureMode: ProviderFeatureMode | undefined
): void {
  const operation = featureMode === 'full-body' ? 'mail.read.fullbody' : 'mail.read.metadata';
  try {
    policyRegistry.assertOperationAllowed({
      providerId: 'google',
      operation,
      featureMode,
    });
  } catch (error) {
    if (error instanceof ProviderPolicyError) {
      throw new GmailSyncError('PROVIDER_POLICY_BLOCKED', error.message);
    }
    throw error;
  }
import { describe, expect, it } from 'vitest';
import { ProviderPolicyError } from '@superfunctions/oauth-providers';
import {
  MemoryGmailCheckpointStore,
  MemoryGmailMessageStore,
  runGmailSync,
} from '../src/gmail/gmail.sync.js';

describe('gmail sync', () => {
  it('persists baseline checkpoint on full sync', async () => {
    const checkpointStore = new MemoryGmailCheckpointStore();
    const messageStore = new MemoryGmailMessageStore();

    const result = await runGmailSync(
      {
        tenantId: 'tenant-1',
        userId: 'user-1',
        connectionId: 'conn-1',
        mode: 'full',
      },
      {
        source: {
          listBaseline: async () => ({
            historyId: 'h-1',
            messages: [
              createGmailMessage('g-1', 'gt-1', 'h-1'),
              createGmailMessage('g-2', 'gt-2', 'h-1'),
            ],
          }),
          listIncremental: async () => ({
            historyId: 'h-2',
            messages: [],
          }),
        },
        checkpointStore,
        messageStore,
      }
    );

    expect(result.checkpoint).toBe('h-1');
    expect(result.fetched).toBe(2);
    expect(result.upserted).toBe(2);
    expect(result.skipped).toBe(0);
    expect(result.messages[0].providerMessageId).toBe('g-1');
    expect(result.messages[0].threadId).toBe('gt-1');

    const checkpoint = await checkpointStore.get('conn-1');
    expect(checkpoint).toMatchObject({
      historyId: 'h-1',
    });
  });

  it('uses checkpoint for incremental sync and dedupes already-upserted messages', async () => {
    const checkpointStore = new MemoryGmailCheckpointStore();
    const messageStore = new MemoryGmailMessageStore();

    await runGmailSync(
      {
        tenantId: 'tenant-1',
        userId: 'user-1',
        connectionId: 'conn-1',
        mode: 'full',
      },
      {
        source: {
          listBaseline: async () => ({
            historyId: 'h-1',
            messages: [createGmailMessage('g-1', 'gt-1', 'h-1')],
          }),
          listIncremental: async () => ({
            historyId: 'h-2',
            messages: [],
          }),
        },
        checkpointStore,
        messageStore,
      }
    );

    const incremental = await runGmailSync(
      {
        tenantId: 'tenant-1',
        userId: 'user-1',
        connectionId: 'conn-1',
        mode: 'incremental',
      },
      {
        source: {
          listBaseline: async () => ({
            historyId: 'h-1',
            messages: [],
          }),
          listIncremental: async () => ({
            historyId: 'h-2',
            messages: [
              createGmailMessage('g-1', 'gt-1', 'h-2'),
              createGmailMessage('g-3', 'gt-3', 'h-2'),
            ],
          }),
        },
        checkpointStore,
        messageStore,
      }
    );

    expect(incremental.checkpoint).toBe('h-2');
    expect(incremental.fetched).toBe(2);
    expect(incremental.upserted).toBe(1);
    expect(incremental.skipped).toBe(1);
  });

  it('uses a durable runtime checkpoint when the local checkpoint store is empty', async () => {
    const checkpointStore = new MemoryGmailCheckpointStore();
    let receivedHistoryId: string | undefined;

    const result = await runGmailSync(
      {
        tenantId: 'tenant-1',
        userId: 'user-1',
        connectionId: 'conn-1',
        mode: 'incremental',
        checkpoint: 'h-durable',
      },
      {
        source: {
          listBaseline: async () => ({ historyId: 'h-1', messages: [] }),
          listIncremental: async ({ startHistoryId }) => {
            receivedHistoryId = startHistoryId;
            return { historyId: 'h-next', messages: [] };
          },
        },
        checkpointStore,
      }
    );

    expect(receivedHistoryId).toBe('h-durable');
    expect(result.checkpoint).toBe('h-next');
  });

  it('returns canonical MAIL_SYNC_CHECKPOINT_INVALID when incremental checkpoint is invalid', async () => {
    const checkpointStore = new MemoryGmailCheckpointStore();
    const messageStore = new MemoryGmailMessageStore();
    await checkpointStore.set('conn-1', {
      historyId: 'invalid-history-id',
      updatedAt: new Date().toISOString(),
    });

    await expect(
      runGmailSync(
        {
          tenantId: 'tenant-1',
          userId: 'user-1',
          connectionId: 'conn-1',
          mode: 'incremental',
        },
        {
          source: {
            listBaseline: async () => ({
              historyId: 'h-1',
              messages: [],
            }),
            listIncremental: async () => {
              throw {
                status: 404,
                message: 'history id invalid',
              };
            },
          },
          checkpointStore,
          messageStore,
        }
      )
    ).rejects.toMatchObject({
      code: 'MAIL_SYNC_CHECKPOINT_INVALID',
      message: 'gmail checkpoint invalid; rebaseline required',
    });
  });

  it('blocks sync execution when policy registry disallows the operation', async () => {
    const checkpointStore = new MemoryGmailCheckpointStore();
    const messageStore = new MemoryGmailMessageStore();

    await expect(
      runGmailSync(
        {
          tenantId: 'tenant-1',
          userId: 'user-1',
          connectionId: 'conn-1',
          mode: 'full',
        },
        {
          source: {
            listBaseline: async () => ({
              historyId: 'h-1',
              messages: [createGmailMessage('g-1', 'gt-1', 'h-1')],
            }),
            listIncremental: async () => ({
              historyId: 'h-2',
              messages: [],
            }),
          },
          checkpointStore,
          messageStore,
          policyRegistry: {
            assertOperationAllowed: () => {
              throw new ProviderPolicyError(
                'PROVIDER_POLICY_BLOCKED',
                'operation not allowed by policy'
              );
            },
          } as any,
        }
      )
    ).rejects.toMatchObject({
      code: 'PROVIDER_POLICY_BLOCKED',
      message: 'operation not allowed by policy',
    });
  });
});

function createGmailMessage(id: string, threadId: string, historyId: string) {
  return {
    id,
    threadId,
    historyId,
    internalDate: `${Date.parse('2026-03-12T00:00:00.000Z')}`,
    labelIds: ['INBOX'],
    snippet: 'Example snippet',
    payload: {
      headers: [
        { name: 'From', value: 'sender@example.com' },
        { name: 'To', value: 'user@example.com' },
        { name: 'Subject', value: 'Subject line' },
        { name: 'Date', value: 'Thu, 12 Mar 2026 00:00:00 GMT' },
      ],
      mimeType: 'multipart/alternative',
      parts: [
        {
          mimeType: 'text/plain',
          body: {
            data: Buffer.from('Body text').toString('base64url'),
          },
        },
      ],
    },
    database,
    providers: providerRegistry,
    integrationConfigs,
    baseUrl: config.baseUrl,
    encryptionKey: config.encryptionKey,
    logger,
  });

  // Initialize managers
  const connectionManager = new ConnectionManager(
    connectionStorage,
    providerRegistry,
    integrationConfigs,
    config.baseUrl,
    config.encryptionKey,
    logger,
    oauthFlowDependencies,
    config.authorization?.authorizeConnection
  );

  const actionExecutor = new ActionExecutor(
    connectionManager,
    providerRegistry,
    logger,
    {
      enableRetry: config.retry?.enabled !== false,
      enableRateLimit: config.rateLimit?.enabled !== false,
      enableCache: config.cache?.enabled !== false,
      enableLogging: true,
      enableMetrics: true,
      database,
      cacheStore: config.cache?.store ?? config.cacheStore,
      cacheTtl: config.cache?.ttl ?? config.cache?.defaultTTL,
      cacheKeyPrefix: config.cache?.keyPrefix,
      respectProviderLimits: config.rateLimit?.respectProviderLimits,
      globalRateLimit: config.rateLimit?.global,
    }
  );

  const webhookHandler = new WebhookHandler(providerRegistry, logger, {
    verifySignatures: config.webhooks?.verifySignatures,
