readme = "README.md"
requires-python = ">=3.10"
license = "MIT"
keywords = ["integrations", "oauth", "webhooks", "api", "superfunctions"]
authors = [
  { name = "21n" }
]
classifiers = [
  "Development Status :: 3 - Alpha",
  "Intended Audience :: Developers",
  "License :: OSI Approved :: MIT License",
  "Programming Language :: Python :: 3",
  "Programming Language :: Python :: 3.10",
  "Programming Language :: Python :: 3.11",
  "Programming Language :: Python :: 3.12",
  "Topic :: Software Development :: Libraries :: Python Modules",
]
dependencies = [
  "httpx>=0.25.0",
  "pydantic>=2.5.0",
  "cryptography>=41.0.0",
  "python-jose>=3.3.0",
  "superfunctions>=0.1.0",
]

[project.optional-dependencies]
dev = [
  "pytest>=7.4.0",
  "pytest-asyncio>=0.21.0",
  "pytest-cov>=4.1.0",
  "build>=1.0.0",
  "mypy>=1.7.0",
  "ruff>=0.1.6",
  "black>=23.11.0",
  # CI installs only .[dev], so adapter test dependencies are repeated here intentionally.
  "fastapi>=0.104.0",
  "uvicorn>=0.24.0",
  "flask>=3.0.0",
]
fastapi = [
  "fastapi>=0.104.0",
  "uvicorn>=0.24.0",
]
flask = [
  "flask>=3.0.0",
]

[project.urls]
Repository = "https://github.com/21nCo/super-functions"
Issues = "https://github.com/21nCo/super-functions/issues"

[tool.hatch.build.targets.wheel]
packages = ["plugfn"]

[tool.pytest.ini_options]
testpaths = ["tests"]
asyncio_mode = "auto"
addopts = "-q"
python_files = ["test_*.py"]
python_classes = ["Test*"]
python_functions = ["test_*"]

[tool.mypy]
python_version = "3.10"
warn_return_any = true
warn_unused_configs = true
disallow_untyped_defs = true
explicit_package_bases = true
exclude = ["^setup\\.py$"]

[[tool.mypy.overrides]]
module = ["tests.*", "examples.*"]
disallow_untyped_defs = false
check_untyped_defs = true

[tool.ruff]
target-version = "py310"
line-length = 100

[tool.ruff.lint]
select = [
  "E",  # pycodestyle errors
  "W",  # pycodestyle warnings
  "F",  # pyflakes
  "I",  # isort
  "B",  # flake8-bugbear
  "C4", # flake8-comprehensions
]
ignore = [
  "E501", # line too long, handled by black
]

[tool.black]
line-length = 100
target-version = ["py310", "py311", "py312"]

