/**
 * Main PlugFn SDK interface
 */
export interface PlugFn {
  /** Resolves only after persisted workflow triggers have been rehydrated. */
  ready: Promise<void>;

  config: {
    auth: {
      authenticate(request: Request): Promise<PlugFnPrincipal | null>;
    };
    baseUrl: string;
    integrations: Record<string, PlugFnConfig['integrations'][string]>;
    authorization?: PlugFnConfig['authorization'];
    webhooks?: PlugFnConfig['webhooks'];
  };

  // Connection management
  connections: {
    start(options: StartConnectionOptions): Promise<{ authUrl: string }>;
    getAuthUrl(options: GetAuthUrlOptions): Promise<string>;
    handleCallback(options: HandleCallbackOptions): Promise<HandleCallbackResult>;
    list(options: ListConnectionsOptions): Promise<Connection[]>;
    get(id: string): Promise<Connection>;
    disconnect(options: DisconnectOptions): Promise<DisconnectResult>;
    refresh(id: string): Promise<Connection>;
  };

  runtime: {
    installations: {
      create(input: CreateProviderInstallationInput): Promise<PlugFnProviderInstallation>;
      list(filters?: Record<string, unknown>): Promise<PlugFnProviderInstallation[]>;
      update(id: string, updates: Partial<PlugFnProviderInstallation>): Promise<PlugFnProviderInstallation>;
    };
    grants: {
      create(input: CreateConnectionGrantInput): Promise<PlugFnConnectionGrant>;
      list(connectionId: string): Promise<PlugFnConnectionGrant[]>;
      delete(id: string): Promise<void>;
    };
    webhooks: {
      createReceipt(input: CreateWebhookReceiptInput): Promise<PlugFnWebhookReceipt>;
      getReceipt(id: string): Promise<PlugFnWebhookReceipt | null>;
      findReceiptByIdempotencyKey(provider: string, idempotencyKey: string): Promise<PlugFnWebhookReceipt | null>;
      updateReceipt(id: string, updates: Partial<PlugFnWebhookReceipt>): Promise<PlugFnWebhookReceipt>;
      createDelivery(input: CreateWebhookDeliveryInput): Promise<PlugFnWebhookDelivery>;
      updateDelivery(id: string, updates: Partial<PlugFnWebhookDelivery>): Promise<PlugFnWebhookDelivery>;
      listDeliveries(receiptId: string): Promise<PlugFnWebhookDelivery[]>;
      processDueDeliveries(
        handler: PlugFnWebhookDeliveryHandler,
        options?: PlugFnWebhookDeliveryWorkerOptions
      ): Promise<PlugFnWebhookDeliveryWorkerResult>;
    };
    sync: {
      createJob(input: CreateSyncJobInput): Promise<PlugFnSyncJob>;
      getJob(id: string): Promise<PlugFnSyncJob | null>;
      listJobs(filters?: Record<string, unknown>, limit?: number): Promise<PlugFnSyncJob[]>;
      updateJob(id: string, updates: UpdateSyncJobProgressInput): Promise<PlugFnSyncJob>;
      cancelJob(id: string): Promise<PlugFnSyncJob>;
      completeJob(id: string, updates?: Omit<UpdateSyncJobProgressInput, 'status' | 'error'>): Promise<PlugFnSyncJob>;
      failJob(id: string, error: string): Promise<PlugFnSyncJob>;
      processQueued(options?: PlugFnSyncWorkerOptions): Promise<PlugFnSyncWorkerResult>;
      upsertCheckpoint(input: {
        provider: string;
        connectionId: string;
        resource: string;
        checkpoint: unknown;
      }): Promise<PlugFnSyncCheckpoint>;
      getCheckpoint(connectionId: string, resource: string): Promise<PlugFnSyncCheckpoint | null>;
    };
    events: {
      create(input: Omit<PlugFnProviderEvent, 'id' | 'createdAt'>): Promise<PlugFnProviderEvent>;
      list(filters?: Record<string, unknown>, limit?: number): Promise<PlugFnProviderEvent[]>;
    };
    secrets: {
      upsert(input: Omit<PlugFnSecretRef, 'createdAt' | 'updatedAt'>): Promise<PlugFnSecretRef>;
      list(filters?: Record<string, unknown>): Promise<PlugFnSecretRef[]>;
    };
    sinks: {
      register<Raw = unknown, RecordValue = unknown>(
        sink: PlugFnPersistenceSink<Raw, RecordValue>
      ): void;
      list(): PlugFnPersistenceSink[];
      get(id: string): PlugFnPersistenceSink | undefined;
      persist<Raw = unknown>(input: {
        sinkId?: string;
        provider: string;
        resource: string;
        raw: Raw;
        context?: Partial<PlugFnSinkContext>;
      }): Promise<{ sinkId: string; idempotencyKey: string }>;
    };
  };

  // Workflow management
  workflows: {
    list(options?: ListWorkflowsOptions): Promise<Workflow[]>;
    get(id: string): Promise<Workflow | null>;
    rehydrateTriggers(): Promise<{ registered: number; failed: number }>;
    enable(id: string): Promise<void>;
    disable(id: string): Promise<void>;
    delete(id: string): Promise<void>;
    getStats(id: string): Promise<WorkflowStats>;
  };

  // Webhook management
  webhooks: {
    on(provider: string, event: string, handler: TriggerHandler): void;
    off(provider: string, event: string, handler: TriggerHandler): void;
    handle(
      provider: string,
      event: string,
      payload: any,
      headers: Record<string, string>,
      secret?: string,
      options?: {
        rawBody?: Uint8Array;
      }
    ): Promise<any>;
    verify(
      provider: string,
      event: string,
      payload: any,
      headers: Record<string, string>,
      secret?: string,
      options?: {
        rawBody?: Uint8Array;
      }
    ): Promise<any>;
  };

  // Provider management
  providers: {
    list(): Provider[];
    get(name: string): Provider | undefined;
    register(provider: Provider): void;
  };

  use<P extends Provider>(provider: P): PlugFn;

  action<T = unknown>(
    provider: string,
    action: string,
    options: ActionOptions
  ): Promise<T>;

  sync: {
    backfill(options: PlugFnSyncRunOptions): Promise<PlugFnSyncJob>;
    incremental(options: PlugFnSyncRunOptions): Promise<PlugFnSyncJob>;
    enqueue(options: PlugFnSyncQueueOptions): Promise<PlugFnSyncJob>;
    processQueued(options?: PlugFnSyncWorkerOptions): Promise<PlugFnSyncWorkerResult>;
  };

  // Action execution
  batch(actions: BatchAction[]): Promise<BatchResult[]>;
  getMetrics(options: MetricsOptions): Promise<any>;
  on(event: string, handler: (event: any) => void): void;
  off(event: string, handler: (event: any) => void): void;

  // Dynamic provider access
  [provider: string]: any;
}

export interface PlugFnSyncRunOptions {
  provider: string;
  connectionId: string;
  resource: string;
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages?: number;
  metadata?: Record<string, unknown>;
  actor?: PlugFnActor;
}

export interface PlugFnSyncQueueOptions extends PlugFnSyncRunOptions {
  mode: PlugFnSyncJob['mode'];
}

export interface PlugFnSyncWorkerOptions {
  limit?: number;
}

export interface PlugFnSyncWorkerResult {
  processed: number;
  completed: number;
  cancelled: number;
  failed: number;
  jobs: PlugFnSyncJob[];
}

export interface PlugFnWebhookDeliveryWorkerOptions {
  limit?: number;
  maxAttempts?: number;
  baseDelayMs?: number;
}

export interface PlugFnWebhookDeliveryWorkerResult {
  processed: number;
  succeeded: number;
  failed: number;
  deadLettered: number;
  deliveries: PlugFnWebhookDelivery[];
}

export type PlugFnWebhookDeliveryHandler = (input: {
  delivery: PlugFnWebhookDelivery;
  receipt: PlugFnWebhookReceipt;
}) => Promise<void> | void;

/**
 * Create PlugFn instance
 */
export function plugFn(config: PlugFnConfig): PlugFn {
  // Initialize logger
  const logger: Logger = config.logger || new ConsoleLogger('[PlugFn]');
  validateEncryptionKey(config.encryptionKey);
  const normalizedAuthProvider = normalizeAuthProvider(config.auth);
  const database = wrapWithSchema(config.database, getSchema());

  // Initialize storage
  const connectionStorage = new AdapterConnectionStorage(database);
  // const _webhookStorage = new AdapterWebhookStorage(database);
  const runtimeStorage = new AdapterRuntimeStorage(database);
  const workflowStorage = new AdapterWorkflowStorage(database);

  // Initialize provider registry
  const providerRegistry = new ProviderRegistry(logger);

  // Convert integration configs to Map
  const integrationConfigs = new Map(Object.entries(config.integrations));

  // Mark configured providers
  for (const providerName of integrationConfigs.keys()) {
    providerRegistry.markConfigured(providerName);
  }

  const oauthFlowDependencies = createConnectionManagerOAuthDependencies({
    database,
    providers: providerRegistry,
    integrationConfigs,
    baseUrl: config.baseUrl,
    encryptionKey: config.encryptionKey,
    logger,
  });

  // Initialize managers
  const connectionManager = new ConnectionManager(
    connectionStorage,
    providerRegistry,
    integrationConfigs,
    config.baseUrl,
    config.encryptionKey,
    logger,
    oauthFlowDependencies,
    config.authorization?.authorizeConnection
  );

  const actionExecutor = new ActionExecutor(
    connectionManager,
    providerRegistry,
    logger,
    {
      enableRetry: config.retry?.enabled !== false,
      enableRateLimit: config.rateLimit?.enabled !== false,
      enableCache: config.cache?.enabled !== false,
      enableLogging: true,
      enableMetrics: true,
      database,
      cacheStore: config.cache?.store ?? config.cacheStore,
      cacheTtl: config.cache?.ttl ?? config.cache?.defaultTTL,
      cacheKeyPrefix: config.cache?.keyPrefix,
      respectProviderLimits: config.rateLimit?.respectProviderLimits,
      globalRateLimit: config.rateLimit?.global,
    }
  );

  const webhookHandler = new WebhookHandler(providerRegistry, logger, {
    verifySignatures: config.webhooks?.verifySignatures,
  });

  const workflowEngine = new WorkflowEngine(workflowStorage, webhookHandler, logger);
  const ready = workflowEngine.rehydrateEnabledTriggers().then((result) => {
    if (result.failed > 0) {
      throw new Error(`failed to rehydrate ${result.failed} workflow trigger(s)`);
    }
  });
  void ready.catch((error) => {
    logger.error('PlugFn workflow trigger rehydration failed', { error });
  });

  // Event handlers
  const eventHandlers = new Map<string, Set<(event: any) => void>>();
  const persistenceSinks = new Map<string, PlugFnPersistenceSink>();
  let proxyApi!: PlugFn;

  // Create the main API
  const api: PlugFn = {
    ready,
    config: {
      auth: normalizedAuthProvider,
      baseUrl: config.baseUrl,
      integrations: config.integrations,
      authorization: config.authorization,
      webhooks: config.webhooks,
    },

    // Connection management
    connections: {
      start: async (options) => ({ authUrl: await connectionManager.getAuthUrl(options) }),
      getAuthUrl: (options) => connectionManager.getAuthUrl(options),
      handleCallback: (options) => connectionManager.handleCallback(options),
      list: (options) => connectionManager.list(options),
      get: (id) => connectionManager.get(id),
      disconnect: (options) => connectionManager.disconnect(options),
      refresh: (id) => connectionManager.refresh(id),
    },

    runtime: {
      installations: {
        create: (input) => runtimeStorage.createProviderInstallation(input),
        list: (filters) => runtimeStorage.listProviderInstallations(filters),
        update: (id, updates) => runtimeStorage.updateProviderInstallation(id, updates),
      },
      grants: {
        create: (input) => runtimeStorage.createConnectionGrant(input),
        list: (connectionId) => runtimeStorage.listConnectionGrants(connectionId),
        delete: (id) => runtimeStorage.deleteConnectionGrant(id),
      },
      webhooks: {
        createReceipt: (input) => runtimeStorage.createWebhookReceipt(input),
        getReceipt: (id) => runtimeStorage.getWebhookReceipt(id),
        findReceiptByIdempotencyKey: (provider, idempotencyKey) =>
          runtimeStorage.findWebhookReceiptByIdempotencyKey(provider, idempotencyKey),
        updateReceipt: (id, updates) => runtimeStorage.updateWebhookReceipt(id, updates),
        createDelivery: (input) => runtimeStorage.createWebhookDelivery(input),
        updateDelivery: (id, updates) => runtimeStorage.updateWebhookDelivery(id, updates),
        listDeliveries: (receiptId) => runtimeStorage.listWebhookDeliveries(receiptId),
        processDueDeliveries: (handler, options) => processDueWebhookDeliveries(handler, options),
      },
      sync: {
        createJob: (input) => runtimeStorage.createSyncJob(input),
        getJob: (id) => runtimeStorage.getSyncJob(id),
        listJobs: (filters, limit) => runtimeStorage.listSyncJobs(filters, limit),
        updateJob: (id, updates) => runtimeStorage.updateSyncJob(id, updates),
        cancelJob: (id) => runtimeStorage.cancelSyncJob(id),
        completeJob: (id, updates) => runtimeStorage.completeSyncJob(id, updates),
        failJob: (id, error) => runtimeStorage.failSyncJob(id, error),
        processQueued: (options) => processQueuedSyncJobs(options),
        upsertCheckpoint: (input) => runtimeStorage.upsertSyncCheckpoint(input),
        getCheckpoint: (connectionId, resource) =>
          runtimeStorage.getSyncCheckpoint(connectionId, resource),
      },
      events: {
        create: (input) => runtimeStorage.createProviderEvent(input),
        list: (filters, limit) => runtimeStorage.listProviderEvents(filters, limit),
      },
      secrets: {
        upsert: (input) => runtimeStorage.upsertSecretRef(input),
        list: (filters) => runtimeStorage.listSecretRefs(filters),
      },
      sinks: {
        register: (sink) => {
          persistenceSinks.set(sink.id, sink as PlugFnPersistenceSink);
        },
        list: () => [...persistenceSinks.values()],
        get: (id) => persistenceSinks.get(id),
        persist: async (input) => {
          const sink = resolvePersistenceSink(persistenceSinks, input);
          const context: PlugFnSinkContext = {
            provider: input.provider,
            resource: input.resource,
            ...input.context,
          };
          const { idempotencyKey } = await persistSinkItem(sink, input.raw, context);
          return {
            sinkId: sink.id,
            idempotencyKey,
          };
        },
      },
    },

    // Workflow management
    workflows: {
      list: (options) => workflowEngine.list(options),
      get: (id) => workflowEngine.get(id),
      rehydrateTriggers: () => workflowEngine.rehydrateEnabledTriggers(),
      enable: (id) => workflowEngine.enable(id),
      disable: (id) => workflowEngine.disable(id),
      delete: (id) => workflowEngine.delete(id),
      getStats: (id) => workflowEngine.getStats(id),
    },

    // Webhook management
    webhooks: {
      on: (provider, event, handler) => webhookHandler.on(provider, event, handler),
      off: (provider, event, handler) => webhookHandler.off(provider, event, handler),
      handle: (provider, event, payload, headers, secret, options) =>
        webhookHandler.handleWebhook(provider, event, payload, headers, secret, options),
      verify: (provider, event, payload, headers, secret, options) =>
        webhookHandler.verifyWebhook(provider, event, payload, headers, secret, options),
    },

    // Provider management
    providers: {
      list: () => providerRegistry.list(),
      get: (name) => providerRegistry.get(name),
      register: (provider) => {
        providerRegistry.register(provider);
      },
    },

    use: (provider) => {
      providerRegistry.register(provider);
      return proxyApi;
    },

    action: async (provider, action, options) => {
      const result = await actionExecutor.execute(provider, action, options);
      if (!result.success) {
        throw result.error;
      }
      return result.data as any;
    },

    sync: {
      backfill: (options) => runSyncJob('full', options),
      incremental: (options) => runSyncJob('incremental', options),
      enqueue: (options) => enqueueSyncJob(options.mode, options),
      processQueued: (options) => processQueuedSyncJobs(options),
    },

    // Batch execution
    batch: (actions) => actionExecutor.batch(actions),

    // Metrics
    getMetrics: async (options) => actionExecutor.getMetrics(options),

    // Event handling
    on: (event: string, handler: (event: any) => void) => {
      if (!eventHandlers.has(event)) {
        eventHandlers.set(event, new Set());
      }
      eventHandlers.get(event)!.add(handler);
    },

    off: (event: string, handler: (event: any) => void) => {
      const handlers = eventHandlers.get(event);
      if (handlers) {
        handlers.delete(handler);
      }
    },
  };

  async function runSyncJob(
    mode: PlugFnSyncJob['mode'],
    options: PlugFnSyncRunOptions
  ): Promise<PlugFnSyncJob> {
    const job = await enqueueSyncJob(mode, options);
    return executeQueuedSyncJob(job);
  }

  async function assertSyncConnectionAuthorized(
    connection: Connection,
    actor: PlugFnActor
  ): Promise<void> {
    if (await connectionManager.canActorAccessConnection(connection, actor, 'sync')) {
      return;
    }

    const tenantMismatch =
      !config.authorization?.authorizeConnection &&
      !tenantMatches(connection.tenantId, actor.tenantId);
    throw new PlugFnRuntimeError(
      'TENANT_ACCESS_DENIED',
      tenantMismatch ? 'connection tenant mismatch' : 'connection owner mismatch',
      403
    );
  }

  async function enqueueSyncJob(
    mode: PlugFnSyncJob['mode'],
    options: PlugFnSyncRunOptions
  ): Promise<PlugFnSyncJob> {
    const connection = await connectionManager.get(options.connectionId);
    if (connection.provider !== options.provider) {
      throw new PlugFnRuntimeError(
        'VALIDATION_ERROR',
        'connection provider mismatch',
        400
      );
    }

    if (options.actor) {
      await assertSyncConnectionAuthorized(connection, options.actor);
    }

    const persistedCheckpoint =
      mode === 'incremental' && options.checkpoint === undefined
        ? await runtimeStorage.getSyncCheckpoint(options.connectionId, options.resource)
        : null;

    return runtimeStorage.createSyncJob({
      provider: options.provider,
      connectionId: options.connectionId,
      resource: options.resource,
      mode,
      owner: connectionToOwner(connection),
      cursor: options.cursor,
      checkpoint:
        options.checkpoint !== undefined
          ? options.checkpoint
          : persistedCheckpoint?.checkpoint,
      metadata: {
        ...(options.metadata ?? {}),
        plugfnSync: {
          sinkId: options.sinkId,
          maxPages: options.maxPages,
          actor: options.actor,
        },
      },
    });
  }

  async function processQueuedSyncJobs(
    options: PlugFnSyncWorkerOptions = {}
  ): Promise<PlugFnSyncWorkerResult> {
    const queued = await runtimeStorage.claimQueuedSyncJobs(options.limit ?? 25);
    const jobs: PlugFnSyncJob[] = [];
    let completed = 0;
    let cancelled = 0;
    let failed = 0;

    for (const job of queued) {
      try {
        const processedJob = await executeSyncJob(job, { claimed: true });
        if (processedJob.status === 'completed') {
          completed += 1;
        } else if (processedJob.status === 'cancelled') {
          cancelled += 1;
        } else if (processedJob.status === 'failed') {
          failed += 1;
        } else {
          throw new Error(`Sync job ${processedJob.id} ended in ${processedJob.status}`);
        }
        jobs.push(processedJob);
      } catch {
        const updated = await runtimeStorage.getSyncJob(job.id);
        if (updated) {
          jobs.push(updated);
        }
        failed += 1;
      }
    }

    return {
      processed: queued.length,
      completed,
      cancelled,
      failed,
      jobs,
    };
  }

  async function executeQueuedSyncJob(job: PlugFnSyncJob): Promise<PlugFnSyncJob> {
    return executeSyncJob(job, { claimed: false });
  }

  async function executeSyncJob(
    job: PlugFnSyncJob,
    options: { claimed: boolean }
  ): Promise<PlugFnSyncJob> {
    if (!options.claimed) {
      await runtimeStorage.updateSyncJob(job.id, { status: 'running' });
    }

    try {
      const connection = await connectionManager.get(job.connectionId);
      if (connection.provider !== job.provider) {
        throw new PlugFnRuntimeError(
          'VALIDATION_ERROR',
          'connection provider mismatch',
          400
        );
      }

      const workerOptions = readSyncJobWorkerMetadata(job);
      if (workerOptions.actor) {
        await assertSyncConnectionAuthorized(connection, workerOptions.actor);
      }

      const result = await executeSyncResource({
        providerRegistry,
        actionExecutor,
        persistenceSinks,
        provider: job.provider,
        connectionId: job.connectionId,
        resource: job.resource,
        mode: job.mode,
        userId: connection.userId,
        tenantId: connection.tenantId ?? workerOptions.actor?.tenantId,
        sinkId: workerOptions.sinkId,
        cursor: job.cursor,
        checkpoint: job.checkpoint,
        maxPages: workerOptions.maxPages ?? 50,
        shouldContinue: async () => {
          const currentJob = await runtimeStorage.getSyncJob(job.id);
          return currentJob?.status !== 'cancelled';
        },
        onPage: async (progress) => {
          await runtimeStorage.updateSyncJob(job.id, {
            cursor: progress.cursor,
            checkpoint: progress.checkpoint,
            fetchedCount: progress.fetchedCount,
            persistedCount: progress.persistedCount,
            skippedCount: progress.skippedCount,
          });
          if (progress.checkpoint !== undefined) {
            await runtimeStorage.upsertSyncCheckpoint({
              provider: job.provider,
              connectionId: job.connectionId,
              resource: job.resource,
              checkpoint: progress.checkpoint,
            });
          }
        },
      });

      if (result.checkpoint !== undefined) {
        await runtimeStorage.upsertSyncCheckpoint({
          provider: job.provider,
          connectionId: job.connectionId,
          resource: job.resource,
          checkpoint: result.checkpoint,
        });
      }

      return runtimeStorage.completeSyncJob(job.id, {
        cursor: result.cursor,
        checkpoint: result.checkpoint,
        fetchedCount: result.fetchedCount,
        persistedCount: result.persistedCount,
        skippedCount: result.skippedCount,
      });
    } catch (error) {
      if (isSyncCancelledError(error)) {
        return runtimeStorage.updateSyncJob(job.id, {
          status: 'cancelled',
          error: undefined,
        });
      }
      const failedJob = await runtimeStorage.failSyncJob(
        job.id,
        error instanceof Error ? error.message : 'sync failed'
      );
      if (failedJob.status === 'cancelled') {
        return failedJob;
      }
      throw error;
    }
  }

  async function processDueWebhookDeliveries(
    handler: PlugFnWebhookDeliveryHandler,
    options: PlugFnWebhookDeliveryWorkerOptions = {}
  ): Promise<PlugFnWebhookDeliveryWorkerResult> {
    const maxAttempts = Math.max(1, options.maxAttempts ?? 5);
    const baseDelayMs = Math.max(1000, options.baseDelayMs ?? 30_000);
    const dueDeliveries = await runtimeStorage.claimWebhookDeliveriesForRetry(
      new Date(),
      options.limit ?? 100
    );
    const deliveries: PlugFnWebhookDelivery[] = [];
    let succeeded = 0;
    let failed = 0;
    let deadLettered = 0;

    for (const delivery of dueDeliveries) {
      const attempt = delivery.attempts;
      const receipt = await runtimeStorage.getWebhookReceipt(delivery.receiptId);
      if (!receipt) {
        const deadLetter = await runtimeStorage.updateWebhookDelivery(delivery.id, {
          status: 'dead-lettered',
          attempts: attempt,
          error: 'webhook receipt not found',
        });
        deliveries.push(deadLetter);
        deadLettered += 1;
        continue;
      }

      const receiptDeliveries = await runtimeStorage.listWebhookDeliveries(receipt.id);
      if (
        receiptDeliveries.some(
          (receiptDelivery) =>
            receiptDelivery.id !== delivery.id && receiptDelivery.status === 'success'
        )
      ) {
        const superseded = await runtimeStorage.updateWebhookDelivery(delivery.id, {
          status: 'dead-lettered',
          attempts: attempt,
          error: 'webhook receipt was already delivered successfully',
          nextAttemptAt: undefined,
        });
        deliveries.push(superseded);
        deadLettered += 1;
        continue;
      }

      try {
        await handler({ delivery, receipt });
        const updated = await runtimeStorage.updateWebhookDelivery(delivery.id, {
          status: 'success',
          attempts: attempt,
        });
        deliveries.push(updated);
        succeeded += 1;
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'webhook delivery failed';
        const status = attempt >= maxAttempts ? 'dead-lettered' : 'failed';
        const nextAttemptAt =
          status === 'failed'
            ? new Date(Date.now() + baseDelayMs * 2 ** Math.max(0, attempt - 1))
            : undefined;
        const updated = await runtimeStorage.updateWebhookDelivery(delivery.id, {
          status,
          attempts: attempt,
          error: errorMessage,
          nextAttemptAt,
        });
        deliveries.push(updated);
        if (status === 'dead-lettered') {
          deadLettered += 1;
        } else {
          failed += 1;
        }
      }
    }

    return {
      processed: dueDeliveries.length,
      succeeded,
      failed,
      deadLettered,
      deliveries,
    };
  }

  // Create dynamic provider proxies
  proxyApi = new Proxy(api, {
    get(target, prop: string) {
      // If property exists on target, return it
      if (prop in target) {
        return target[prop as keyof typeof target];
      }

      // Check if it's a provider
      const provider = providerRegistry.get(prop);
      if (!provider) {
        return undefined;
      }

      // Create provider action proxy
      const providerProxy: any = {
        on: (event: string, handler: TriggerHandler) => {
          webhookHandler.on(prop, event, handler);
        },
      };

      // Add all actions
      for (const [actionName, _action] of Object.entries(provider.actions)) {
        providerProxy[actionName] = async (options: ActionOptions) => {
          const result = await actionExecutor.execute(prop, actionName, options);
          if (!result.success) {
            throw result.error;
          }
          return result.data;
        };
      }

      return providerProxy;
    },
  }) as PlugFn;

  return proxyApi;
}

function resolvePersistenceSink(
  sinks: Map<string, PlugFnPersistenceSink>,
  input: {
    sinkId?: string;
    provider: string;
    resource: string;
  }
): PlugFnPersistenceSink {
  if (input.sinkId) {
    const sink = sinks.get(input.sinkId);
    if (!sink) {
      throw new Error(`Persistence sink ${input.sinkId} not found`);
    }
    return sink;
  }

  const sink = [...sinks.values()].find((candidate) => {
    return candidate.provider === input.provider && candidate.resource === input.resource;
  });
  if (!sink) {
    throw new Error(`Persistence sink not found for ${input.provider}.${input.resource}`);
  }
  return sink;
}

async function persistSinkItem(
  sink: PlugFnPersistenceSink,
  raw: unknown,
  context: PlugFnSinkContext
): Promise<{ idempotencyKey: string }> {
  if (sink.idempotencyKeyForRecord) {
    const record = await sink.transform(raw, context);
    const idempotencyKey = sink.idempotencyKeyForRecord(record, context);
    await sink.upsert(record, {
      ...context,
      metadata: {
        ...(context.metadata ?? {}),
        idempotencyKey,
      },
    });
    return { idempotencyKey };
  }

  const idempotencyKey = sink.idempotencyKey(raw, context);
  const record = await sink.transform(raw, {
    ...context,
    metadata: {
      ...(context.metadata ?? {}),
      idempotencyKey,
    },
  });
  await sink.upsert(record, context);
  return { idempotencyKey };
}

async function executeSyncResource(input: {
  providerRegistry: ProviderRegistry;
  actionExecutor: ActionExecutor;
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  connectionId: string;
  resource: string;
  mode: PlugFnSyncJob['mode'];
  userId: string;
  tenantId?: string;
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages: number;
  onPage?: (progress: {
    fetchedCount: number;
    persistedCount: number;
    skippedCount: number;
    cursor?: string;
    checkpoint?: unknown;
  }) => Promise<void> | void;
  shouldContinue?: () => Promise<boolean> | boolean;
}): Promise<{
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  cursor?: string;
  checkpoint?: unknown;
}> {
  const provider = input.providerRegistry.get(input.provider);
  if (!provider) {
    throw {
      code: 'PROVIDER_NOT_REGISTERED',
      message: `provider ${input.provider} is not registered`,
      status: 404,
    };
  }

  const syncDefinition = provider.sync?.[input.resource];
  if (syncDefinition) {
    return executeProviderSyncDefinition({ ...input, syncDefinition });
  }

  const fallbackAction = resolveSyncActionName(provider, input.resource);
  if (!fallbackAction) {
    throw {
      code: 'SYNC_RESOURCE_NOT_FOUND',
      message: `sync resource ${input.provider}.${input.resource} is not registered`,
      status: 404,
    };
  }

  if (input.shouldContinue && !(await input.shouldContinue())) {
    throw syncCancelledError();
  }

  const result = await input.actionExecutor.execute(input.provider, fallbackAction, {
    userId: input.userId,
    connectionId: input.connectionId,
    params: {
      tenantId: input.tenantId,
      mode: input.mode,
      checkpoint: input.checkpoint,
      cursor: input.cursor,
    },
    cache: false,
  });

  if (!result.success) {
    throw result.error;
  }

  const data = (result.data ?? {}) as Record<string, unknown>;
  const fallbackItems = resolveFallbackSyncItems(data);
  const fallbackSink = resolveFallbackSyncSink(input);
  const persistedCount = fallbackSink
    ? await persistFallbackSyncItems(fallbackSink, fallbackItems, input, fallbackAction)
    : asNumber(data.upserted) ?? asNumber(data.persistedCount) ?? 0;

  return {
    fetchedCount:
      asNumber(data.fetched) ??
      asNumber(data.fetchedCount) ??
      asNumber(data.count) ??
      fallbackItems?.length ??
      0,
    persistedCount,
    skippedCount: asNumber(data.skipped) ?? asNumber(data.skippedCount) ?? 0,
    checkpoint: data.checkpoint,
    cursor: typeof data.cursor === 'string' ? data.cursor : undefined,
  };
}

function resolveFallbackSyncSink(input: {
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  resource: string;
  sinkId?: string;
}): PlugFnPersistenceSink | undefined {
  if (input.sinkId) {
    const sink = input.persistenceSinks.get(input.sinkId);
    if (!sink) {
      throw new PlugFnRuntimeError(
        'SYNC_SINK_NOT_FOUND',
        `persistence sink ${input.sinkId} is not registered`,
        404
      );
    }
    return sink;
  }

  return [...input.persistenceSinks.values()].find((candidate) => {
    return candidate.provider === input.provider && candidate.resource === input.resource;
  });
}

async function persistFallbackSyncItems(
  sink: PlugFnPersistenceSink,
  items: unknown[] | undefined,
  input: { provider: string; resource: string; connectionId: string },
  fallbackAction: string
): Promise<number> {
  if (!items) {
    throw new PlugFnRuntimeError(
      'SYNC_FALLBACK_ITEMS_REQUIRED',
      `fallback action ${input.provider}.${fallbackAction} must return items for persistence`,
      500
    );
  }

  for (const item of items) {
    await persistSinkItem(sink, item, {
      provider: input.provider,
      resource: input.resource,
      connectionId: input.connectionId,
    });
  }
  return items.length;
}

function resolveFallbackSyncItems(data: Record<string, unknown>): unknown[] | undefined {
  if (Array.isArray(data.items)) {
    return data.items;
  }
  if (Array.isArray(data.messages)) {
    return data.messages;
  }
  return undefined;
}

async function executeProviderSyncDefinition(input: {
  syncDefinition: NonNullable<Provider['sync']>[string];
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  connectionId: string;
  resource: string;
  mode: PlugFnSyncJob['mode'];
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages: number;
  onPage?: (progress: {
    fetchedCount: number;
    persistedCount: number;
    skippedCount: number;
    cursor?: string;
    checkpoint?: unknown;
  }) => Promise<void> | void;
  shouldContinue?: () => Promise<boolean> | boolean;
}): Promise<{
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  cursor?: string;
  checkpoint?: unknown;
}> {
  let fetchedCount = 0;
  let persistedCount = 0;
  let skippedCount = 0;
  let cursor = input.cursor;
  let checkpoint = input.checkpoint ?? input.syncDefinition.initialCheckpoint;
  let pages = 0;

  while (pages < input.maxPages) {
    if (input.shouldContinue && !(await input.shouldContinue())) {
      throw syncCancelledError();
    }

    pages += 1;
    const result: PlugFnSyncFetchResult = await input.syncDefinition.fetch({
      provider: input.provider,
      resource: input.resource,
      connectionId: input.connectionId,
      mode: input.mode,
      checkpoint,
      cursor,
    });

    fetchedCount += result.items.length;
    checkpoint = result.checkpoint ?? checkpoint;
    cursor = result.cursor;

    const sinkId = input.sinkId ?? result.sinkId ?? input.syncDefinition.defaultSinkId;
    if (sinkId || input.persistenceSinks.size > 0) {
      const sink = sinkId
        ? input.persistenceSinks.get(sinkId)
        : [...input.persistenceSinks.values()].find((candidate) => {
            return candidate.provider === input.provider && candidate.resource === input.resource;
          });

      if (sink) {
        for (const item of result.items) {
          const context: PlugFnSinkContext = {
            provider: input.provider,
            resource: input.resource,
            connectionId: input.connectionId,
          };
          await persistSinkItem(sink, item, context);
          persistedCount += 1;
        }
      } else {
        skippedCount += result.items.length;
      }
    } else {
      skippedCount += result.items.length;
    }

    if (result.done !== false || !cursor) {
      await input.onPage?.({
        fetchedCount,
        persistedCount,
        skippedCount,
        cursor,
        checkpoint,
      });
      break;
    }

    await input.onPage?.({
      fetchedCount,
      persistedCount,
      skippedCount,
      cursor,
      checkpoint,
    });
  }

  return {
    fetchedCount,
    persistedCount,
    skippedCount,
    cursor,
    checkpoint,
  };
}

function syncCancelledError(): { code: string; message: string; status: number } {
  return {
    code: 'SYNC_CANCELLED',
    message: 'sync job was cancelled',
    status: 409,
  };
}

class PlugFnRuntimeError extends Error {
  readonly retryable = false;

  constructor(
    readonly code: string,
    message: string,
    readonly status: number
  ) {
    super(message);
    this.name = 'PlugFnRuntimeError';
  }
}

function isSyncCancelledError(error: unknown): boolean {
  return (
    !!error &&
    typeof error === 'object' &&
    'code' in error &&
    (error as { code?: unknown }).code === 'SYNC_CANCELLED'
  );
}

function resolveSyncActionName(provider: Provider, resource: string): string | undefined {
  const candidates = [
    `${resource}.sync`,
    `sync.${resource}`,
    resource === 'messages' ? 'mail.sync' : undefined,
  ].filter((candidate): candidate is string => typeof candidate === 'string');

  return candidates.find((candidate) => candidate in provider.actions);
}

function readSyncJobWorkerMetadata(job: PlugFnSyncJob): {
  sinkId?: string;
  maxPages?: number;
  actor?: PlugFnSyncRunOptions['actor'];
} {
  const raw = job.metadata?.plugfnSync;
  if (!raw || typeof raw !== 'object') {
    return {};
  }

  const record = raw as Record<string, unknown>;
  return {
    sinkId: typeof record.sinkId === 'string' ? record.sinkId : undefined,
    maxPages: typeof record.maxPages === 'number' ? record.maxPages : undefined,
    actor: isSyncActor(record.actor) ? record.actor : undefined,
  };
}

function isSyncActor(value: unknown): value is PlugFnSyncRunOptions['actor'] {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as { userId?: unknown }).userId === 'string'
  );
}

function connectionToOwner(connection: Connection): PlugFnConnectionOwner {
  if (connection.ownerKind === 'organization' && connection.organizationId && connection.installedByUserId) {
    return {
      kind: 'organization',
      organizationId: connection.organizationId,
      installedByUserId: connection.installedByUserId,
      tenantId: connection.tenantId,
    };
  }

  if (
    connection.ownerKind === 'delegated' &&
    connection.organizationId &&
    connection.installedByUserId &&
    connection.delegatedToUserId
  ) {
    return {
      kind: 'delegated',
      organizationId: connection.organizationId,
      installedByUserId: connection.installedByUserId,
      delegatedToUserId: connection.delegatedToUserId,
      grants: connection.grants ?? [],
      tenantId: connection.tenantId,
    };
  }

  return {
    kind: 'user',
    userId: connection.ownerId ?? connection.userId,
    tenantId: connection.tenantId,
  };
}

function asNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function normalizeAuthProvider(configuredAuth: PlugFnConfig['auth']): {
  authenticate(request: Request): Promise<PlugFnPrincipal | null>;
} {
  if (typeof configuredAuth.authenticate === 'function') {
    return {
      authenticate: async (request: Request) => {
        const principal = await configuredAuth.authenticate!(request);
        return normalizePrincipal(principal);
      },
    };
  }

  return {
    authenticate: async (request: Request) => {
      if (typeof configuredAuth.getUserId === 'function') {
        const userId = await configuredAuth.getUserId(request);
        return normalizePrincipal(userId);
      }

      if (typeof configuredAuth.requireAuth === 'function') {
        try {
          const userId = await configuredAuth.requireAuth(request);
          return normalizePrincipal(userId);
        } catch {
          return null;
        }
      }

      return null;
    },
  };
}

function normalizePrincipal(
  value: PlugFnPrincipal | AuthSession | string | null | undefined
): PlugFnPrincipal | null {
  if (!value) {
    return null;
  }

  if (typeof value === 'string') {
    return value.length > 0 ? { userId: value } : null;
  }

  if (
    typeof value === 'object' &&
    'userId' in value &&
    typeof value.userId === 'string' &&
    value.userId.length > 0
  ) {
    return value as PlugFnPrincipal;
  }

  const subject =
    typeof value === 'object' && 'subject' in value
      ? (value as Partial<AuthSession>).subject
      : null;
  if (
    subject !== null &&
    typeof subject === 'object' &&
    typeof subject.actorId === 'string' &&
    subject.actorId.length > 0
  ) {
    const session = value as AuthSession;
    return {
      userId: session.subject.actorId,
      tenantId: session.subject.tenantId,
      roles: session.resourceIds,
      grants: session.scopes,
      metadata: session.metadata,
    };
  }

  return null;
}

import { createHash, randomBytes } from 'node:crypto';
import { createRouter, type Middleware, type Route, type Router } from '@superfunctions/http';
import type { AuthSession } from '@superfunctions/auth';
import { ok as envelopeOk, err as envelopeErr } from '@superfunctions/envelope';
import { SuperfunctionError } from '@superfunctions/errors';
import type { PlugFn } from '../core/plug-fn.js';
import type { PlugFnPrincipal } from '../types/config.js';
import type { Connection, HandleCallbackResult } from '../types/connection.js';
import type { PlugFnApiEnvelope, PlugFnResponseMeta } from '../types/protocol.js';
import type { PlugFnConnectionOwner } from '../types/runtime.js';
import { connectionMatchesActor, hasAny } from '../security/tenancy.js';

export interface RouteAuthContext {
  userId: string;
  tenantId?: string;
  organizationId?: string;
  roles?: string[];
  grants?: string[];
}

export interface PlugFnRouterOptions {
  authenticate?: (request: Request) => Promise<RouteAuthContext | null> | RouteAuthContext | null;
  /** Fallback browser redirect when OAuth state has no returnTo (dev/examples). */
  defaultReturnTo?: string;
  webhookSecret?:
    | Record<string, string>
    | ((
        provider: string,
        request: Request,
        headers: Record<string, string>
      ) => Promise<string | undefined> | string | undefined);
  /** Resolve the direct client IP from trusted adapter/server metadata. */
  resolveWebhookClientIp?: (request: Request) => Promise<string | undefined> | string | undefined;
  maxWebhookPayloadBytes?: number;
}

interface PlugFnContext {
  plugFn: PlugFn;
  authContext?: RouteAuthContext;
}

interface DeterministicError {
  code: string;
  message: string;
  status: number;
  retryable: boolean;
  details: Record<string, unknown>;
}

interface ParseJsonBodyOptions {
  maxBytes?: number;
}

const DEFAULT_WEBHOOK_PAYLOAD_MAX_BYTES = 2 * 1024 * 1024;
const WEBHOOK_DELIVERY_LEASE_MS = 5 * 60 * 1000;
const WEBHOOK_INITIAL_RETRY_DELAY_MS = 30_000;
const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504]);

export function createPlugFnRouter(
  plugFn: PlugFn,
  options: PlugFnRouterOptions = {}
): Router<PlugFnContext> {
  const maxWebhookPayloadBytes =
    options.maxWebhookPayloadBytes ??
    plugFn.config.webhooks?.maxPayloadSize ??
    DEFAULT_WEBHOOK_PAYLOAD_MAX_BYTES;
  const authenticate = options.authenticate ?? plugFn.config.auth.authenticate;

  const requireAuth: Middleware<PlugFnContext> = async (request, context, next) => {
    try {
      const authContext = await resolveAuthContext(request, authenticate);
      if (!authContext) {
        return errorResponse({
          code: 'PLUGFN_AUTH_REQUIRED',
          message: 'authentication required',
          status: 401,
          retryable: false,
          details: {},
        });
      }

      context.authContext = authContext;
      assertIdentityMatchesQuery(new URL(request.url).searchParams, authContext);
      return next();
    } catch (error) {
      return errorResponse(toDeterministicError(error));
    }
  };

  const routes: Route<PlugFnContext>[] = [
    {
      method: 'GET',
      path: '/callback',
      handler: async (_req, ctx) => {
        const { code, state } = Object.fromEntries(ctx.query);

        if (!code || !state) {
          return errorResponse({
            code: 'VALIDATION_ERROR',
            message: 'missing code or state',
            status: 400,
            retryable: false,
            details: {},
          });
        }

        try {
          const result = await ctx.plugFn.connections.handleCallback({
            code,
            state,
          });

          return oauthCallbackResponse(ctx, result, options);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/callback/:provider',
      handler: async (_req, ctx) => {
        const { provider } = ctx.params;
        const { code, state } = Object.fromEntries(ctx.query);

        if (!code || !state) {
          return errorResponse({
            code: 'VALIDATION_ERROR',
            message: 'missing code or state',
            status: 400,
            retryable: false,
            details: {},
          });
        }

        try {
          assertProviderConfigured(ctx, provider);
          const result = await ctx.plugFn.connections.handleCallback({
            provider,
            code,
            state,
          });

          return oauthCallbackResponse(ctx, result, options);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/webhooks/:provider',
      handler: async (req, ctx) => {
        const { provider } = ctx.params;

        return handleWebhookRoute(req, ctx, provider, undefined, {
          maxWebhookPayloadBytes,
          webhookSecret: options.webhookSecret,
          resolveWebhookClientIp: options.resolveWebhookClientIp,
        });
      },
    },
    {
      method: 'POST',
      path: '/webhooks/:provider/:event',
      handler: async (req, ctx) => {
        const { provider, event } = ctx.params;

        return handleWebhookRoute(req, ctx, provider, event, {
          maxWebhookPayloadBytes,
          webhookSecret: options.webhookSecret,
          resolveWebhookClientIp: options.resolveWebhookClientIp,
        });
      },
    },
    {
      method: 'GET',
      path: '/healthz',
      handler: async () => successResponse({ status: 'ok' }),
    },
    {
      method: 'GET',
      path: '/readyz',
      handler: async (_req, ctx) => {
        try {
          await ctx.plugFn.ready;
        } catch (error) {
          return errorResponse({
            code: 'PLUGFN_NOT_READY',
            message: 'workflow trigger rehydration failed',
            status: 503,
            retryable: true,
            details: {
              error: error instanceof Error ? error.message : 'unknown initialization failure',
            },
          });
        }
        const configuredProviders = Object.keys(ctx.plugFn.config.integrations ?? {});
        const missingProviders = configuredProviders.filter(
          (provider) => !ctx.plugFn.providers.get(provider)
        );

        if (missingProviders.length > 0) {
          return errorResponse({
            code: 'PLUGFN_NOT_READY',
            message: 'configured providers are not registered',
            status: 503,
            retryable: true,
            details: { missingProviders },
          });
        }

        return successResponse({
          status: 'ready',
          providers: configuredProviders.length,
        });
      },
    },
    {
      method: 'GET',
      path: '/providers',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const providers = ctx.plugFn.providers.list();

        return successResponse({
          providers: providers.map((provider) => ({
            name: provider.name,
            displayName: provider.displayName,
            description: provider.description,
            authType: provider.auth.type,
          })),
        });
      },
    },
    {
      method: 'GET',
      path: '/connections',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const provider = ctx.query.get('provider');
        const authContext = requireAuthContext(ctx);

        const ownConnections = (
          await ctx.plugFn.connections.list({
            userId: authContext.userId,
            provider: provider || undefined,
          })
        ).filter((connection) => connectionMatchesActor(connection, authContext));
        let connections = ownConnections;
        if (
          authContext.organizationId &&
          hasAny(authContext.roles, ['admin', 'owner', 'org:admin'])
        ) {
          const organizationConnections = await ctx.plugFn.connections.list({
            userId: authContext.userId,
            provider: provider || undefined,
            owner: {
              kind: 'organization',
              organizationId: authContext.organizationId,
              installedByUserId: authContext.userId,
              tenantId: authContext.tenantId,
            },
          });
          connections = deduplicateConnections([
            ...ownConnections,
            ...organizationConnections,
          ]).filter((connection) => connectionMatchesActor(connection, authContext));
        }

        return successResponse({
          connections,
          userId: authContext.userId,
        });
      },
    },
    {
      method: 'GET',
      path: '/connections/:connectionId',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            ctx.params.connectionId,
            authContext,
            'read'
          );
          return successResponse({ connection });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/connections/:connectionId/status',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            ctx.params.connectionId,
            authContext,
            'read'
          );
          return successResponse({
            connection: {
              id: connection.id,
              provider: connection.provider,
              status: connection.status,
            },
          });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/connections/start',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          assertIdentityMatches(body, authContext);

          const provider = asString(body.provider);
          const redirectUri = asString(body.redirectUri);
          const scopes = asStringArray(body.scopes);
          const connectionName = asOptionalString(body.connectionName);
          const returnTo = asOptionalString(body.returnTo);
          const prompt = asOptionalString(body.prompt);
          const loginHint = asOptionalString(body.loginHint);
          const owner = asConnectionOwner(body.owner) ?? {
            kind: 'user',
            userId: authContext.userId,
            tenantId: authContext.tenantId,
          };

          if (!provider || !redirectUri) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, redirectUri',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          assertProviderConfigured(ctx, provider);
          const started = await ctx.plugFn.connections.start({
            userId: authContext.userId,
            provider,
            redirectUri,
            scopes,
            connectionName,
            returnTo,
            prompt,
            loginHint,
            owner,
            actor: {
              userId: authContext.userId,
              tenantId: authContext.tenantId,
              organizationId: authContext.organizationId,
            },
          });

          return successResponse(started);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/connections/disconnect',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          assertIdentityMatches(body, authContext);

          const provider = asString(body.provider);
          const connectionId = asOptionalString(body.connectionId);

          if (!provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required field: provider',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          if (!connectionId && authContext.tenantId) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connectionId is required for tenant-scoped disconnects',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          if (connectionId && !ctx.plugFn.config.authorization?.authorizeConnection) {
            await requireAuthorizedConnection(ctx, connectionId, authContext, 'disconnect');
          }

          const result = await ctx.plugFn.connections.disconnect({
            userId: authContext.userId,
            provider,
            connectionId,
            actor: authContext,
          });

          return successResponse({
            success: result.disconnected,
            ...result,
          });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/workflows',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const status = asOptionalString(ctx.query.get('status'));
        const authContext = requireAuthContext(ctx);

        const workflows = await ctx.plugFn.workflows.list({
          userId: authContext.userId,
          status: status as any,
        });

        return successResponse({
          workflows,
        });
      },
    },
    {
      method: 'POST',
      path: '/sync/jobs',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          const provider = asString(body.provider);
          const connectionId = asString(body.connectionId);
          const resource = asString(body.resource);
          const mode = body.mode === 'incremental' ? 'incremental' : 'full';

          if (!provider || !connectionId || !resource) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, connectionId, resource',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const connection = await requireAuthorizedConnection(
            ctx,
            connectionId,
            authContext,
            'sync'
          );
          if (connection.provider !== provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connection provider mismatch',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const job = await ctx.plugFn.sync[mode === 'incremental' ? 'incremental' : 'backfill']({
            provider,
            connectionId,
            resource,
            cursor: asOptionalString(body.cursor),
            checkpoint: body.checkpoint,
            sinkId: asOptionalString(body.sinkId),
            metadata: isPlainObject(body.metadata) ? body.metadata : undefined,
            actor: authContext,
          });

          return successResponse({ job });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/sync/jobs',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const provider = asOptionalString(ctx.query.get('provider'));
        const connectionId = asOptionalString(ctx.query.get('connectionId'));
        const status = asOptionalString(ctx.query.get('status'));
        const authContext = requireAuthContext(ctx);
        const filters: Record<string, unknown> = {};
        if (provider) {
          filters.provider = provider;
        }
        if (connectionId) {
          filters.connectionId = connectionId;
        }
        if (status) {
          filters.status = status;
        }

        const ownJobs = await filterAuthorizedSyncJobs(
          ctx,
          await ctx.plugFn.runtime.sync.listJobs({
            ...filters,
            ownerKind: 'user',
            ownerId: authContext.userId,
          }),
          authContext
        );
        let jobs = ownJobs;
        if (authContext.organizationId) {
          const organizationJobs = await ctx.plugFn.runtime.sync.listJobs({
            ...filters,
            ownerKind: 'organization',
            ownerId: authContext.organizationId,
          });
          const authorizedOrganizationJobs = await filterAuthorizedSyncJobs(
            ctx,
            organizationJobs,
            authContext
          );
          jobs = deduplicateSyncJobs([...ownJobs, ...authorizedOrganizationJobs]);
        }
        return successResponse({ jobs });
      },
    },
    {
      method: 'GET',
      path: '/sync/jobs/:jobId',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const authContext = requireAuthContext(ctx);
        const job = await requireAuthorizedSyncJob(ctx, ctx.params.jobId, authContext);
        return successResponse({ job });
      },
    },
    {
      method: 'POST',
      path: '/sync/jobs/:jobId/cancel',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          await requireAuthorizedSyncJob(ctx, ctx.params.jobId, authContext);
          const job = await ctx.plugFn.runtime.sync.cancelJob(ctx.params.jobId);
          return successResponse({ job });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/sync/checkpoints',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const provider = asString(body.provider);
          const connectionId = asString(body.connectionId);
          const resource = asString(body.resource);

          if (!provider || !connectionId || !resource) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, connectionId, resource',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            connectionId,
            authContext,
            'checkpoint'
          );
          if (connection.provider !== provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connection provider mismatch',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const checkpoint = await ctx.plugFn.runtime.sync.upsertCheckpoint({
            provider,
            connectionId,
            resource,
            checkpoint: body.checkpoint,
          });

          return successResponse({ checkpoint });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/events',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const authContext = requireAuthContext(ctx);
        const provider = asOptionalString(ctx.query.get('provider'));
        const event = asOptionalString(ctx.query.get('event'));
        const filters: Record<string, unknown> = {
          ownerKind: 'user',
          ownerId: authContext.userId,
        };
        if (provider) {
          filters.provider = provider;
        }
        if (event) {
          filters.event = event;
        }
        const events = await ctx.plugFn.runtime.events.list(filters);
        return successResponse({ events });
      },
    },
    {
      method: 'GET',
      path: '/metrics',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const timeRange = asOptionalString(ctx.query.get('timeRange'));
        const groupBy = asOptionalString(ctx.query.get('groupBy'));
        const provider = asOptionalString(ctx.query.get('provider'));
        const authContext = requireAuthContext(ctx);

        const metrics = await ctx.plugFn.getMetrics({
          timeRange: timeRange as any,
          groupBy: groupBy as any,
          provider,
          userId: authContext.userId,
        });

        return successResponse({
          metrics,
        });
      },
    },
  ];

  return createRouter<PlugFnContext>({
    context: { plugFn },
    routes,
  });
}

function requireAuthContext(context: PlugFnContext): RouteAuthContext {
  if (!context.authContext) {
    throw {
      code: 'PLUGFN_AUTH_REQUIRED',
      message: 'authentication required',
      status: 401,
    };
  }

  return context.authContext;
}

async function requireAuthorizedConnection(
  context: PlugFnContext,
  connectionId: string,
  authContext: RouteAuthContext,
  operation: 'read' | 'disconnect' | 'revoke' | 'sync' | 'action' | 'checkpoint'
): Promise<Connection> {
  const connection = await context.plugFn.connections.get(connectionId);
  return authorizeConnection(context, connection, authContext, operation);
}

async function authorizeConnection(
  context: PlugFnContext,
  connection: Connection,
  authContext: RouteAuthContext,
  operation: 'read' | 'disconnect' | 'revoke' | 'sync' | 'action' | 'checkpoint'
): Promise<Connection> {
  const customAuthorizer = context.plugFn.config.authorization?.authorizeConnection;
  if (customAuthorizer) {
    const allowed = await customAuthorizer({
      actor: authContext,
      connection,
      operation,
    });
    if (allowed) {
      return connection;
    }
  } else if (connectionMatchesActor(connection, authContext, operation)) {
    return connection;
  }

  throw {
    code: 'TENANT_ACCESS_DENIED',
    message: 'connection owner mismatch',
    status: 403,
  };
}

async function requireAuthorizedSyncJob(
  context: PlugFnContext,
  jobId: string,
  authContext: RouteAuthContext
) {
  const job = await context.plugFn.runtime.sync.getJob(jobId);
  if (!job) {
    throw {
      code: 'NOT_FOUND',
      message: 'sync job not found',
      status: 404,
    };
  }
  return authorizeSyncJob(context, job, authContext);
}

async function authorizeSyncJob(
  context: PlugFnContext,
  job: NonNullable<Awaited<ReturnType<PlugFn['runtime']['sync']['getJob']>>>,
  authContext: RouteAuthContext,
  connectionCache?: Map<string, Promise<Connection>>
) {
  let connectionPromise = connectionCache?.get(job.connectionId);
  if (!connectionPromise) {
    connectionPromise = context.plugFn.connections.get(job.connectionId);
    connectionCache?.set(job.connectionId, connectionPromise);
  }
  const connection = await connectionPromise;
  await authorizeConnection(context, connection, authContext, 'sync');
  return job;
}

async function filterAuthorizedSyncJobs(
  context: PlugFnContext,
  jobs: Awaited<ReturnType<PlugFn['runtime']['sync']['listJobs']>>,
  authContext: RouteAuthContext
) {
  const connectionCache = new Map<string, Promise<Connection>>();
  const authorizationResults = await Promise.all(
    jobs.map(async (job) => {
      try {
        await authorizeSyncJob(context, job, authContext, connectionCache);
        return job;
      } catch (error) {
        if (!isExpectedAuthorizationMiss(error)) {
          throw error;
        }
        return undefined;
      }
    })
  );
  return authorizationResults.filter((job): job is NonNullable<typeof job> => Boolean(job));
}

function deduplicateConnections(connections: Connection[]): Connection[] {
  return [...new Map(connections.map((connection) => [connection.id, connection])).values()];
}

function deduplicateSyncJobs(jobs: Awaited<ReturnType<PlugFn['runtime']['sync']['listJobs']>>) {
  return [...new Map(jobs.map((job) => [job.id, job])).values()];
}

function isExpectedAuthorizationMiss(error: unknown): boolean {
  if (!error || typeof error !== 'object' || !('code' in error)) {
    return false;
  }
  const code = (error as { code?: unknown }).code;
  return code === 'TENANT_ACCESS_DENIED' || code === 'NOT_FOUND' || code === 'CONNECTION_NOT_FOUND';
}

async function resolveAuthContext(
  request: Request,
  authenticate?: PlugFnRouterOptions['authenticate']
): Promise<RouteAuthContext | null> {
  if (!authenticate) {
    return null;
  }

  return normalizeAuthContext(await authenticate(request));
}

async function resolveWebhookSecret(
  provider: string,
  request: Request,
  headers: Record<string, string>,
  resolver: PlugFnRouterOptions['webhookSecret']
): Promise<string | undefined> {
  if (!resolver) {
    return undefined;
  }

  if (typeof resolver === 'function') {
    return await resolver(provider, request, headers);
  }

  return resolver[provider];
}

function normalizeHeaders(headers: Headers): Record<string, string> {
  const normalized: Record<string, string> = {};
  headers.forEach((value, key) => {
    normalized[key.toLowerCase()] = value;
  });
  return normalized;
}

async function handleWebhookRoute(
  req: Request,
  ctx: PlugFnContext,
  provider: string,
  event: string | undefined,
  options: Pick<PlugFnRouterOptions, 'webhookSecret' | 'resolveWebhookClientIp'> & {
    maxWebhookPayloadBytes: number;
  }
): Promise<Response> {
  let deliveryId: string | undefined;
  let deliveryAttempts = 0;
  let receiptId: string | undefined;
  let rawBody: Uint8Array | undefined;
  let headers: Record<string, string> | undefined;
  let payloadHash: string | undefined;
  let idempotencyKey: string | undefined;
  let resolvedEvent = event ?? 'event';
  let verificationStatus: 'verified' | 'not-required';

  try {
    headers = normalizeHeaders(req.headers);
    await assertWebhookSourceAllowed(
      req,
      ctx.plugFn.config.webhooks?.allowedIPs,
      options.resolveWebhookClientIp
    );
    if (provider.toLowerCase() === 'outlook') {
      const validationToken = new URL(req.url).searchParams.get('validationToken');
      if (validationToken !== null) {
        return new Response(validationToken, {
          status: 200,
          headers: { 'content-type': 'text/plain; charset=utf-8' },
        });
      }
    }
    rawBody = await readRequestBytes(req, { maxBytes: options.maxWebhookPayloadBytes });
    if (!event) {
      resolvedEvent = inferWebhookEvent(
        provider,
        headers,
        rawBody,
        ctx.plugFn.providers.get(provider)?.triggers
      );
    }
    const secret = await resolveWebhookSecret(provider, req, headers, options.webhookSecret);
    const currentPayloadHash = createHash('sha256').update(rawBody).digest('hex');
    payloadHash = currentPayloadHash;
    const verification = await ctx.plugFn.webhooks.verify(
      provider,
      resolvedEvent,
      undefined,
      headers,
      secret,
      { rawBody }
    );
    verificationStatus = verification.verified === false ? 'not-required' : 'verified';

    const slackChallenge = readSlackUrlVerificationChallenge(
      provider,
      verification.transformedPayload
    );
    if (slackChallenge !== undefined) {
      return Response.json({ challenge: slackChallenge });
    }

    try {
      await ctx.plugFn.ready;
    } catch (error) {
      throw {
        code: 'PLUGFN_NOT_READY',
        message: 'workflow trigger rehydration failed',
        status: 503,
        retryable: true,
        details: {
          error: error instanceof Error ? error.message : 'unknown initialization failure',
        },
      };
    }

    // Only verified payloads may claim a durable idempotency key. In
    // particular, Stripe event ids come from the body and are untrusted until
    // signature verification succeeds.
    idempotencyKey = readWebhookIdempotencyKey(provider, headers, rawBody);
    if (idempotencyKey) {
      const existing = await ctx.plugFn.runtime.webhooks.findReceiptByIdempotencyKey(
        provider,
        idempotencyKey
      );
      if (existing) {
        if (existing.payloadHash !== currentPayloadHash) {
          throw {
            code: 'WEBHOOK_IDEMPOTENCY_CONFLICT',
            message: 'webhook idempotency key was reused with a different payload',
            status: 409,
            retryable: false,
            details: {
              receiptId: existing.id,
            },
          };
        }
        if (
          existing.verificationStatus === 'verified' ||
          existing.verificationStatus === 'not-required'
        ) {
          const disposition = await webhookReceiptDisposition(ctx, existing);
          if (disposition === 'retry') {
            receiptId = existing.id;
          } else {
            return successResponse({
              duplicate: true,
              receiptId: existing.id,
              event: {
                provider,
                event: resolvedEvent,
                verified: true,
              },
            });
          }
        }
      }
    }

    const receiptClaimToken = idempotencyKey
      ? `claim_${randomBytes(12).toString('hex')}`
      : undefined;
    const receipt = await ctx.plugFn.runtime.webhooks.createReceipt({
      provider,
      event: resolvedEvent,
      payloadHash: currentPayloadHash,
      idempotencyKey,
      headersRedacted: redactHeaders(headers),
      verificationStatus,
      metadata: {
        contentType: headers['content-type'],
        userAgent: headers['user-agent'],
        ...(receiptClaimToken ? { receiptClaimToken } : {}),
      },
    });
    if (
      receiptClaimToken &&
      receipt.metadata?.receiptClaimToken !== receiptClaimToken &&
      (receipt.verificationStatus === 'verified' ||
        receipt.verificationStatus === 'not-required') &&
      (await webhookReceiptDisposition(ctx, receipt)) !== 'retry'
    ) {
      return successResponse({
        duplicate: true,
        receiptId: receipt.id,
        event: {
          provider,
          event: resolvedEvent,
          verified: true,
        },
      });
    }
    receiptId = receipt.id;
    if (receipt.verificationStatus !== verificationStatus) {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receipt.id, {
        verificationStatus,
      });
    }
    const delivery = await ctx.plugFn.runtime.webhooks.createDelivery({
      receiptId: receipt.id,
      handlerName: `${provider}.${resolvedEvent}`,
      status: 'running',
      metadata: {
        provider,
        event: resolvedEvent,
        payloadHash: currentPayloadHash,
        idempotencyKey,
      },
    });
    deliveryId = delivery.id;
    deliveryAttempts = delivery.attempts;

    const webhookEvent = await ctx.plugFn.webhooks.handle(
      provider,
      resolvedEvent,
      undefined,
      headers,
      secret,
      { rawBody }
    );

    await ctx.plugFn.runtime.webhooks.updateDelivery(delivery.id, {
      status: 'success',
      attempts: delivery.attempts + 1,
    });

    return successResponse({
      event: webhookEvent,
      receiptId: receipt.id,
      deliveryId: delivery.id,
    });
  } catch (error) {
    if (!receiptId) {
      await createFailedWebhookReceipt(
        ctx,
        provider,
        resolvedEvent,
        headers,
        payloadHash,
        idempotencyKey,
        error
      );
    } else if (!deliveryId) {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receiptId, {
        verificationStatus: 'failed',
        metadata: {
          error: error instanceof Error ? error.message : 'webhook handler failed',
        },
      });
    } else {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receiptId, {
        metadata: {
          error: error instanceof Error ? error.message : 'webhook handler failed',
        },
      });
    }
    if (deliveryId) {
      await ctx.plugFn.runtime.webhooks.updateDelivery(deliveryId, {
        status: 'failed',
        attempts: deliveryAttempts + 1,
        error: error instanceof Error ? error.message : 'webhook handler failed',
        nextAttemptAt: new Date(Date.now() + WEBHOOK_INITIAL_RETRY_DELAY_MS),
      });
    }
    return errorResponse(toDeterministicError(error));
  }
}

async function webhookReceiptDisposition(
  ctx: PlugFnContext,
  receipt: NonNullable<Awaited<ReturnType<PlugFn['runtime']['webhooks']['getReceipt']>>>
): Promise<'complete' | 'active' | 'retry'> {
  const deliveries = await ctx.plugFn.runtime.webhooks.listDeliveries(receipt.id);
  if (deliveries.some((delivery) => delivery.status === 'success')) {
    return 'complete';
  }

  const now = Date.now();
  if (
    deliveries.some(
      (delivery) =>
        delivery.status === 'running' &&
        now - new Date(delivery.updatedAt).getTime() < WEBHOOK_DELIVERY_LEASE_MS
    )
  ) {
    return 'active';
  }

  if (
    deliveries.length === 0 &&
    now - new Date(receipt.createdAt).getTime() < WEBHOOK_DELIVERY_LEASE_MS
  ) {
    return 'active';
  }

  return 'retry';
}

async function assertWebhookSourceAllowed(
  request: Request,
  allowedIPs: string[] | undefined,
  resolver: PlugFnRouterOptions['resolveWebhookClientIp']
): Promise<void> {
  if (!allowedIPs || allowedIPs.length === 0) {
    return;
  }

  const clientIp = await resolver?.(request);
  if (clientIp && allowedIPs.includes(clientIp)) {
    return;
  }

  throw {
    code: 'WEBHOOK_SOURCE_DENIED',
    message: 'webhook source is not allowed',
    status: 403,
    retryable: false,
  };
}

async function createFailedWebhookReceipt(
  ctx: PlugFnContext,
  provider: string,
  event: string,
  headers: Record<string, string> | undefined,
  payloadHash: string | undefined,
  idempotencyKey: string | undefined,
  error: unknown
): Promise<void> {
  if (!payloadHash) {
    return;
  }

  try {
    await ctx.plugFn.runtime.webhooks.createReceipt({
      provider,
      event,
      payloadHash,
      idempotencyKey,
      headersRedacted: headers ? redactHeaders(headers) : undefined,
      verificationStatus: 'failed',
      metadata: {
        error: error instanceof Error ? error.message : 'webhook verification failed',
      },
    });
  } catch {
    // A failed receipt is observability best-effort; the original deterministic error is returned.
  }
}

function inferWebhookEvent(
  provider: string,
  headers: Record<string, string>,
  rawBody?: Uint8Array,
  triggers: Record<string, unknown> = {}
): string {
  if (provider === 'github') {
    const family = headers['x-github-event'] || 'event';
    const action = readWebhookAction(rawBody);
    const actionEvent = action ? `${family}.${action}` : undefined;
    return actionEvent && actionEvent in triggers ? actionEvent : family;
  }
  if (provider === 'linear') {
    const family = (headers['linear-event'] || headers['x-linear-event'] || 'event')
      .trim()
      .toLowerCase()
      .replace(/[\s-]+/g, '_');
    const action = readWebhookAction(rawBody)?.trim().toLowerCase();
    const candidate =
      family === 'issue' && action === 'create'
        ? 'issue.created'
        : family === 'issue' && action === 'update'
          ? 'issue.updated'
          : (family === 'comment' || family === 'issue_comment') && action === 'create'
            ? 'issue_comment.created'
            : undefined;
    return candidate && candidate in triggers ? candidate : family;
  }
  if (provider === 'stripe') {
    return readWebhookStringField(rawBody, 'type') || 'event';
  }
  if (provider === 'gmail' || provider === 'google') {
    const resourceState = headers['x-goog-resource-state'];
    if (resourceState) {
      return resourceState;
    }
    if ('mail.update' in triggers && isGmailPubSubEnvelope(rawBody)) {
      return 'mail.update';
    }
    return 'message';
  }
  return headers['x-plugfn-event'] || 'event';
}

function isGmailPubSubEnvelope(rawBody?: Uint8Array): boolean {
  if (!rawBody || rawBody.byteLength === 0) {
    return false;
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(rawBody)) as Record<string, unknown>;
    const message = payload.message;
    return (
      typeof message === 'object' &&
      message !== null &&
      typeof (message as Record<string, unknown>).data === 'string'
    );
  } catch {
    return false;
  }
}

function readWebhookStringField(
  rawBody: Uint8Array | undefined,
  field: string
): string | undefined {
  if (!rawBody || rawBody.byteLength === 0) {
    return undefined;
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(rawBody)) as Record<string, unknown>;
    return typeof payload[field] === 'string' && payload[field].length > 0
      ? payload[field]
      : undefined;
  } catch {
    return undefined;
  }
}

function readWebhookAction(rawBody?: Uint8Array): string | undefined {
  return readWebhookStringField(rawBody, 'action');
}

function readSlackUrlVerificationChallenge(provider: string, payload: unknown): string | undefined {
  if (provider !== 'slack' || !payload || typeof payload !== 'object') {
    return undefined;
  }
  const value = payload as Record<string, unknown>;
  return value.type === 'url_verification' && typeof value.challenge === 'string'
    ? value.challenge
    : undefined;
}

function readWebhookIdempotencyKey(
  provider: string,
  headers: Record<string, string>,
  rawBody?: Uint8Array
): string | undefined {
  if (provider === 'stripe') {
    const eventId = readWebhookStringField(rawBody, 'id');
    if (eventId) {
      return eventId;
    }
  }

  return (
    headers['x-plugfn-delivery'] ||
    headers['x-github-delivery'] ||
    headers['linear-delivery'] ||
    headers['x-linear-delivery'] ||
    headers['x-goog-message-number'] ||
    headers[`${provider}-delivery`]
  );
}

function redactHeaders(headers: Record<string, string>): Record<string, string> {
  const redacted: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (
      key.includes('authorization') ||
      key.includes('signature') ||
      key.includes('secret') ||
      key.includes('token')
    ) {
      redacted[key] = '[redacted]';
      continue;
    }
    redacted[key] = value;
  }
  return redacted;
}

async function parseJsonBody(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<Record<string, any>> {
  return parseJsonText(await readRequestText(request, options));
}

async function readRequestBytes(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<Uint8Array> {
  const maxBytes = options.maxBytes;
  if (maxBytes !== undefined) {
    const contentLength = parseContentLength(request.headers.get('content-length'));
    if (contentLength !== undefined && contentLength > maxBytes) {
      throw payloadTooLargeError(maxBytes);
    }
  }

  try {
    const body = new Uint8Array(await request.arrayBuffer());
    if (maxBytes !== undefined && body.byteLength > maxBytes) {
      throw payloadTooLargeError(maxBytes);
    }
    return body;
  } catch (error) {
    if (
      error &&
      typeof error === 'object' &&
      'code' in (error as any) &&
      'status' in (error as any)
    ) {
      throw error;
    }
    return new Uint8Array();
  }
}

async function readRequestText(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<string> {
  const body = await readRequestBytes(request, options);
  return new TextDecoder().decode(body);
}

function parseJsonText(body: string): Record<string, any> {
  try {
    if (!body) {
      return {};
    }

    const parsed = JSON.parse(body);
    if (!parsed || typeof parsed !== 'object') {
      return {};
    }
    return parsed as Record<string, any>;
  } catch {
    return {};
  }
}

function assertIdentityMatches(body: Record<string, any>, authContext: RouteAuthContext): void {
  const bodyUserId = asOptionalString(body.userId);
  if (bodyUserId && bodyUserId !== authContext.userId) {
    throw identityMismatchError();
  }

  const bodyTenantId = asOptionalString(body.tenantId);
  if (bodyTenantId && authContext.tenantId && bodyTenantId !== authContext.tenantId) {
    throw identityMismatchError();
  }

  const bodyOrganizationId = asOptionalString(body.organizationId);
  if (
    bodyOrganizationId &&
    authContext.organizationId &&
    bodyOrganizationId !== authContext.organizationId
  ) {
    throw identityMismatchError();
  }

  const owner = asConnectionOwner(body.owner);
  if (!owner) {
    return;
  }

  assertOwnerMatchesAuthContext(owner, authContext);
}

function assertOwnerMatchesAuthContext(
  owner: PlugFnConnectionOwner,
  authContext: RouteAuthContext
): void {
  if (owner.tenantId && authContext.tenantId && owner.tenantId !== authContext.tenantId) {
    throw identityMismatchError();
  }

  if (owner.kind === 'user' && owner.userId !== authContext.userId) {
    throw identityMismatchError();
  }

  if (owner.kind === 'organization' && owner.installedByUserId !== authContext.userId) {
    throw identityMismatchError();
  }

  if (
    owner.kind === 'organization' &&
    (!authContext.organizationId || owner.organizationId !== authContext.organizationId)
  ) {
    throw identityMismatchError();
  }

  if (
    owner.kind === 'delegated' &&
    owner.installedByUserId !== authContext.userId &&
    owner.delegatedToUserId !== authContext.userId
  ) {
    throw identityMismatchError();
  }

  if (
    'organizationId' in owner &&
    authContext.organizationId &&
    owner.organizationId !== authContext.organizationId
  ) {
    throw identityMismatchError();
  }
}

function identityMismatchError(): SuperfunctionError {
  return new SuperfunctionError({
    code: 'TENANT_ACCESS_DENIED',
    message: 'identity mismatch',
    status: 403,
    retryable: false,
  });
}

function assertIdentityMatchesQuery(query: URLSearchParams, authContext: RouteAuthContext): void {
  assertIdentityMatches(
    {
      userId: query.get('user') ?? query.get('uid') ?? Object.fromEntries(query).userId,
      tenantId: Object.fromEntries(query).tenantId,
      organizationId: Object.fromEntries(query).organizationId,
    },
    authContext
  );
}

function normalizeAuthContext(
  principal: PlugFnPrincipal | AuthSession | null
): RouteAuthContext | null {
  if (!principal) {
    return null;
  }

  if ('subject' in principal) {
    return {
      userId: principal.subject.actorId,
      tenantId: principal.subject.tenantId,
      organizationId: asOptionalString(principal.metadata?.organizationId),
      roles: principal.resourceIds,
      grants: principal.scopes,
    };
  }

  return {
    userId: principal.userId,
    tenantId: principal.tenantId,
    organizationId:
      asOptionalString(principal.organizationId) ??
      asOptionalString(principal.metadata?.organizationId),
    roles: principal.roles,
    grants: principal.grants,
  };
}

function assertProviderConfigured(ctx: PlugFnContext, provider: string): void {
  if (!ctx.plugFn.providers.get(provider)) {
    throw {
      code: 'PROVIDER_NOT_REGISTERED',
      message: `provider ${provider} is not registered`,
      status: 404,
    };
  }

  if (!(provider in ctx.plugFn.config.integrations)) {
    throw {
      code: 'PROVIDER_NOT_CONFIGURED',
      message: `provider ${provider} is not configured`,
      status: 400,
    };
  }
}

function asString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function asOptionalString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function asStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const result = value.filter((entry): entry is string => {
    return typeof entry === 'string' && entry.length > 0;
  });

  return result.length > 0 ? result : undefined;
}

function asConnectionOwner(value: unknown): PlugFnConnectionOwner | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }

  if (value.kind === 'user' && typeof value.userId === 'string' && value.userId.length > 0) {
    return {
      kind: 'user',
      userId: value.userId,
      tenantId: asOptionalString(value.tenantId),
    };
  }

  if (
    value.kind === 'organization' &&
    typeof value.organizationId === 'string' &&
    typeof value.installedByUserId === 'string'
  ) {
    return {
      kind: 'organization',
      organizationId: value.organizationId,
      installedByUserId: value.installedByUserId,
      tenantId: asOptionalString(value.tenantId),
    };
  }

  if (
    value.kind === 'delegated' &&
    typeof value.organizationId === 'string' &&
    typeof value.installedByUserId === 'string' &&
    typeof value.delegatedToUserId === 'string' &&
    Array.isArray(value.grants)
  ) {
    return {
      kind: 'delegated',
      organizationId: value.organizationId,
      installedByUserId: value.installedByUserId,
      delegatedToUserId: value.delegatedToUserId,
      grants: value.grants.filter((grant): grant is string => typeof grant === 'string'),
      tenantId: asOptionalString(value.tenantId),
    };
  }

  return undefined;
}

function toDeterministicError(error: unknown): DeterministicError {
  if (error instanceof SuperfunctionError) {
    const superfunctionError = error as SuperfunctionError;
    return {
      code: superfunctionError.code,
      message: superfunctionError.message,
      status: superfunctionError.status,
      retryable: superfunctionError.retryable,
      details: superfunctionError.details ?? {},
    };
  }

  if (
    error &&
    typeof error === 'object' &&
    'code' in error &&
    'message' in error &&
    typeof (error as any).code === 'string' &&
    typeof (error as any).message === 'string'
  ) {
    const status =
      'status' in (error as any) && typeof (error as any).status === 'number'
        ? (error as any).status
        : 400;
    const retryable =
      'retryable' in (error as any) && typeof (error as any).retryable === 'boolean'
        ? (error as any).retryable
        : isRetryableStatus(status);
    const details =
      'details' in (error as any) && isPlainObject((error as any).details)
        ? ((error as any).details as Record<string, unknown>)
        : {};

    return {
      code: (error as any).code,
      message: (error as any).message,
      status,
      retryable,
      details,
    };
  }

  if (error instanceof Error) {
    return {
      code: 'VALIDATION_ERROR',
      message: error.message,
      status: 400,
      retryable: false,
      details: {},
    };
  }

  return {
    code: 'VALIDATION_ERROR',
    message: 'request failed',
    status: 400,
    retryable: false,
    details: {},
  };
}

function oauthCallbackResponse(
  ctx: PlugFnContext,
  result: HandleCallbackResult,
  routerOptions: PlugFnRouterOptions
): Response {
  const { connection, returnTo } = result;
  const redirectUrl = resolveReturnToRedirect(
    returnTo ?? routerOptions.defaultReturnTo,
    ctx.plugFn.config.baseUrl
  );

  if (redirectUrl) {
    return Response.redirect(redirectUrl, 302);
  }

  return successResponse({
    connection: {
      id: connection.id,
      provider: connection.provider,
      status: connection.status,
    },
  });
}

function resolveReturnToRedirect(returnTo: string | undefined, baseUrl: string): string | null {
  if (!returnTo) {
    return null;
  }

  const trimmed = returnTo.trim();
  if (!trimmed || trimmed.startsWith('//')) {
    return null;
  }

  if (trimmed.startsWith('/')) {
    try {
      const base = new URL(baseUrl);
      return `${base.origin}${trimmed}`;
    } catch {
      return null;
    }
  }

  let target: URL;
  try {
    target = new URL(trimmed);
  } catch {
    return null;
  }

  if (target.protocol !== 'http:' && target.protocol !== 'https:') {
    return null;
  }

  try {
    const base = new URL(baseUrl);
    if (target.origin === base.origin) {
      return target.toString();
    }
  } catch {
    return null;
  }

  if (/^(localhost|127\.0\.0\.1)$/i.test(target.hostname)) {
    return target.toString();
  }

  return null;
}

function successResponse(data: Record<string, unknown>): Response {
  const envelope = envelopeOk(data) as PlugFnApiEnvelope<Record<string, unknown>>;
  envelope.meta = createResponseMeta(envelope.meta?.timestamp);
  return Response.json(envelope);
}

function errorResponse(error: DeterministicError): Response {
  const details = isPlainObject(error.details) ? error.details : {};
  const envelope = envelopeErr({
    code: error.code,
    message: error.message,
    status: error.status,
    retryable: error.retryable,
    details,
  }) as PlugFnApiEnvelope;
  envelope.meta = createResponseMeta(envelope.meta?.timestamp);
  return Response.json(envelope, { status: error.status });
}

function createResponseMeta(timestamp = new Date().toISOString()): PlugFnResponseMeta {
  return {
    requestId: `req_${randomBytes(12).toString('hex')}`,
    timestamp,
  };
}

function parseContentLength(value: string | null): number | undefined {
  if (!value) {
    return undefined;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function payloadTooLargeError(maxBytes: number): DeterministicError {
  return {
    code: 'VALIDATION_ERROR',
    message: 'webhook payload exceeds configured max size',
    status: 413,
    retryable: false,
    details: {
      maxBytes,
    },
  };
}

function isRetryableStatus(status: number): boolean {
  return RETRYABLE_STATUS_CODES.has(status);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

import { createHash, randomBytes } from 'node:crypto';
import { createRouter, type Middleware, type Route, type Router } from '@superfunctions/http';
import type { AuthSession } from '@superfunctions/auth';
import { ok as envelopeOk, err as envelopeErr } from '@superfunctions/envelope';
import { SuperfunctionError } from '@superfunctions/errors';
import type { PlugFn } from '../core/plug-fn.js';
import type { PlugFnPrincipal } from '../types/config.js';
import type { Connection, HandleCallbackResult } from '../types/connection.js';
import type { PlugFnApiEnvelope, PlugFnResponseMeta } from '../types/protocol.js';
import type { PlugFnConnectionOwner } from '../types/runtime.js';
import { connectionMatchesActor, hasAny } from '../security/tenancy.js';

export interface RouteAuthContext {
  userId: string;
  tenantId?: string;
  organizationId?: string;
  roles?: string[];
  grants?: string[];
}

export interface PlugFnRouterOptions {
  authenticate?: (request: Request) => Promise<RouteAuthContext | null> | RouteAuthContext | null;
  /** Fallback browser redirect when OAuth state has no returnTo (dev/examples). */
  defaultReturnTo?: string;
  webhookSecret?:
    | Record<string, string>
    | ((
        provider: string,
        request: Request,
        headers: Record<string, string>
      ) => Promise<string | undefined> | string | undefined);
  /** Resolve the direct client IP from trusted adapter/server metadata. */
  resolveWebhookClientIp?: (
    request: Request
  ) => Promise<string | undefined> | string | undefined;
  maxWebhookPayloadBytes?: number;
}

interface PlugFnContext {
  plugFn: PlugFn;
  authContext?: RouteAuthContext;
}

interface DeterministicError {
  code: string;
  message: string;
  status: number;
  retryable: boolean;
  details: Record<string, unknown>;
}

interface ParseJsonBodyOptions {
  maxBytes?: number;
}

const DEFAULT_WEBHOOK_PAYLOAD_MAX_BYTES = 2 * 1024 * 1024;
const WEBHOOK_DELIVERY_LEASE_MS = 5 * 60 * 1000;
const WEBHOOK_INITIAL_RETRY_DELAY_MS = 30_000;
const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504]);

export function createPlugFnRouter(
  plugFn: PlugFn,
  options: PlugFnRouterOptions = {}
): Router<PlugFnContext> {
  const maxWebhookPayloadBytes =
    options.maxWebhookPayloadBytes ??
    plugFn.config.webhooks?.maxPayloadSize ??
    DEFAULT_WEBHOOK_PAYLOAD_MAX_BYTES;
  const authenticate = options.authenticate ?? plugFn.config.auth.authenticate;

  const requireAuth: Middleware<PlugFnContext> = async (request, context, next) => {
    try {
      const authContext = await resolveAuthContext(request, authenticate);
      if (!authContext) {
        return errorResponse({
          code: 'PLUGFN_AUTH_REQUIRED',
          message: 'authentication required',
          status: 401,
          retryable: false,
          details: {},
        });
      }

      context.authContext = authContext;
      assertIdentityMatchesQuery(new URL(request.url).searchParams, authContext);
      return next();
    } catch (error) {
      return errorResponse(toDeterministicError(error));
    }
  };

  const routes: Route<PlugFnContext>[] = [
    {
      method: 'GET',
      path: '/callback',
      handler: async (_req, ctx) => {
        const { code, state } = Object.fromEntries(ctx.query);

        if (!code || !state) {
          return errorResponse({
            code: 'VALIDATION_ERROR',
            message: 'missing code or state',
            status: 400,
            retryable: false,
            details: {},
          });
        }

        try {
          const result = await ctx.plugFn.connections.handleCallback({
            code,
            state,
          });

          return oauthCallbackResponse(ctx, result, options);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/callback/:provider',
      handler: async (_req, ctx) => {
        const { provider } = ctx.params;
        const { code, state } = Object.fromEntries(ctx.query);

        if (!code || !state) {
          return errorResponse({
            code: 'VALIDATION_ERROR',
            message: 'missing code or state',
            status: 400,
            retryable: false,
            details: {},
          });
        }

        try {
          assertProviderConfigured(ctx, provider);
          const result = await ctx.plugFn.connections.handleCallback({
            provider,
            code,
            state,
          });

          return oauthCallbackResponse(ctx, result, options);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/webhooks/:provider',
      handler: async (req, ctx) => {
        const { provider } = ctx.params;

        return handleWebhookRoute(req, ctx, provider, undefined, {
          maxWebhookPayloadBytes,
          webhookSecret: options.webhookSecret,
          resolveWebhookClientIp: options.resolveWebhookClientIp,
        });
      },
    },
    {
      method: 'POST',
      path: '/webhooks/:provider/:event',
      handler: async (req, ctx) => {
        const { provider, event } = ctx.params;

        return handleWebhookRoute(req, ctx, provider, event, {
          maxWebhookPayloadBytes,
          webhookSecret: options.webhookSecret,
          resolveWebhookClientIp: options.resolveWebhookClientIp,
        });
      },
    },
    {
      method: 'GET',
      path: '/healthz',
      handler: async () => successResponse({ status: 'ok' }),
    },
    {
      method: 'GET',
      path: '/readyz',
      handler: async (_req, ctx) => {
        try {
          await ctx.plugFn.ready;
        } catch (error) {
          return errorResponse({
            code: 'PLUGFN_NOT_READY',
            message: 'workflow trigger rehydration failed',
            status: 503,
            retryable: true,
            details: {
              error: error instanceof Error ? error.message : 'unknown initialization failure',
            },
          });
        }
        const configuredProviders = Object.keys(ctx.plugFn.config.integrations ?? {});
        const missingProviders = configuredProviders.filter((provider) => !ctx.plugFn.providers.get(provider));

        if (missingProviders.length > 0) {
          return errorResponse({
            code: 'PLUGFN_NOT_READY',
            message: 'configured providers are not registered',
            status: 503,
            retryable: true,
            details: { missingProviders },
          });
        }

        return successResponse({
          status: 'ready',
          providers: configuredProviders.length,
        });
      },
    },
    {
      method: 'GET',
      path: '/providers',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const providers = ctx.plugFn.providers.list();

        return successResponse({
          providers: providers.map((provider) => ({
            name: provider.name,
            displayName: provider.displayName,
            description: provider.description,
            authType: provider.auth.type,
          })),
        });
      },
    },
    {
      method: 'GET',
      path: '/connections',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const provider = ctx.query.get('provider');
        const authContext = requireAuthContext(ctx);

        const ownConnections = (
          await ctx.plugFn.connections.list({
            userId: authContext.userId,
            provider: provider || undefined,
          })
        ).filter((connection) => connectionMatchesActor(connection, authContext));
        let connections = ownConnections;
        if (
          authContext.organizationId &&
          hasAny(authContext.roles, ['admin', 'owner', 'org:admin'])
        ) {
          const organizationConnections = await ctx.plugFn.connections.list({
            userId: authContext.userId,
            provider: provider || undefined,
            owner: {
              kind: 'organization',
              organizationId: authContext.organizationId,
              installedByUserId: authContext.userId,
              tenantId: authContext.tenantId,
            },
          });
          connections = deduplicateConnections([...ownConnections, ...organizationConnections])
            .filter((connection) => connectionMatchesActor(connection, authContext));
        }

        return successResponse({
          connections,
          userId: authContext.userId,
        });
      },
    },
    {
      method: 'GET',
      path: '/connections/:connectionId',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            ctx.params.connectionId,
            authContext,
            'read'
          );
          return successResponse({ connection });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/connections/:connectionId/status',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            ctx.params.connectionId,
            authContext,
            'read'
          );
          return successResponse({
            connection: {
              id: connection.id,
              provider: connection.provider,
              status: connection.status,
            },
          });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/connections/start',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          assertIdentityMatches(body, authContext);

          const provider = asString(body.provider);
          const redirectUri = asString(body.redirectUri);
          const scopes = asStringArray(body.scopes);
          const connectionName = asOptionalString(body.connectionName);
          const returnTo = asOptionalString(body.returnTo);
          const prompt = asOptionalString(body.prompt);
          const loginHint = asOptionalString(body.loginHint);
          const owner = asConnectionOwner(body.owner) ?? {
            kind: 'user',
            userId: authContext.userId,
            tenantId: authContext.tenantId,
          };

          if (!provider || !redirectUri) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, redirectUri',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          assertProviderConfigured(ctx, provider);
          const started = await ctx.plugFn.connections.start({
            userId: authContext.userId,
            provider,
            redirectUri,
            scopes,
            connectionName,
            returnTo,
            prompt,
            loginHint,
            owner,
            actor: {
              userId: authContext.userId,
              tenantId: authContext.tenantId,
              organizationId: authContext.organizationId,
            },
          });

          return successResponse(started);
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/connections/disconnect',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          assertIdentityMatches(body, authContext);

          const provider = asString(body.provider);
          const connectionId = asOptionalString(body.connectionId);

          if (!provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required field: provider',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          if (!connectionId && authContext.tenantId) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connectionId is required for tenant-scoped disconnects',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          if (connectionId && !ctx.plugFn.config.authorization?.authorizeConnection) {
            await requireAuthorizedConnection(ctx, connectionId, authContext, 'disconnect');
          }

          const result = await ctx.plugFn.connections.disconnect({
            userId: authContext.userId,
            provider,
            connectionId,
            actor: authContext,
          });

          return successResponse({
            success: result.disconnected,
            ...result,
          });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/workflows',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const status = asOptionalString(ctx.query.get('status'));
        const authContext = requireAuthContext(ctx);

        const workflows = await ctx.plugFn.workflows.list({
          userId: authContext.userId,
          status: status as any,
        });

        return successResponse({
          workflows,
        });
      },
    },
    {
      method: 'POST',
      path: '/sync/jobs',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const authContext = requireAuthContext(ctx);
          const provider = asString(body.provider);
          const connectionId = asString(body.connectionId);
          const resource = asString(body.resource);
          const mode = body.mode === 'incremental' ? 'incremental' : 'full';

          if (!provider || !connectionId || !resource) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, connectionId, resource',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const connection = await requireAuthorizedConnection(
            ctx,
            connectionId,
            authContext,
            'sync'
          );
          if (connection.provider !== provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connection provider mismatch',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const job = await ctx.plugFn.sync[mode === 'incremental' ? 'incremental' : 'backfill']({
            provider,
            connectionId,
            resource,
            cursor: asOptionalString(body.cursor),
            checkpoint: body.checkpoint,
            sinkId: asOptionalString(body.sinkId),
            metadata: isPlainObject(body.metadata) ? body.metadata : undefined,
            actor: authContext,
          });

          return successResponse({ job });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/sync/jobs',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const provider = asOptionalString(ctx.query.get('provider'));
        const connectionId = asOptionalString(ctx.query.get('connectionId'));
        const status = asOptionalString(ctx.query.get('status'));
        const authContext = requireAuthContext(ctx);
        const filters: Record<string, unknown> = {};
        if (provider) {
          filters.provider = provider;
        }
        if (connectionId) {
          filters.connectionId = connectionId;
        }
        if (status) {
          filters.status = status;
        }

        const ownJobs = await filterAuthorizedSyncJobs(
          ctx,
          await ctx.plugFn.runtime.sync.listJobs({
            ...filters,
            ownerKind: 'user',
            ownerId: authContext.userId,
          }),
          authContext
        );
        let jobs = ownJobs;
        if (authContext.organizationId) {
          const organizationJobs = await ctx.plugFn.runtime.sync.listJobs({
            ...filters,
            ownerKind: 'organization',
            ownerId: authContext.organizationId,
          });
          const authorizedOrganizationJobs = await filterAuthorizedSyncJobs(
            ctx,
            organizationJobs,
            authContext
          );
          jobs = deduplicateSyncJobs([...ownJobs, ...authorizedOrganizationJobs]);
        }
        return successResponse({ jobs });
      },
    },
    {
      method: 'GET',
      path: '/sync/jobs/:jobId',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const authContext = requireAuthContext(ctx);
        const job = await requireAuthorizedSyncJob(ctx, ctx.params.jobId, authContext);
        return successResponse({ job });
      },
    },
    {
      method: 'POST',
      path: '/sync/jobs/:jobId/cancel',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        try {
          const authContext = requireAuthContext(ctx);
          await requireAuthorizedSyncJob(ctx, ctx.params.jobId, authContext);
          const job = await ctx.plugFn.runtime.sync.cancelJob(ctx.params.jobId);
          return successResponse({ job });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'POST',
      path: '/sync/checkpoints',
      middleware: [requireAuth],
      handler: async (req, ctx) => {
        try {
          const body = await parseJsonBody(req);
          const provider = asString(body.provider);
          const connectionId = asString(body.connectionId);
          const resource = asString(body.resource);

          if (!provider || !connectionId || !resource) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'missing required fields: provider, connectionId, resource',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const authContext = requireAuthContext(ctx);
          const connection = await requireAuthorizedConnection(
            ctx,
            connectionId,
            authContext,
            'checkpoint'
          );
          if (connection.provider !== provider) {
            return errorResponse({
              code: 'VALIDATION_ERROR',
              message: 'connection provider mismatch',
              status: 400,
              retryable: false,
              details: {},
            });
          }

          const checkpoint = await ctx.plugFn.runtime.sync.upsertCheckpoint({
            provider,
            connectionId,
            resource,
            checkpoint: body.checkpoint,
          });

          return successResponse({ checkpoint });
        } catch (error) {
          return errorResponse(toDeterministicError(error));
        }
      },
    },
    {
      method: 'GET',
      path: '/events',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const authContext = requireAuthContext(ctx);
        const provider = asOptionalString(ctx.query.get('provider'));
        const event = asOptionalString(ctx.query.get('event'));
        const filters: Record<string, unknown> = {
          ownerKind: 'user',
          ownerId: authContext.userId,
        };
        if (provider) {
          filters.provider = provider;
        }
        if (event) {
          filters.event = event;
        }
        const events = await ctx.plugFn.runtime.events.list(filters);
        return successResponse({ events });
      },
    },
    {
      method: 'GET',
      path: '/metrics',
      middleware: [requireAuth],
      handler: async (_req, ctx) => {
        const timeRange = asOptionalString(ctx.query.get('timeRange'));
        const groupBy = asOptionalString(ctx.query.get('groupBy'));
        const provider = asOptionalString(ctx.query.get('provider'));
        const authContext = requireAuthContext(ctx);

        const metrics = await ctx.plugFn.getMetrics({
          timeRange: timeRange as any,
          groupBy: groupBy as any,
          provider,
          userId: authContext.userId,
        });

        return successResponse({
          metrics,
        });
      },
    },
  ];

  return createRouter<PlugFnContext>({
    context: { plugFn },
    routes,
  });
}

function requireAuthContext(context: PlugFnContext): RouteAuthContext {
  if (!context.authContext) {
    throw {
      code: 'PLUGFN_AUTH_REQUIRED',
      message: 'authentication required',
      status: 401,
    };
  }

  return context.authContext;
}

async function requireAuthorizedConnection(
  context: PlugFnContext,
  connectionId: string,
  authContext: RouteAuthContext,
  operation: 'read' | 'disconnect' | 'revoke' | 'sync' | 'action' | 'checkpoint'
): Promise<Connection> {
  const connection = await context.plugFn.connections.get(connectionId);
  return authorizeConnection(context, connection, authContext, operation);
}

async function authorizeConnection(
  context: PlugFnContext,
  connection: Connection,
  authContext: RouteAuthContext,
  operation: 'read' | 'disconnect' | 'revoke' | 'sync' | 'action' | 'checkpoint'
): Promise<Connection> {
  const customAuthorizer = context.plugFn.config.authorization?.authorizeConnection;
  if (customAuthorizer) {
    const allowed = await customAuthorizer({
      actor: authContext,
      connection,
      operation,
    });
    if (allowed) {
      return connection;
    }
  } else if (connectionMatchesActor(connection, authContext, operation)) {
    return connection;
  }

  throw {
    code: 'TENANT_ACCESS_DENIED',
    message: 'connection owner mismatch',
    status: 403,
  };
}

async function requireAuthorizedSyncJob(
  context: PlugFnContext,
  jobId: string,
  authContext: RouteAuthContext
) {
  const job = await context.plugFn.runtime.sync.getJob(jobId);
  if (!job) {
    throw {
      code: 'NOT_FOUND',
      message: 'sync job not found',
      status: 404,
    };
  }
  return authorizeSyncJob(context, job, authContext);
}

async function authorizeSyncJob(
  context: PlugFnContext,
  job: NonNullable<Awaited<ReturnType<PlugFn['runtime']['sync']['getJob']>>>,
  authContext: RouteAuthContext,
  connectionCache?: Map<string, Promise<Connection>>
) {
  let connectionPromise = connectionCache?.get(job.connectionId);
  if (!connectionPromise) {
    connectionPromise = context.plugFn.connections.get(job.connectionId);
    connectionCache?.set(job.connectionId, connectionPromise);
  }
  const connection = await connectionPromise;
  await authorizeConnection(context, connection, authContext, 'sync');
  return job;
}

async function filterAuthorizedSyncJobs(
  context: PlugFnContext,
  jobs: Awaited<ReturnType<PlugFn['runtime']['sync']['listJobs']>>,
  authContext: RouteAuthContext
) {
  const connectionCache = new Map<string, Promise<Connection>>();
  const authorizationResults = await Promise.all(
    jobs.map(async (job) => {
      try {
        await authorizeSyncJob(context, job, authContext, connectionCache);
        return job;
      } catch (error) {
        if (!isExpectedAuthorizationMiss(error)) {
          throw error;
        }
        return undefined;
      }
    })
  );
  return authorizationResults.filter((job): job is NonNullable<typeof job> => Boolean(job));
}

function deduplicateConnections(connections: Connection[]): Connection[] {
  return [...new Map(connections.map((connection) => [connection.id, connection])).values()];
}

function deduplicateSyncJobs(
  jobs: Awaited<ReturnType<PlugFn['runtime']['sync']['listJobs']>>
) {
  return [...new Map(jobs.map((job) => [job.id, job])).values()];
}

function isExpectedAuthorizationMiss(error: unknown): boolean {
  if (!error || typeof error !== 'object' || !('code' in error)) {
    return false;
  }
  const code = (error as { code?: unknown }).code;
  return (
    code === 'TENANT_ACCESS_DENIED' ||
    code === 'NOT_FOUND' ||
    code === 'CONNECTION_NOT_FOUND'
  );
}

async function resolveAuthContext(
  request: Request,
  authenticate?: PlugFnRouterOptions['authenticate']
): Promise<RouteAuthContext | null> {
  if (!authenticate) {
    return null;
  }

  return normalizeAuthContext(await authenticate(request));
}

async function resolveWebhookSecret(
  provider: string,
  request: Request,
  headers: Record<string, string>,
  resolver: PlugFnRouterOptions['webhookSecret']
): Promise<string | undefined> {
  if (!resolver) {
    return undefined;
  }

  if (typeof resolver === 'function') {
    return await resolver(provider, request, headers);
  }

  return resolver[provider];
}

function normalizeHeaders(headers: Headers): Record<string, string> {
  const normalized: Record<string, string> = {};
  headers.forEach((value, key) => {
    normalized[key.toLowerCase()] = value;
  });
  return normalized;
}

async function handleWebhookRoute(
  req: Request,
  ctx: PlugFnContext,
  provider: string,
  event: string | undefined,
  options: Pick<PlugFnRouterOptions, 'webhookSecret' | 'resolveWebhookClientIp'> & {
    maxWebhookPayloadBytes: number;
  }
): Promise<Response> {
  let deliveryId: string | undefined;
  let deliveryAttempts = 0;
  let receiptId: string | undefined;
  let rawBody: Uint8Array | undefined;
  let headers: Record<string, string> | undefined;
  let payloadHash: string | undefined;
  let idempotencyKey: string | undefined;
  let resolvedEvent = event ?? 'event';
  let verificationStatus: 'verified' | 'not-required';

  try {
    try {
      await ctx.plugFn.ready;
    } catch (error) {
      throw {
        code: 'PLUGFN_NOT_READY',
        message: 'workflow trigger rehydration failed',
        status: 503,
        retryable: true,
        details: {
          error: error instanceof Error ? error.message : 'unknown initialization failure',
        },
      };
    }
    headers = normalizeHeaders(req.headers);
    await assertWebhookSourceAllowed(
      req,
      ctx.plugFn.config.webhooks?.allowedIPs,
      options.resolveWebhookClientIp
    );
    if (provider.toLowerCase() === 'outlook') {
      const validationToken = new URL(req.url).searchParams.get('validationToken');
      if (validationToken !== null) {
        return new Response(validationToken, {
          status: 200,
          headers: { 'content-type': 'text/plain; charset=utf-8' },
        });
      }
    }
    rawBody = await readRequestBytes(req, { maxBytes: options.maxWebhookPayloadBytes });
    if (!event) {
      resolvedEvent = inferWebhookEvent(
        provider,
        headers,
        rawBody,
        ctx.plugFn.providers.get(provider)?.triggers
      );
    }
    const secret = await resolveWebhookSecret(provider, req, headers, options.webhookSecret);
    const currentPayloadHash = createHash('sha256').update(rawBody).digest('hex');
    payloadHash = currentPayloadHash;
    const verification = await ctx.plugFn.webhooks.verify(
      provider,
      resolvedEvent,
      undefined,
      headers,
      secret,
      { rawBody }
    );
    verificationStatus = verification.verified === false ? 'not-required' : 'verified';

    const slackChallenge = readSlackUrlVerificationChallenge(
      provider,
      verification.transformedPayload
    );
    if (slackChallenge !== undefined) {
      return Response.json({ challenge: slackChallenge });
    }

    // Only verified payloads may claim a durable idempotency key. In
    // particular, Stripe event ids come from the body and are untrusted until
    // signature verification succeeds.
    idempotencyKey = readWebhookIdempotencyKey(provider, headers, rawBody);
    if (idempotencyKey) {
      const existing = await ctx.plugFn.runtime.webhooks.findReceiptByIdempotencyKey(
        provider,
        idempotencyKey
      );
      if (existing) {
        if (existing.payloadHash !== currentPayloadHash) {
          throw {
            code: 'WEBHOOK_IDEMPOTENCY_CONFLICT',
            message: 'webhook idempotency key was reused with a different payload',
            status: 409,
            retryable: false,
            details: {
              receiptId: existing.id,
            },
          };
        }
        if (
          existing.verificationStatus === 'verified' ||
          existing.verificationStatus === 'not-required'
        ) {
          const disposition = await webhookReceiptDisposition(ctx, existing);
          if (disposition === 'retry') {
            receiptId = existing.id;
          } else {
            return successResponse({
              duplicate: true,
              receiptId: existing.id,
              event: {
                provider,
                event: resolvedEvent,
                verified: true,
              },
            });
          }
        }
      }
    }

    const receiptClaimToken = idempotencyKey
      ? `claim_${randomBytes(12).toString('hex')}`
      : undefined;
    const receipt = await ctx.plugFn.runtime.webhooks.createReceipt({
      provider,
      event: resolvedEvent,
      payloadHash: currentPayloadHash,
      idempotencyKey,
      headersRedacted: redactHeaders(headers),
      verificationStatus,
      metadata: {
        contentType: headers['content-type'],
        userAgent: headers['user-agent'],
        ...(receiptClaimToken ? { receiptClaimToken } : {}),
      },
    });
    if (
      receiptClaimToken &&
      receipt.metadata?.receiptClaimToken !== receiptClaimToken &&
      (receipt.verificationStatus === 'verified' || receipt.verificationStatus === 'not-required') &&
      (await webhookReceiptDisposition(ctx, receipt)) !== 'retry'
    ) {
      return successResponse({
        duplicate: true,
        receiptId: receipt.id,
        event: {
          provider,
          event: resolvedEvent,
          verified: true,
        },
      });
    }
    receiptId = receipt.id;
    if (receipt.verificationStatus !== verificationStatus) {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receipt.id, {
        verificationStatus,
      });
    }
    const delivery = await ctx.plugFn.runtime.webhooks.createDelivery({
      receiptId: receipt.id,
      handlerName: `${provider}.${resolvedEvent}`,
      status: 'running',
      metadata: {
        provider,
        event: resolvedEvent,
        payloadHash: currentPayloadHash,
        idempotencyKey,
      },
    });
    deliveryId = delivery.id;
    deliveryAttempts = delivery.attempts;

    const webhookEvent = await ctx.plugFn.webhooks.handle(
      provider,
      resolvedEvent,
      undefined,
      headers,
      secret,
      { rawBody }
    );

    await ctx.plugFn.runtime.webhooks.updateDelivery(delivery.id, {
      status: 'success',
      attempts: delivery.attempts + 1,
    });

    return successResponse({
      event: webhookEvent,
      receiptId: receipt.id,
      deliveryId: delivery.id,
    });
  } catch (error) {
    if (!receiptId) {
      await createFailedWebhookReceipt(
        ctx,
        provider,
        resolvedEvent,
        headers,
        payloadHash,
        idempotencyKey,
        error
      );
    } else if (!deliveryId) {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receiptId, {
        verificationStatus: 'failed',
        metadata: {
          error: error instanceof Error ? error.message : 'webhook handler failed',
        },
      });
    } else {
      await ctx.plugFn.runtime.webhooks.updateReceipt(receiptId, {
        metadata: {
          error: error instanceof Error ? error.message : 'webhook handler failed',
        },
      });
    }
    if (deliveryId) {
      await ctx.plugFn.runtime.webhooks.updateDelivery(deliveryId, {
        status: 'failed',
        attempts: deliveryAttempts + 1,
        error: error instanceof Error ? error.message : 'webhook handler failed',
        nextAttemptAt: new Date(Date.now() + WEBHOOK_INITIAL_RETRY_DELAY_MS),
      });
    }
    return errorResponse(toDeterministicError(error));
  }
}

async function webhookReceiptDisposition(
  ctx: PlugFnContext,
  receipt: NonNullable<Awaited<ReturnType<PlugFn['runtime']['webhooks']['getReceipt']>>>
): Promise<'complete' | 'active' | 'retry'> {
  const deliveries = await ctx.plugFn.runtime.webhooks.listDeliveries(receipt.id);
  if (deliveries.some((delivery) => delivery.status === 'success')) {
    return 'complete';
  }

  const now = Date.now();
  if (
    deliveries.some(
      (delivery) =>
        delivery.status === 'running' &&
        now - new Date(delivery.updatedAt).getTime() < WEBHOOK_DELIVERY_LEASE_MS
    )
  ) {
    return 'active';
  }

  if (
    deliveries.length === 0 &&
    now - new Date(receipt.createdAt).getTime() < WEBHOOK_DELIVERY_LEASE_MS
  ) {
    return 'active';
  }

  return 'retry';
}

async function assertWebhookSourceAllowed(
  request: Request,
  allowedIPs: string[] | undefined,
  resolver: PlugFnRouterOptions['resolveWebhookClientIp']
): Promise<void> {
  if (!allowedIPs || allowedIPs.length === 0) {
    return;
  }

  const clientIp = await resolver?.(request);
  if (clientIp && allowedIPs.includes(clientIp)) {
    return;
  }

  throw {
    code: 'WEBHOOK_SOURCE_DENIED',
    message: 'webhook source is not allowed',
    status: 403,
    retryable: false,
  };
}

async function createFailedWebhookReceipt(
  ctx: PlugFnContext,
  provider: string,
  event: string,
  headers: Record<string, string> | undefined,
  payloadHash: string | undefined,
  idempotencyKey: string | undefined,
  error: unknown
): Promise<void> {
  if (!payloadHash) {
    return;
  }

  try {
    await ctx.plugFn.runtime.webhooks.createReceipt({
      provider,
      event,
      payloadHash,
      idempotencyKey,
      headersRedacted: headers ? redactHeaders(headers) : undefined,
      verificationStatus: 'failed',
      metadata: {
        error: error instanceof Error ? error.message : 'webhook verification failed',
      },
    });
  } catch {
    // A failed receipt is observability best-effort; the original deterministic error is returned.
  }
}

function inferWebhookEvent(
  provider: string,
  headers: Record<string, string>,
  rawBody?: Uint8Array,
  triggers: Record<string, unknown> = {}
): string {
  if (provider === 'github') {
    const family = headers['x-github-event'] || 'event';
    const action = readWebhookAction(rawBody);
    const actionEvent = action ? `${family}.${action}` : undefined;
    return actionEvent && actionEvent in triggers ? actionEvent : family;
  }
  if (provider === 'linear') {
    const family = (headers['linear-event'] || headers['x-linear-event'] || 'event')
      .trim()
      .toLowerCase()
      .replace(/[\s-]+/g, '_');
    const action = readWebhookAction(rawBody)?.trim().toLowerCase();
    const candidate =
      family === 'issue' && action === 'create'
        ? 'issue.created'
        : family === 'issue' && action === 'update'
          ? 'issue.updated'
          : (family === 'comment' || family === 'issue_comment') && action === 'create'
            ? 'issue_comment.created'
            : undefined;
    return candidate && candidate in triggers ? candidate : family;
  }
  if (provider === 'stripe') {
    return readWebhookStringField(rawBody, 'type') || 'event';
  }
  if (provider === 'gmail' || provider === 'google') {
    const resourceState = headers['x-goog-resource-state'];
    if (resourceState) {
      return resourceState;
    }
    if ('mail.update' in triggers && isGmailPubSubEnvelope(rawBody)) {
      return 'mail.update';
    }
    return 'message';
  }
  return headers['x-plugfn-event'] || 'event';
}

function isGmailPubSubEnvelope(rawBody?: Uint8Array): boolean {
  if (!rawBody || rawBody.byteLength === 0) {
    return false;
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(rawBody)) as Record<string, unknown>;
    const message = payload.message;
    return (
      typeof message === 'object' &&
      message !== null &&
      typeof (message as Record<string, unknown>).data === 'string'
    );
  } catch {
    return false;
  }
}

function readWebhookStringField(
  rawBody: Uint8Array | undefined,
  field: string
): string | undefined {
  if (!rawBody || rawBody.byteLength === 0) {
    return undefined;
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(rawBody)) as Record<string, unknown>;
    return typeof payload[field] === 'string' && payload[field].length > 0
      ? payload[field]
      : undefined;
  } catch {
    return undefined;
  }
}

function readWebhookAction(rawBody?: Uint8Array): string | undefined {
  return readWebhookStringField(rawBody, 'action');
}

function readSlackUrlVerificationChallenge(
  provider: string,
  payload: unknown
): string | undefined {
  if (provider !== 'slack' || !payload || typeof payload !== 'object') {
    return undefined;
  }
  const value = payload as Record<string, unknown>;
  return value.type === 'url_verification' && typeof value.challenge === 'string'
    ? value.challenge
    : undefined;
}

function readWebhookIdempotencyKey(
  provider: string,
  headers: Record<string, string>,
  rawBody?: Uint8Array
): string | undefined {
  if (provider === 'stripe') {
    const eventId = readWebhookStringField(rawBody, 'id');
    if (eventId) {
      return eventId;
    }
  }

  return (
    headers['x-plugfn-delivery'] ||
    headers['x-github-delivery'] ||
    headers['linear-delivery'] ||
    headers['x-linear-delivery'] ||
    headers['x-goog-message-number'] ||
    headers[`${provider}-delivery`]
  );
}

function redactHeaders(headers: Record<string, string>): Record<string, string> {
  const redacted: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (
      key.includes('authorization') ||
      key.includes('signature') ||
      key.includes('secret') ||
      key.includes('token')
    ) {
      redacted[key] = '[redacted]';
      continue;
    }
    redacted[key] = value;
  }
  return redacted;
}

async function parseJsonBody(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<Record<string, any>> {
  return parseJsonText(await readRequestText(request, options));
}

async function readRequestBytes(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<Uint8Array> {
  const maxBytes = options.maxBytes;
  if (maxBytes !== undefined) {
    const contentLength = parseContentLength(request.headers.get('content-length'));
    if (contentLength !== undefined && contentLength > maxBytes) {
      throw payloadTooLargeError(maxBytes);
    }
  }

  try {
    const body = new Uint8Array(await request.arrayBuffer());
    if (maxBytes !== undefined && body.byteLength > maxBytes) {
      throw payloadTooLargeError(maxBytes);
    }
    return body;
  } catch (error) {
    if (
      error &&
      typeof error === 'object' &&
      'code' in (error as any) &&
      'status' in (error as any)
    ) {
      throw error;
    }
    return new Uint8Array();
  }
}

async function readRequestText(
  request: Request,
  options: ParseJsonBodyOptions = {}
): Promise<string> {
  const body = await readRequestBytes(request, options);
  return new TextDecoder().decode(body);
}

function parseJsonText(body: string): Record<string, any> {
  try {
    if (!body) {
      return {};
    }

    const parsed = JSON.parse(body);
    if (!parsed || typeof parsed !== 'object') {
      return {};
    }
    return parsed as Record<string, any>;
  } catch {
    return {};
  }
}

function assertIdentityMatches(body: Record<string, any>, authContext: RouteAuthContext): void {
  const bodyUserId = asOptionalString(body.userId);
  if (bodyUserId && bodyUserId !== authContext.userId) {
    throw identityMismatchError();
  }

  const bodyTenantId = asOptionalString(body.tenantId);
  if (bodyTenantId && authContext.tenantId && bodyTenantId !== authContext.tenantId) {
    throw identityMismatchError();
  }

  const bodyOrganizationId = asOptionalString(body.organizationId);
  if (
    bodyOrganizationId &&
    authContext.organizationId &&
    bodyOrganizationId !== authContext.organizationId
  ) {
    throw identityMismatchError();
  }

  const owner = asConnectionOwner(body.owner);
  if (!owner) {
    return;
  }

  assertOwnerMatchesAuthContext(owner, authContext);
}

function assertOwnerMatchesAuthContext(
  owner: PlugFnConnectionOwner,
  authContext: RouteAuthContext
): void {
  if (owner.tenantId && authContext.tenantId && owner.tenantId !== authContext.tenantId) {
    throw identityMismatchError();
  }

  if (owner.kind === 'user' && owner.userId !== authContext.userId) {
    throw identityMismatchError();
  }

  if (
    owner.kind === 'organization' &&
    owner.installedByUserId !== authContext.userId
  ) {
    throw identityMismatchError();
  }

  if (
    owner.kind === 'organization' &&
    (!authContext.organizationId || owner.organizationId !== authContext.organizationId)
  ) {
    throw identityMismatchError();
  }

  if (
    owner.kind === 'delegated' &&
    owner.installedByUserId !== authContext.userId &&
    owner.delegatedToUserId !== authContext.userId
  ) {
    throw identityMismatchError();
  }

  if (
    'organizationId' in owner &&
    authContext.organizationId &&
    owner.organizationId !== authContext.organizationId
  ) {
    throw identityMismatchError();
  }
}

function identityMismatchError(): SuperfunctionError {
  return new SuperfunctionError({
    code: 'TENANT_ACCESS_DENIED',
    message: 'identity mismatch',
    status: 403,
    retryable: false,
  });
}

function assertIdentityMatchesQuery(
  query: URLSearchParams,
  authContext: RouteAuthContext
): void {
  assertIdentityMatches(
    {
      userId: query.get('user') ?? query.get('uid') ?? Object.fromEntries(query).userId,
      tenantId: Object.fromEntries(query).tenantId,
      organizationId: Object.fromEntries(query).organizationId,
    },
    authContext
  );
}

function normalizeAuthContext(principal: PlugFnPrincipal | AuthSession | null): RouteAuthContext | null {
  if (!principal) {
    return null;
  }

  if ('subject' in principal) {
    return {
      userId: principal.subject.actorId,
      tenantId: principal.subject.tenantId,
      organizationId: asOptionalString(principal.metadata?.organizationId),
      roles: principal.resourceIds,
      grants: principal.scopes,
    };
  }

  return {
    userId: principal.userId,
    tenantId: principal.tenantId,
    organizationId:
      asOptionalString(principal.organizationId) ??
      asOptionalString(principal.metadata?.organizationId),
    roles: principal.roles,
    grants: principal.grants,
  };
}

function assertProviderConfigured(ctx: PlugFnContext, provider: string): void {
  if (!ctx.plugFn.providers.get(provider)) {
    throw {
      code: 'PROVIDER_NOT_REGISTERED',
      message: `provider ${provider} is not registered`,
      status: 404,
    };
  }

  if (!(provider in ctx.plugFn.config.integrations)) {
    throw {
      code: 'PROVIDER_NOT_CONFIGURED',
      message: `provider ${provider} is not configured`,
      status: 400,
    };
  }
}

function asString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function asOptionalString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function asStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const result = value.filter((entry): entry is string => {
    return typeof entry === 'string' && entry.length > 0;
  });

  return result.length > 0 ? result : undefined;
}

function asConnectionOwner(value: unknown): PlugFnConnectionOwner | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }

  if (value.kind === 'user' && typeof value.userId === 'string' && value.userId.length > 0) {
    return {
      kind: 'user',
      userId: value.userId,
      tenantId: asOptionalString(value.tenantId),
    };
  }

  if (
    value.kind === 'organization' &&
    typeof value.organizationId === 'string' &&
    typeof value.installedByUserId === 'string'
  ) {
    return {
      kind: 'organization',
      organizationId: value.organizationId,
      installedByUserId: value.installedByUserId,
      tenantId: asOptionalString(value.tenantId),
    };
  }

  if (
    value.kind === 'delegated' &&
    typeof value.organizationId === 'string' &&
    typeof value.installedByUserId === 'string' &&
    typeof value.delegatedToUserId === 'string' &&
    Array.isArray(value.grants)
  ) {
    return {
      kind: 'delegated',
      organizationId: value.organizationId,
      installedByUserId: value.installedByUserId,
      delegatedToUserId: value.delegatedToUserId,
      grants: value.grants.filter((grant): grant is string => typeof grant === 'string'),
      tenantId: asOptionalString(value.tenantId),
    };
  }

  return undefined;
}

function toDeterministicError(error: unknown): DeterministicError {
  if (error instanceof SuperfunctionError) {
    const superfunctionError = error as SuperfunctionError;
    return {
      code: superfunctionError.code,
      message: superfunctionError.message,
      status: superfunctionError.status,
      retryable: superfunctionError.retryable,
      details: superfunctionError.details ?? {},
    };
  }

  if (
    error &&
    typeof error === 'object' &&
    'code' in error &&
    'message' in error &&
    typeof (error as any).code === 'string' &&
    typeof (error as any).message === 'string'
  ) {
    const status =
      'status' in (error as any) && typeof (error as any).status === 'number'
        ? (error as any).status
        : 400;
    const retryable =
      'retryable' in (error as any) && typeof (error as any).retryable === 'boolean'
        ? (error as any).retryable
        : isRetryableStatus(status);
    const details =
      'details' in (error as any) && isPlainObject((error as any).details)
        ? ((error as any).details as Record<string, unknown>)
        : {};

    return {
      code: (error as any).code,
      message: (error as any).message,
      status,
      retryable,
      details,
    };
  }

  if (error instanceof Error) {
    return {
      code: 'VALIDATION_ERROR',
      message: error.message,
      status: 400,
      retryable: false,
      details: {},
    };
  }

  return {
    code: 'VALIDATION_ERROR',
    message: 'request failed',
    status: 400,
    retryable: false,
    details: {},
  };
}

function oauthCallbackResponse(
  ctx: PlugFnContext,
  result: HandleCallbackResult,
  routerOptions: PlugFnRouterOptions
): Response {
  const { connection, returnTo } = result;
  const redirectUrl = resolveReturnToRedirect(
    returnTo ?? routerOptions.defaultReturnTo,
    ctx.plugFn.config.baseUrl
  );

  if (redirectUrl) {
    return Response.redirect(redirectUrl, 302);
  }

  return successResponse({
    connection: {
      id: connection.id,
      provider: connection.provider,
      status: connection.status,
    },
  });
}

function resolveReturnToRedirect(returnTo: string | undefined, baseUrl: string): string | null {
  if (!returnTo) {
    return null;
  }

  const trimmed = returnTo.trim();
  if (!trimmed || trimmed.startsWith('//')) {
    return null;
  }

  if (trimmed.startsWith('/')) {
    try {
      const base = new URL(baseUrl);
      return `${base.origin}${trimmed}`;
    } catch {
      return null;
    }
  }

  let target: URL;
  try {
    target = new URL(trimmed);
  } catch {
    return null;
  }

  if (target.protocol !== 'http:' && target.protocol !== 'https:') {
    return null;
  }

  try {
    const base = new URL(baseUrl);
    if (target.origin === base.origin) {
      return target.toString();
    }
  } catch {
    return null;
  }

  if (/^(localhost|127\.0\.0\.1)$/i.test(target.hostname)) {
    return target.toString();
  }

  return null;
}

function successResponse(data: Record<string, unknown>): Response {
  const envelope = envelopeOk(data) as PlugFnApiEnvelope<Record<string, unknown>>;
  envelope.meta = createResponseMeta(envelope.meta?.timestamp);
  return Response.json(envelope);
}

function errorResponse(error: DeterministicError): Response {
  const details = isPlainObject(error.details) ? error.details : {};
  const envelope = envelopeErr({
    code: error.code,
    message: error.message,
    status: error.status,
    retryable: error.retryable,
    details,
  }) as PlugFnApiEnvelope;
  envelope.meta = createResponseMeta(envelope.meta?.timestamp);
  return Response.json(
    envelope,
    { status: error.status }
  );
}

function createResponseMeta(timestamp = new Date().toISOString()): PlugFnResponseMeta {
  return {
    requestId: `req_${randomBytes(12).toString('hex')}`,
    timestamp,
  };
}

function parseContentLength(value: string | null): number | undefined {
  if (!value) {
    return undefined;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function payloadTooLargeError(maxBytes: number): DeterministicError {
  return {
    code: 'VALIDATION_ERROR',
    message: 'webhook payload exceeds configured max size',
    status: 413,
    retryable: false,
    details: {
      maxBytes,
    },
  };
}

function isRetryableStatus(status: number): boolean {
  return RETRYABLE_STATUS_CODES.has(status);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

import type { TableSchema } from '@superfunctions/db';
import {
  getOAuthStorageTableDefinitions,
  type OAuthStorageTableDefinition,
} from '@superfunctions/oauth-storage';
import {
  DEFAULT_PLUGFN_STORAGE_MODELS,
  resolvePlugFnStorageModels,
  type PlugFnStorageModelMapping,
} from './storage/adapters/database.js';

