        async with self._ready_lock:
            if self._ready:
                return
            result = await self.rehydrate_enabled_triggers()
            if result["failed"]:
                raise WorkflowEngineError(
                    "WORKFLOW_TRIGGER_REHYDRATION_FAILED",
                    f"Failed to rehydrate {result['failed']} workflow trigger(s)",
