  ): Promise<PlugFnSyncJob> {
    const updated = await this.adapter.database.updateMany({
      model: this.adapter.models.syncJobs,
      where: [
        { field: 'id', operator: 'eq', value: id },
        { field: 'status', operator: 'eq', value: 'running' },
