): value is PlugFnDatabaseStorageAdapter {
  return (
    typeof value === 'object' &&
    value !== null &&
    'database' in value &&
    'models' in value &&
    typeof (value as PlugFnDatabaseStorageAdapter).getConnection === 'function'
  );
}

