function toWhereClauses(filters: Record<string, unknown>): WhereClause[] {
  const where: WhereClause[] = [];

  for (const [field, value] of Object.entries(filters)) {
    if (value === undefined) {
      continue;
    }
    where.push({ field, operator: 'eq', value });
  }

  return where;
}

