  metadata: Record<string, unknown> | undefined,
  workerId: string,
  claimedAt: Date
): Record<string, unknown> {
  return {
    ...(metadata ?? {}),
    workerClaim: {
      workerId,
      claimedAt: claimedAt.toISOString(),
    },
  };
}

