} from '../types/runtime.js';
import {
  ensurePlugFnDatabaseAdapter,
  type PlugFnDatabaseStorageAdapter,
} from './adapters/database.js';

export interface CreateProviderInstallationInput {
  provider: string;
  owner: PlugFnConnectionOwner;
  scopes?: string[];
  metadata?: Record<string, unknown>;
}

export interface CreateConnectionGrantInput {
  connectionId: string;
  granteeUserId: string;
  grant: string;
  expiresAt?: Date;
}

export interface CreateWebhookReceiptInput {
  provider: string;
  event: string;
  payloadHash: string;
  idempotencyKey?: string;
  connectionId?: string;
  owner?: PlugFnConnectionOwner;
  headersRedacted?: Record<string, string>;
  verificationStatus?: PlugFnWebhookReceipt['verificationStatus'];
  metadata?: Record<string, unknown>;
}

export interface CreateWebhookDeliveryInput {
  receiptId: string;
  sinkId?: string;
  handlerName?: string;
  status?: PlugFnWebhookDelivery['status'];
  nextAttemptAt?: Date;
  metadata?: Record<string, unknown>;
}

export interface CreateSyncJobInput {
  provider: string;
  connectionId: string;
  resource: string;
  mode: PlugFnSyncJob['mode'];
  owner?: PlugFnConnectionOwner;
  cursor?: string;
  checkpoint?: unknown;
  metadata?: Record<string, unknown>;
}

export interface UpdateSyncJobProgressInput {
  status?: PlugFnSyncJob['status'];
  claimToken?: string;
  cursor?: string;
  checkpoint?: unknown;
  fetchedCount?: number;
  persistedCount?: number;
  skippedCount?: number;
  error?: string;
}

export class AdapterRuntimeStorage {
  private readonly adapter: PlugFnDatabaseStorageAdapter;
  private readonly webhookReceiptClaimLocks = new Map<string, Promise<void>>();
  private readonly syncCheckpointLocks = new Map<string, Promise<void>>();

  constructor(adapter: DbAdapter | PlugFnDatabaseStorageAdapter) {
    this.adapter = ensurePlugFnDatabaseAdapter(adapter);
  }

  createProviderInstallation(
    input: CreateProviderInstallationInput
  ): Promise<PlugFnProviderInstallation> {
    const now = new Date();
    const owner = ownerFields(input.owner);
    if (!owner.ownerKind || !owner.ownerId) {
      throw new Error('provider installation owner is required');
    }
    return this.adapter.createProviderInstallation({
      id: generateId('install'),
      provider: input.provider,
      ownerKind: owner.ownerKind,
      ownerId: owner.ownerId,
      tenantId: owner.tenantId,
      organizationId: owner.organizationId,
      installedByUserId: owner.installedByUserId,
      delegatedToUserId: owner.delegatedToUserId,
      status: 'active',
      scopes: input.scopes,
      metadata: input.metadata,
      createdAt: now,
      updatedAt: now,
    });
  }

  listProviderInstallations(
    filters: Record<string, unknown> = {}
  ): Promise<PlugFnProviderInstallation[]> {
    return this.adapter.listProviderInstallations(filters);
  }

  updateProviderInstallation(
    id: string,
    updates: Partial<PlugFnProviderInstallation>
  ): Promise<PlugFnProviderInstallation> {
    return this.adapter.updateProviderInstallation(id, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  createConnectionGrant(input: CreateConnectionGrantInput): Promise<PlugFnConnectionGrant> {
    return this.adapter.createConnectionGrant({
      id: generateId('grant'),
      connectionId: input.connectionId,
      granteeUserId: input.granteeUserId,
      grant: input.grant,
      expiresAt: input.expiresAt,
      createdAt: new Date(),
    });
  }

  listConnectionGrants(connectionId: string): Promise<PlugFnConnectionGrant[]> {
    return this.adapter.listConnectionGrants(connectionId);
  }

  deleteConnectionGrant(id: string): Promise<void> {
    return this.adapter.deleteConnectionGrant(id);
  }

  async createWebhookReceipt(input: CreateWebhookReceiptInput): Promise<PlugFnWebhookReceipt> {
    if (!input.idempotencyKey) {
      return this.persistWebhookReceipt(input);
    }

    const claimKey = `${input.provider}:${input.idempotencyKey}`;
    return this.withWebhookReceiptClaimLock(claimKey, async () => {
      const existing = await this.adapter.findWebhookReceiptByIdempotencyKey(
        input.provider,
        input.idempotencyKey!
      );
      if (existing) {
        return assertMatchingWebhookReceipt(existing, input.payloadHash);
      }

      try {
        return await this.persistWebhookReceipt(input);
      } catch (error) {
        // A unique provider/idempotency index arbitrates claims across runtime instances.
        const concurrentlyCreated = await this.adapter.findWebhookReceiptByIdempotencyKey(
          input.provider,
          input.idempotencyKey!
        );
        if (concurrentlyCreated) {
          return assertMatchingWebhookReceipt(concurrentlyCreated, input.payloadHash);
        }
        throw error;
      }
    });
  }

  private persistWebhookReceipt(input: CreateWebhookReceiptInput): Promise<PlugFnWebhookReceipt> {
    const now = new Date();
    return this.adapter.createWebhookReceipt({
      id: generateId('whrec'),
      provider: input.provider,
      event: input.event,
      idempotencyKey: input.idempotencyKey,
      connectionId: input.connectionId,
      ...ownerFields(input.owner),
      headersRedacted: input.headersRedacted,
      payloadHash: input.payloadHash,
      verificationStatus: input.verificationStatus ?? 'not-required',
      receivedAt: now,
      createdAt: now,
      metadata: input.metadata,
    });
  }

  private async withWebhookReceiptClaimLock<T>(key: string, work: () => Promise<T>): Promise<T> {
    const previous = this.webhookReceiptClaimLocks.get(key) ?? Promise.resolve();
    let release!: () => void;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });
    const tail = previous.catch(() => {}).then(() => current);
    this.webhookReceiptClaimLocks.set(key, tail);

    await previous.catch(() => {});
    try {
      return await work();
    } finally {
      release();
      if (this.webhookReceiptClaimLocks.get(key) === tail) {
        this.webhookReceiptClaimLocks.delete(key);
      }
    }
  }

  getWebhookReceipt(id: string): Promise<PlugFnWebhookReceipt | null> {
    return this.adapter.getWebhookReceipt(id);
  }

  findWebhookReceiptByIdempotencyKey(
    provider: string,
    idempotencyKey: string
  ): Promise<PlugFnWebhookReceipt | null> {
    return this.adapter.findWebhookReceiptByIdempotencyKey(provider, idempotencyKey);
  }

  async updateWebhookReceipt(
    id: string,
    updates: Partial<PlugFnWebhookReceipt>
  ): Promise<PlugFnWebhookReceipt> {
    const normalizedUpdates = { ...updates };
    if (updates.metadata !== undefined) {
      const metadata: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(updates.metadata ?? {})) {
        if (value === undefined) {
          continue;
        }
        metadata[key] = value;
      }
      // Receipt metadata uses replacement semantics. Avoid a cross-instance
      // read/merge/write race and always preserve the runtime-owned timestamp.
      metadata.updatedAt = new Date().toISOString();
      normalizedUpdates.metadata = metadata;
    }
    return this.adapter.updateWebhookReceipt(id, normalizedUpdates);
  }

  createWebhookDelivery(input: CreateWebhookDeliveryInput): Promise<PlugFnWebhookDelivery> {
    const now = new Date();
    return this.adapter.createWebhookDelivery({
      id: generateId('whdel'),
      receiptId: input.receiptId,
      sinkId: input.sinkId,
      handlerName: input.handlerName,
      status: input.status ?? 'pending',
      attempts: 0,
      nextAttemptAt: input.nextAttemptAt,
      metadata: input.metadata,
      createdAt: now,
      updatedAt: now,
    });
  }

  updateWebhookDelivery(
    id: string,
    updates: Partial<PlugFnWebhookDelivery>
  ): Promise<PlugFnWebhookDelivery> {
    return this.adapter.updateWebhookDelivery(id, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  updateClaimedWebhookDelivery(
    id: string,
    claimToken: string,
    updates: Partial<PlugFnWebhookDelivery>
  ): Promise<PlugFnWebhookDelivery | null> {
    return this.adapter.updateClaimedWebhookDelivery(id, claimToken, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  listWebhookDeliveries(receiptId: string): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.listWebhookDeliveries(receiptId);
  }

  listWebhookDeliveriesForRetry(
    now = new Date(),
    limit = 100,
    leaseMs?: number
  ): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.listWebhookDeliveriesForRetry(now, limit, leaseMs);
  }

  claimWebhookDeliveriesForRetry(
    now = new Date(),
    limit = 100,
    workerId = generateId('webhook_worker'),
    leaseMs?: number
  ): Promise<PlugFnWebhookDelivery[]> {
    return this.adapter.claimWebhookDeliveriesForRetry(now, limit, workerId, leaseMs);
  }

  createSyncJob(input: CreateSyncJobInput): Promise<PlugFnSyncJob> {
    const now = new Date();
    return this.adapter.createSyncJob({
      id: generateId('sync'),
      provider: input.provider,
      connectionId: input.connectionId,
      resource: input.resource,
      mode: input.mode,
      status: 'queued',
      ...ownerFields(input.owner),
      cursor: input.cursor,
      checkpoint: input.checkpoint,
      fetchedCount: 0,
      persistedCount: 0,
      skippedCount: 0,
      metadata: input.metadata,
      createdAt: now,
      updatedAt: now,
    });
  }

  getSyncJob(id: string): Promise<PlugFnSyncJob | null> {
    return this.adapter.getSyncJob(id);
  }

  listSyncJobs(filters: Record<string, unknown> = {}, limit = 100): Promise<PlugFnSyncJob[]> {
    return this.adapter.listSyncJobs(filters, limit);
  }

  claimQueuedSyncJobs(
    limit = 25,
    leaseMs?: number,
    workerId = generateId('sync_worker')
  ): Promise<PlugFnSyncJob[]> {
    return this.adapter.claimQueuedSyncJobs(limit, workerId, leaseMs);
  }

  updateSyncJob(id: string, updates: UpdateSyncJobProgressInput): Promise<PlugFnSyncJob> {
    return this.adapter.updateSyncJob(id, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  updateClaimedSyncJob(
    id: string,
    claimToken: string,
    updates: UpdateSyncJobProgressInput = {}
  ): Promise<PlugFnSyncJob | null> {
    return this.adapter.updateClaimedSyncJob(id, claimToken, {
      ...updates,
      updatedAt: new Date(),
    });
  }

  checkpointClaimedSyncJob(
    id: string,
    claimToken: string,
    updates: UpdateSyncJobProgressInput,
    checkpointInput?: {
      provider: string;
      connectionId: string;
      resource: string;
      checkpoint: unknown;
    }
  ): Promise<PlugFnSyncJob | null> {
    return this.withSyncCheckpointLock(id, async () => {
      if (!this.adapter.database.capabilities.transactions.supported) {
        const job = await this.updateClaimedSyncJob(id, claimToken, updates);
        if (!job) {
          return null;
        }
        if (checkpointInput) {
          await this.upsertSyncCheckpoint(checkpointInput);
        }
        return job;
      }

      return this.adapter.database.transaction(async (transaction) => {
        let job: PlugFnSyncJob;
        try {
          job = await transaction.update<PlugFnSyncJob>({
            model: this.adapter.models.syncJobs,
            where: [
              { field: 'id', operator: 'eq', value: id },
              { field: 'status', operator: 'eq', value: 'running' },
              { field: 'claimToken', operator: 'eq', value: claimToken },
            ],
            data: {
              ...updates,
              updatedAt: new Date(),
            },
          });
        } catch (error) {
          if (error instanceof NotFoundError) {
            return null;
          }
          throw error;
        }

        if (checkpointInput) {
          const now = new Date();
          await transaction.upsert<PlugFnSyncCheckpoint>({
            model: this.adapter.models.syncCheckpoints,
            where: [
              { field: 'connectionId', operator: 'eq', value: checkpointInput.connectionId },
              { field: 'resource', operator: 'eq', value: checkpointInput.resource },
            ],
            create: {
              id: checkpointId(checkpointInput.connectionId, checkpointInput.resource),
              ...checkpointInput,
              updatedAt: now,
            },
            update: {
              provider: checkpointInput.provider,
              checkpoint: checkpointInput.checkpoint,
              updatedAt: now,
            },
            conflictTarget: ['connectionId', 'resource'],
          });
        }
        return job;
      });
    });
  }

  private async withSyncCheckpointLock<T>(key: string, work: () => Promise<T>): Promise<T> {
    const previous = this.syncCheckpointLocks.get(key) ?? Promise.resolve();
    let release!: () => void;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });
    const queued = previous.catch(() => {}).then(() => current);
    this.syncCheckpointLocks.set(key, queued);

    await previous.catch(() => {});
    try {
      return await work();
    } finally {
      release();
      if (this.syncCheckpointLocks.get(key) === queued) {
        this.syncCheckpointLocks.delete(key);
      }
    }
  }

  async completeSyncJob(
    id: string,
    updates: Omit<UpdateSyncJobProgressInput, 'status' | 'error'> = {},
    claimToken?: string
  ): Promise<PlugFnSyncJob> {
    const where: WhereClause[] = [
      { field: 'id', operator: 'eq', value: id },
      { field: 'status', operator: 'eq', value: 'running' },
    ];
    if (claimToken) {
      where.push({ field: 'claimToken', operator: 'eq', value: claimToken });
    }
    const updated = await this.adapter.database.updateMany({
      model: this.adapter.models.syncJobs,
      where,
      data: {
        ...updates,
        status: 'completed',
        claimToken: undefined,
        updatedAt: new Date(),
      },
    });

    const job = await this.adapter.getSyncJob(id);
    if (!job) {
      throw new Error(`Sync job ${id} not found after completion`);
    }
    if (updated === 0 && claimToken) {
      throw syncJobClaimLost(id);
    }
    if (updated === 0 && !['completed', 'cancelled', 'failed'].includes(job.status)) {
      throw new Error(`Sync job ${id} could not transition to completed from ${job.status}`);
    }
    return job;
  }

  async cancelSyncJob(id: string): Promise<PlugFnSyncJob> {
    await this.adapter.database.updateMany({
      model: this.adapter.models.syncJobs,
      where: [
        { field: 'id', operator: 'eq', value: id },
        { field: 'status', operator: 'in', value: ['queued', 'running'] },
      ],
      data: {
        status: 'cancelled',
        updatedAt: new Date(),
      },
    });

    const job = await this.adapter.getSyncJob(id);
    if (!job) {
      throw {
        code: 'NOT_FOUND',
        message: 'sync job not found',
        status: 404,
        retryable: false,
      };
    }
    if (job.status !== 'cancelled') {
      throw {
        code: 'SYNC_JOB_TERMINAL',
        message: `sync job cannot be cancelled from ${job.status}`,
        status: 409,
        retryable: false,
        details: { status: job.status },
      };
    }
    return job;
  }

  async failSyncJob(id: string, error: string, claimToken?: string): Promise<PlugFnSyncJob> {
    const where: WhereClause[] = [
      { field: 'id', operator: 'eq', value: id },
      { field: 'status', operator: 'eq', value: 'running' },
    ];
    if (claimToken) {
      where.push({ field: 'claimToken', operator: 'eq', value: claimToken });
    }
    const updated = await this.adapter.database.updateMany({
      model: this.adapter.models.syncJobs,
      where,
      data: {
        status: 'failed',
        claimToken: undefined,
        error,
        updatedAt: new Date(),
      },
    });

    const job = await this.adapter.getSyncJob(id);
    if (!job) {
      throw new Error(`Sync job ${id} not found after failure`);
    }
    if (updated === 0 && claimToken) {
      throw syncJobClaimLost(id);
    }
    if (updated === 0 && !['completed', 'cancelled', 'failed'].includes(job.status)) {
      throw new Error(`Sync job ${id} could not transition to failed from ${job.status}`);
    }
    return job;
  }

  upsertSyncCheckpoint(input: {
    provider: string;
    connectionId: string;
    resource: string;
    checkpoint: unknown;
  }): Promise<PlugFnSyncCheckpoint> {
    return this.adapter.upsertSyncCheckpoint({
      id: checkpointId(input.connectionId, input.resource),
      provider: input.provider,
      connectionId: input.connectionId,
      resource: input.resource,
      checkpoint: input.checkpoint,
      updatedAt: new Date(),
    });
  }

  getSyncCheckpoint(connectionId: string, resource: string): Promise<PlugFnSyncCheckpoint | null> {
    return this.adapter.getSyncCheckpoint(connectionId, resource);
  }

  createProviderEvent(
    input: Omit<PlugFnProviderEvent, 'id' | 'createdAt'>
  ): Promise<PlugFnProviderEvent> {
    return this.adapter.createProviderEvent({
      ...input,
      id: generateId('event'),
      createdAt: new Date(),
    });
  }

  listProviderEvents(
    filters: Record<string, unknown> = {},
    limit = 100
  ): Promise<PlugFnProviderEvent[]> {
    return this.adapter.listProviderEvents(filters, limit);
  }

  upsertSecretRef(
    input: Omit<PlugFnSecretRef, 'createdAt' | 'updatedAt'>
  ): Promise<PlugFnSecretRef> {
    const now = new Date();
    return this.adapter.upsertSecretRef({
      ...input,
      createdAt: now,
      updatedAt: now,
    });
  }

  listSecretRefs(filters: Record<string, unknown> = {}): Promise<PlugFnSecretRef[]> {
    return this.adapter.listSecretRefs(filters);
  }
}

function syncJobClaimLost(id: string): Error {
  const error = new Error(`sync job ${id} claim is no longer owned by this worker`);
  error.name = 'SyncJobClaimLostError';
  return error;
}

function assertMatchingWebhookReceipt(
  receipt: PlugFnWebhookReceipt,
  payloadHash: string
): PlugFnWebhookReceipt {
  if (receipt.payloadHash !== payloadHash) {
    throw new Error('webhook idempotency key was reused with a different payload');
  }
  return receipt;
}

export function ownerFields(owner: PlugFnConnectionOwner | undefined): {
  ownerKind?: PlugFnConnectionOwner['kind'];
  ownerId?: string;
  tenantId?: string;
  organizationId?: string;
  installedByUserId?: string;
  delegatedToUserId?: string;
  grants?: string[];
} {
  if (!owner) {
    return {};
  }

  if (owner.kind === 'user') {
    return {
      ownerKind: owner.kind,
      ownerId: owner.userId,
      tenantId: owner.tenantId,
    };
  }

  if (owner.kind === 'organization') {
    return {
      ownerKind: owner.kind,
      ownerId: owner.organizationId,
      tenantId: owner.tenantId,
      organizationId: owner.organizationId,
      installedByUserId: owner.installedByUserId,
    };
  }

  return {
    ownerKind: owner.kind,
    ownerId: owner.organizationId,
    tenantId: owner.tenantId,
    organizationId: owner.organizationId,
    installedByUserId: owner.installedByUserId,
    delegatedToUserId: owner.delegatedToUserId,
    grants: [...owner.grants],
  };
}

function generateId(prefix: string): string {
  const random = Math.random().toString(36).slice(2, 10);
  return `${prefix}_${Date.now().toString(36)}_${random}`;
}

function checkpointId(connectionId: string, resource: string): string {
  return `ckpt_${connectionId}_${resource}`.replace(/[^a-zA-Z0-9_:-]/g, '_');
}

import { describe, expect, it } from 'vitest';
import { WorkflowEngine } from '../src/core/workflow-engine.js';
import { ProviderRegistry } from '../src/core/provider-registry.js';
import { WebhookHandler } from '../src/webhooks/webhook-handler.js';
import type { WorkflowStorage } from '../src/storage/workflow-storage.js';
import { NoopLogger } from '../src/utils/logger.js';
import {
  WorkflowExecutionStatus,
  WorkflowStatus,
  type Workflow,
  type WorkflowExecution,
} from '../src/types/workflow.js';

describe('workflow durability semantics', () => {
  it('resolves serializable workflow references after a storage round trip and restart', async () => {
    const { storage, logger } = createHarness();
    const action = async () => ({ durable: true });
    const firstEngine = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger,
      { actions: { 'records.persist': action } }
    );
    const workflow = await firstEngine.create({
      userId: 'user-1',
      name: 'workflow-durable-references',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: { provider: 'github', event: 'issues.opened' },
        steps: [{ id: 'persist', type: 'action', action: 'records.persist' }],
      },
    });

    storage.roundTripWorkflow(workflow.id);
    const restarted = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger,
      { actions: { 'records.persist': action } }
    );

    await expect(restarted.execute(workflow.id, { id: 'event-1' })).resolves.toMatchObject({
      status: WorkflowExecutionStatus.Completed,
      output: { data: { durable: true } },
    });
  });

  it('fails clearly when a persisted workflow reference is not registered', async () => {
    const { engine } = createHarness();
    const workflow = await engine.create({
      userId: 'user-1',
      name: 'workflow-missing-reference',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: { provider: 'github', event: 'issues.opened' },
        steps: [{ id: 'persist', type: 'action', action: 'records.missing' }],
      },
    });

    await expect(engine.execute(workflow.id, { id: 'event-1' })).rejects.toMatchObject({
      code: 'WORKFLOW_DEFINITION_INVALID',
      details: { kind: 'action', reference: 'records.missing' },
    });
  });

  it('resumes a failed execution after restart and prevents duplicate completed execution', async () => {
    const { storage, logger } = createHarness();
    const firstEngine = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger
    );

    const sideEffects: string[] = [];
    let failStepTwoOnce = true;
    const workflow = await firstEngine.create({
      userId: 'user-1',
      name: 'workflow-durability-resume',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: {
          provider: 'github',
          event: 'issues.opened',
        },
        steps: [
          {
            id: 'step-1',
            type: 'action',
            action: async () => {
              sideEffects.push('step-1');
              return { first: true };
            },
          },
          {
            id: 'step-2',
            type: 'action',
            action: async () => {
              if (failStepTwoOnce) {
                failStepTwoOnce = false;
                throw new Error('step two failed');
              }
              sideEffects.push('step-2');
              return { second: true };
            },
          },
        ],
      },
    });

    await expect(
      firstEngine.execute(workflow.id, {
        idempotencyKey: 'evt_01',
      })
    ).rejects.toThrow('step two failed');

    const resumedEngine = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger
    );
    const resumed = await resumedEngine.execute(workflow.id, {
      idempotencyKey: 'evt_01',
    });
    const duplicate = await resumedEngine.execute(workflow.id, {
      idempotencyKey: 'evt_01',
    });

    expect(resumed.status).toBe(WorkflowExecutionStatus.Completed);
    expect(duplicate.id).toBe(resumed.id);
    expect(duplicate.status).toBe(WorkflowExecutionStatus.Completed);
    expect(resumed.output.__workflow).toMatchObject({
      idempotencyKey: 'evt_01',
      completedStepIds: ['step-1', 'step-2'],
      resumed: true,
      retriable: false,
    });
    expect(sideEffects).toEqual(['step-1', 'step-2']);
  });

  it('fails closed on delay steps with WORKFLOW_DURABILITY_UNSUPPORTED', async () => {
    const { engine, storage } = createHarness();

    const workflow = await engine.create({
      userId: 'user-1',
      name: 'workflow-delay-unsupported',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: {
          provider: 'github',
          event: 'issues.opened',
        },
        steps: [
          {
            id: 'delay-1',
            type: 'delay',
            duration: 5,
            unit: 'seconds',
          },
        ],
      },
    });

    await expect(
      engine.execute(workflow.id, {
        idempotencyKey: 'evt_delay',
      })
    ).rejects.toMatchObject({
      code: 'WORKFLOW_DURABILITY_UNSUPPORTED',
    });

    const execution = await storage.findExecutionByIdempotencyKey(workflow.id, 'evt_delay');
    expect(execution?.status).toBe(WorkflowExecutionStatus.Failed);
    expect(execution?.error).toBe(
      'WORKFLOW_DURABILITY_UNSUPPORTED:delay step delay-1 requires a durable scheduler'
    );
    expect(execution?.output.__workflow).toMatchObject({
      idempotencyKey: 'evt_delay',
      errorCode: 'WORKFLOW_DURABILITY_UNSUPPORTED',
      retriable: false,
      failedStepId: 'delay-1',
    });
  });

  it('rejects duplicate step IDs across top-level and nested branches', async () => {
    const { engine } = createHarness();

    await expect(
      engine.create({
        userId: 'user-1',
        name: 'workflow-duplicate-step-ids',
        status: WorkflowStatus.Enabled,
        definition: {
          trigger: { provider: 'github', event: 'issues.opened' },
          steps: [
            {
              id: 'duplicate',
              type: 'action',
              action: async () => ({}),
            },
            {
              id: 'branch',
              type: 'branch',
              condition: () => true,
              then: [
                {
                  id: 'duplicate',
                  type: 'action',
                  action: async () => ({}),
                },
              ],
            },
          ],
        },
      })
    ).rejects.toMatchObject({
      code: 'WORKFLOW_DEFINITION_INVALID',
      details: { duplicateStepIds: ['duplicate'] },
    });
  });
});

function createHarness() {
  const storage = new InMemoryWorkflowStorage();
  const logger = new NoopLogger();
  const providerRegistry = new ProviderRegistry(logger);
  const webhookHandler = new WebhookHandler(providerRegistry, logger);
  const engine = new WorkflowEngine(storage, webhookHandler, logger);

  return {
    storage,
    logger,
    webhookHandler,
    engine,
  };
}

class InMemoryWorkflowStorage implements WorkflowStorage {
  private readonly workflows = new Map<string, Workflow>();
  private readonly executions = new Map<string, WorkflowExecution>();
  private workflowCounter = 0;
  private executionCounter = 0;

  roundTripWorkflow(id: string): void {
    const workflow = this.workflows.get(id);
    if (!workflow) {
      throw new Error(`Workflow ${id} not found`);
    }
    const serialized = JSON.parse(JSON.stringify(workflow)) as Workflow;
    serialized.createdAt = new Date(String(serialized.createdAt));
    serialized.updatedAt = new Date(String(serialized.updatedAt));
    this.workflows.set(id, serialized);
  }

  async create(workflow: Omit<Workflow, 'id' | 'createdAt' | 'updatedAt'>): Promise<Workflow> {
    const created: Workflow = {
      ...workflow,
      id: `wf_${++this.workflowCounter}`,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.workflows.set(created.id, created);
    return created;
  }

  async get(id: string): Promise<Workflow | null> {
    return this.workflows.get(id) ?? null;
  }

  async list(userId?: string, status?: WorkflowStatus): Promise<Workflow[]> {
    return [...this.workflows.values()].filter((workflow) => {
      if (userId && workflow.userId !== userId) {
        return false;
      }
      if (status && workflow.status !== status) {
        return false;
      }
      return true;
    });
  }

  async update(id: string, updates: Partial<Workflow>): Promise<Workflow> {
    const current = this.workflows.get(id);
    if (!current) {
      throw new Error(`Workflow ${id} not found`);
    }

    const updated: Workflow = {
      ...current,
      ...updates,
      id: current.id,
      updatedAt: new Date(),
    };
    this.workflows.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<void> {
    this.workflows.delete(id);
  }

  async createExecution(
    execution: Omit<WorkflowExecution, 'id' | 'startedAt'>
  ): Promise<WorkflowExecution> {
    const created: WorkflowExecution = {
      ...execution,
      id: `wfx_${++this.executionCounter}`,
      startedAt: new Date(),
    };
    this.executions.set(created.id, created);
    return created;
  }

  async getExecution(id: string): Promise<WorkflowExecution | null> {
    return this.executions.get(id) ?? null;
  }

  async updateExecution(id: string, updates: Partial<WorkflowExecution>): Promise<void> {
    const current = this.executions.get(id);
    if (!current) {
      throw new Error(`Workflow execution ${id} not found`);
    }

    this.executions.set(id, {
      ...current,
      ...updates,
      id: current.id,
      workflowId: current.workflowId,
      startedAt: current.startedAt,
    });
  }

  async listExecutions(workflowId: string, limit = 50): Promise<WorkflowExecution[]> {
    return [...this.executions.values()]
      .filter((execution) => execution.workflowId === workflowId)
      .sort((left, right) => right.startedAt.getTime() - left.startedAt.getTime())
      .slice(0, limit);
  }

  async findExecutionByIdempotencyKey(
    workflowId: string,
    idempotencyKey: string
  ): Promise<WorkflowExecution | null> {
    const executions = await this.listExecutions(workflowId, 1000);

    for (const execution of executions) {
      const input = execution.input as Record<string, unknown> | undefined;
      const workflowInput = input?.__workflow as Record<string, unknown> | undefined;
      const inputKey =
        typeof workflowInput?.idempotencyKey === 'string'
          ? workflowInput.idempotencyKey
          : typeof input?.idempotencyKey === 'string'
            ? input.idempotencyKey
            : undefined;
      if (inputKey === idempotencyKey) {
        return execution;
      }

      const output = execution.output as Record<string, unknown> | undefined;
      const workflowOutput = output?.__workflow as Record<string, unknown> | undefined;
      if (workflowOutput?.idempotencyKey === idempotencyKey) {
        return execution;
      }
    }

    return null;
  }
}

import type { Workflow, WorkflowContext, WorkflowRuntimeRegistry } from '../types/workflow.js';
import type { Provider } from '../types/provider.js';

/**
 * Workflow test options
 */
export interface WorkflowTestOptions {
  trigger: {
    provider: string;
    event: string;
    payload: any;
  };
  mocks?: Record<string, Provider>;
  timeout?: number;
  runtime?: WorkflowRuntimeRegistry;
}

/**
 * Workflow test result
 */
export interface WorkflowTestResult {
  success: boolean;
  duration: number;
  output?: any;
  error?: Error;
  steps: Array<{
    id: string;
    success: boolean;
    duration: number;
    output?: any;
    error?: Error;
  }>;
}

/**
 * Test a workflow
 */
export async function testWorkflow(
  workflow: Workflow,
  options: WorkflowTestOptions
): Promise<WorkflowTestResult> {
  const startTime = Date.now();
  const steps: WorkflowTestResult['steps'] = [];

  try {
    // Build test context
    const context: WorkflowContext = {
      workflowId: workflow.id,
      executionId: `test-exec-${Date.now()}`,
      userId: workflow.userId,
      trigger: options.trigger,
      data: {},
    };

    // Check filter
    if (workflow.definition.trigger.filter) {
      const filter = workflow.definition.trigger.filter;
      const condition =
        typeof filter === 'function' ? filter : options.runtime?.conditions?.[filter];
      if (!condition) {
        throw new Error(`Workflow condition reference ${String(filter)} is not registered`);
      }
      const shouldRun = condition(context);
      if (!shouldRun) {
        return {
          success: true,
          duration: Date.now() - startTime,
          output: { skipped: true },
          steps: [],
        };
      }
    }

    // Execute steps
    for (const step of workflow.definition.steps) {
      const stepStartTime = Date.now();

      try {
        await executeTestStep(step, context, options.runtime);

        steps.push({
          id: step.id,
          success: true,
          duration: Date.now() - stepStartTime,
          output: context.data,
        });
      } catch (error) {
        steps.push({
          id: step.id,
          success: false,
          duration: Date.now() - stepStartTime,
          error: error as Error,
        });
        throw error;
      }
    }

    return {
      success: true,
      duration: Date.now() - startTime,
      output: context.data,
      steps,
    };
  } catch (error) {
    return {
      success: false,
      duration: Date.now() - startTime,
      error: error as Error,
      steps,
    };
  }
}

/**
 * Execute a workflow step in test mode
 */
async function executeTestStep(
  step: any,
  context: WorkflowContext,
  runtime?: WorkflowRuntimeRegistry
): Promise<void> {
  switch (step.type) {
    case 'action': {
      const action =
        typeof step.action === 'function' ? step.action : runtime?.actions?.[step.action];
      if (!action) {
        throw new Error(`Workflow action reference ${String(step.action)} is not registered`);
      }
      const result = await action(context);
      Object.assign(context.data, result);
      break;
    }

    case 'filter': {
      const condition =
        typeof step.condition === 'function'
          ? step.condition
          : runtime?.conditions?.[step.condition];
      if (!condition) {
        throw new Error(`Workflow condition reference ${String(step.condition)} is not registered`);
      }
      const shouldContinue = condition(context);
      if (!shouldContinue) {
        throw new Error('Filter condition not met');
      }
      break;
    }

    case 'branch': {
      const condition =
        typeof step.condition === 'function'
          ? step.condition
          : runtime?.conditions?.[step.condition];
      if (!condition) {
        throw new Error(`Workflow condition reference ${String(step.condition)} is not registered`);
      }
      const branch = condition(context) ? step.then : step.else;
      if (branch) {
        for (const branchStep of branch) {
          await executeTestStep(branchStep, context, runtime);
        }
      }
      break;
    }

    case 'parallel': {
      const actions = step.actions.map((action: any) => {
        const resolved = typeof action === 'function' ? action : runtime?.actions?.[action];
        if (!resolved) {
          throw new Error(`Workflow action reference ${String(action)} is not registered`);
        }
        return resolved;
      });
      await Promise.all(actions.map((action: any) => action(context)));
      break;
    }

    case 'delay':
      // In test mode, skip actual delays
      break;
  }
}

/**
 * Assert workflow result
 */
export function assertWorkflowSuccess(result: WorkflowTestResult): void {
  if (!result.success) {
    throw new Error(`Workflow test failed: ${result.error?.message || 'Unknown error'}`);
  }
}

/**
 * Assert workflow error
 */
export function assertWorkflowError(result: WorkflowTestResult, expectedMessage?: string): void {
  if (result.success) {
    throw new Error('Expected workflow to fail, but it succeeded');
  }

  if (expectedMessage && result.error?.message !== expectedMessage) {
    throw new Error(`Expected error message "${expectedMessage}", got "${result.error?.message}"`);
  }
}

