/**
 * Main PlugFn SDK interface
 */
export interface PlugFn {
  /** Resolves only after persisted workflow triggers have been rehydrated. */
  ready: Promise<void>;

  config: {
    auth: {
      authenticate(request: Request): Promise<PlugFnPrincipal | null>;
    };
    baseUrl: string;
    integrations: Record<string, PlugFnConfig['integrations'][string]>;
    authorization?: PlugFnConfig['authorization'];
    webhooks?: PlugFnConfig['webhooks'];
  };

  // Connection management
  connections: {
    start(options: StartConnectionOptions): Promise<{ authUrl: string }>;
    getAuthUrl(options: GetAuthUrlOptions): Promise<string>;
    handleCallback(options: HandleCallbackOptions): Promise<HandleCallbackResult>;
    list(options: ListConnectionsOptions): Promise<Connection[]>;
    get(id: string): Promise<Connection>;
    disconnect(options: DisconnectOptions): Promise<DisconnectResult>;
    refresh(id: string): Promise<Connection>;
  };

  runtime: {
    installations: {
      create(input: CreateProviderInstallationInput): Promise<PlugFnProviderInstallation>;
      list(filters?: Record<string, unknown>): Promise<PlugFnProviderInstallation[]>;
      update(
        id: string,
        updates: Partial<PlugFnProviderInstallation>
      ): Promise<PlugFnProviderInstallation>;
    };
    grants: {
      create(input: CreateConnectionGrantInput): Promise<PlugFnConnectionGrant>;
      list(connectionId: string): Promise<PlugFnConnectionGrant[]>;
      delete(id: string): Promise<void>;
    };
    webhooks: {
      createReceipt(input: CreateWebhookReceiptInput): Promise<PlugFnWebhookReceipt>;
      getReceipt(id: string): Promise<PlugFnWebhookReceipt | null>;
      findReceiptByIdempotencyKey(
        provider: string,
        idempotencyKey: string
      ): Promise<PlugFnWebhookReceipt | null>;
      updateReceipt(
        id: string,
        updates: Partial<PlugFnWebhookReceipt>
      ): Promise<PlugFnWebhookReceipt>;
      createDelivery(input: CreateWebhookDeliveryInput): Promise<PlugFnWebhookDelivery>;
      updateDelivery(
        id: string,
        updates: Partial<PlugFnWebhookDelivery>
      ): Promise<PlugFnWebhookDelivery>;
      listDeliveries(receiptId: string): Promise<PlugFnWebhookDelivery[]>;
      processDueDeliveries(
        handler: PlugFnWebhookDeliveryHandler,
        options?: PlugFnWebhookDeliveryWorkerOptions
      ): Promise<PlugFnWebhookDeliveryWorkerResult>;
    };
    sync: {
      createJob(input: CreateSyncJobInput): Promise<PlugFnSyncJob>;
      getJob(id: string): Promise<PlugFnSyncJob | null>;
      listJobs(filters?: Record<string, unknown>, limit?: number): Promise<PlugFnSyncJob[]>;
      updateJob(id: string, updates: UpdateSyncJobProgressInput): Promise<PlugFnSyncJob>;
      cancelJob(id: string): Promise<PlugFnSyncJob>;
      completeJob(
        id: string,
        updates?: Omit<UpdateSyncJobProgressInput, 'status' | 'error'>
      ): Promise<PlugFnSyncJob>;
      failJob(id: string, error: string): Promise<PlugFnSyncJob>;
      processQueued(options?: PlugFnSyncWorkerOptions): Promise<PlugFnSyncWorkerResult>;
      upsertCheckpoint(input: {
        provider: string;
        connectionId: string;
        resource: string;
        checkpoint: unknown;
      }): Promise<PlugFnSyncCheckpoint>;
      getCheckpoint(connectionId: string, resource: string): Promise<PlugFnSyncCheckpoint | null>;
    };
    events: {
      create(input: Omit<PlugFnProviderEvent, 'id' | 'createdAt'>): Promise<PlugFnProviderEvent>;
      list(filters?: Record<string, unknown>, limit?: number): Promise<PlugFnProviderEvent[]>;
    };
    secrets: {
      upsert(input: Omit<PlugFnSecretRef, 'createdAt' | 'updatedAt'>): Promise<PlugFnSecretRef>;
      list(filters?: Record<string, unknown>): Promise<PlugFnSecretRef[]>;
    };
    sinks: {
      register<Raw = unknown, RecordValue = unknown>(
        sink: PlugFnPersistenceSink<Raw, RecordValue>
      ): void;
      list(): PlugFnPersistenceSink[];
      get(id: string): PlugFnPersistenceSink | undefined;
      persist<Raw = unknown>(input: {
        sinkId?: string;
        provider: string;
        resource: string;
        raw: Raw;
        context?: Partial<PlugFnSinkContext>;
      }): Promise<{ sinkId: string; idempotencyKey: string }>;
    };
  };

  // Workflow management
  workflows: {
    list(options?: ListWorkflowsOptions): Promise<Workflow[]>;
    get(id: string): Promise<Workflow | null>;
    rehydrateTriggers(): Promise<{ registered: number; failed: number }>;
    enable(id: string): Promise<void>;
    disable(id: string): Promise<void>;
    delete(id: string): Promise<void>;
    getStats(id: string): Promise<WorkflowStats>;
  };

  // Webhook management
  webhooks: {
    on(provider: string, event: string, handler: TriggerHandler): void;
    off(provider: string, event: string, handler: TriggerHandler): void;
    handle(
      provider: string,
      event: string,
      payload: any,
      headers: Record<string, string>,
      secret?: string,
      options?: {
        rawBody?: Uint8Array;
      }
    ): Promise<any>;
    verify(
      provider: string,
      event: string,
      payload: any,
      headers: Record<string, string>,
      secret?: string,
      options?: {
        rawBody?: Uint8Array;
      }
    ): Promise<any>;
  };

  // Provider management
  providers: {
    list(): Provider[];
    get(name: string): Provider | undefined;
    register(provider: Provider): void;
  };

  use<P extends Provider>(provider: P): PlugFn;

  action<T = unknown>(provider: string, action: string, options: ActionOptions): Promise<T>;

  sync: {
    backfill(options: PlugFnSyncRunOptions): Promise<PlugFnSyncJob>;
    incremental(options: PlugFnSyncRunOptions): Promise<PlugFnSyncJob>;
    enqueue(options: PlugFnSyncQueueOptions): Promise<PlugFnSyncJob>;
    processQueued(options?: PlugFnSyncWorkerOptions): Promise<PlugFnSyncWorkerResult>;
  };

  // Action execution
  batch(actions: BatchAction[]): Promise<BatchResult[]>;
  getMetrics(options: MetricsOptions): Promise<any>;
  on(event: string, handler: (event: any) => void): void;
  off(event: string, handler: (event: any) => void): void;

  // Dynamic provider access
  [provider: string]: any;
}

export interface PlugFnSyncRunOptions {
  provider: string;
  connectionId: string;
  resource: string;
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages?: number;
  metadata?: Record<string, unknown>;
  actor?: PlugFnActor;
}

export interface PlugFnSyncQueueOptions extends PlugFnSyncRunOptions {
  mode: PlugFnSyncJob['mode'];
}

export interface PlugFnSyncWorkerOptions {
  limit?: number;
  leaseMs?: number;
}

export interface PlugFnSyncWorkerResult {
  processed: number;
  completed: number;
  cancelled: number;
  failed: number;
  jobs: PlugFnSyncJob[];
}

export interface PlugFnWebhookDeliveryWorkerOptions {
  limit?: number;
  maxAttempts?: number;
  baseDelayMs?: number;
  leaseMs?: number;
}

export interface PlugFnWebhookDeliveryWorkerResult {
  processed: number;
  succeeded: number;
  failed: number;
  deadLettered: number;
  deliveries: PlugFnWebhookDelivery[];
}

export type PlugFnWebhookDeliveryHandler = (input: {
  delivery: PlugFnWebhookDelivery;
  receipt: PlugFnWebhookReceipt;
  provider: string;
  event: string;
  headers: Record<string, string>;
  rawBody: Uint8Array;
}) => Promise<void> | void;

/**
 * Create PlugFn instance
 */
export function plugFn(config: PlugFnConfig): PlugFn {
  // Initialize logger
  const logger: Logger = config.logger || new ConsoleLogger('[PlugFn]');
  validateEncryptionKey(config.encryptionKey);
  const normalizedAuthProvider = normalizeAuthProvider(config.auth);
  const database = wrapWithSchema(config.database, getSchema());

  // Initialize storage
  const connectionStorage = new AdapterConnectionStorage(database);
  // const _webhookStorage = new AdapterWebhookStorage(database);
  const runtimeStorage = new AdapterRuntimeStorage(database);
  const workflowStorage = new AdapterWorkflowStorage(database);

  // Initialize provider registry
  const providerRegistry = new ProviderRegistry(logger);

  // Convert integration configs to Map
  const integrationConfigs = new Map(Object.entries(config.integrations));

  // Mark configured providers
  for (const providerName of integrationConfigs.keys()) {
    providerRegistry.markConfigured(providerName);
  }

  const oauthFlowDependencies = createConnectionManagerOAuthDependencies({
    database,
    providers: providerRegistry,
    integrationConfigs,
    baseUrl: config.baseUrl,
    encryptionKey: config.encryptionKey,
    logger,
  });

  // Initialize managers
  const connectionManager = new ConnectionManager(
    connectionStorage,
    providerRegistry,
    integrationConfigs,
    config.baseUrl,
    config.encryptionKey,
    logger,
    oauthFlowDependencies,
    config.authorization?.authorizeConnection
  );

  const actionExecutor = new ActionExecutor(connectionManager, providerRegistry, logger, {
    enableRetry: config.retry?.enabled !== false,
    enableRateLimit: config.rateLimit?.enabled !== false,
    enableCache: config.cache?.enabled !== false,
    enableLogging: true,
    enableMetrics: true,
    database,
    cacheStore: config.cache?.store ?? config.cacheStore,
    cacheTtl: config.cache?.ttl ?? config.cache?.defaultTTL,
    cacheKeyPrefix: config.cache?.keyPrefix,
    respectProviderLimits: config.rateLimit?.respectProviderLimits,
    globalRateLimit: config.rateLimit?.global,
  });

  const webhookHandler = new WebhookHandler(providerRegistry, logger, {
    verifySignatures: config.webhooks?.verifySignatures,
  });

  const workflowEngine = new WorkflowEngine(
    workflowStorage,
    webhookHandler,
    logger,
    config.workflows?.runtime
  );
  let readyAttempt: Promise<void> | undefined;
  const ensureReady = (): Promise<void> => {
    if (!readyAttempt) {
      const attempt = workflowEngine.rehydrateEnabledTriggers().then((result) => {
        if (result.failed > 0) {
          throw new Error(`failed to rehydrate ${result.failed} workflow trigger(s)`);
        }
      });
      readyAttempt = attempt;
      void attempt.catch((error) => {
        if (readyAttempt === attempt) {
          readyAttempt = undefined;
        }
        logger.error('PlugFn workflow trigger rehydration failed', { error });
      });
    }
    return readyAttempt!;
  };
  void ensureReady();

  // Event handlers
  const eventHandlers = new Map<string, Set<(event: any) => void>>();
  const persistenceSinks = new Map<string, PlugFnPersistenceSink>();
  let proxyApi!: PlugFn;

  // Create the main API
  const api: PlugFn = {
    get ready() {
      return ensureReady();
    },
    config: {
      auth: normalizedAuthProvider,
      baseUrl: config.baseUrl,
      integrations: config.integrations,
      authorization: config.authorization,
      webhooks: config.webhooks,
    },

    // Connection management
    connections: {
      start: async (options) => ({ authUrl: await connectionManager.getAuthUrl(options) }),
      getAuthUrl: (options) => connectionManager.getAuthUrl(options),
      handleCallback: (options) => connectionManager.handleCallback(options),
      list: (options) => connectionManager.list(options),
      get: (id) => connectionManager.get(id),
      disconnect: (options) => connectionManager.disconnect(options),
      refresh: (id) => connectionManager.refresh(id),
    },

    runtime: {
      installations: {
        create: (input) => runtimeStorage.createProviderInstallation(input),
        list: (filters) => runtimeStorage.listProviderInstallations(filters),
        update: (id, updates) => runtimeStorage.updateProviderInstallation(id, updates),
      },
      grants: {
        create: (input) => runtimeStorage.createConnectionGrant(input),
        list: (connectionId) => runtimeStorage.listConnectionGrants(connectionId),
        delete: (id) => runtimeStorage.deleteConnectionGrant(id),
      },
      webhooks: {
        createReceipt: (input) => runtimeStorage.createWebhookReceipt(input),
        getReceipt: (id) => runtimeStorage.getWebhookReceipt(id),
        findReceiptByIdempotencyKey: (provider, idempotencyKey) =>
          runtimeStorage.findWebhookReceiptByIdempotencyKey(provider, idempotencyKey),
        updateReceipt: (id, updates) => runtimeStorage.updateWebhookReceipt(id, updates),
        createDelivery: (input) => runtimeStorage.createWebhookDelivery(input),
        updateDelivery: (id, updates) => runtimeStorage.updateWebhookDelivery(id, updates),
        listDeliveries: (receiptId) => runtimeStorage.listWebhookDeliveries(receiptId),
        processDueDeliveries: (handler, options) => processDueWebhookDeliveries(handler, options),
      },
      sync: {
        createJob: (input) => runtimeStorage.createSyncJob(input),
        getJob: (id) => runtimeStorage.getSyncJob(id),
        listJobs: (filters, limit) => runtimeStorage.listSyncJobs(filters, limit),
        updateJob: (id, updates) => runtimeStorage.updateSyncJob(id, updates),
        cancelJob: (id) => runtimeStorage.cancelSyncJob(id),
        completeJob: (id, updates) => runtimeStorage.completeSyncJob(id, updates),
        failJob: (id, error) => runtimeStorage.failSyncJob(id, error),
        processQueued: (options) => processQueuedSyncJobs(options),
        upsertCheckpoint: (input) => runtimeStorage.upsertSyncCheckpoint(input),
        getCheckpoint: (connectionId, resource) =>
          runtimeStorage.getSyncCheckpoint(connectionId, resource),
      },
      events: {
        create: (input) => runtimeStorage.createProviderEvent(input),
        list: (filters, limit) => runtimeStorage.listProviderEvents(filters, limit),
      },
      secrets: {
        upsert: (input) => runtimeStorage.upsertSecretRef(input),
        list: (filters) => runtimeStorage.listSecretRefs(filters),
      },
      sinks: {
        register: (sink) => {
          persistenceSinks.set(sink.id, sink as PlugFnPersistenceSink);
        },
        list: () => [...persistenceSinks.values()],
        get: (id) => persistenceSinks.get(id),
        persist: async (input) => {
          const sink = resolvePersistenceSink(persistenceSinks, input);
          const context: PlugFnSinkContext = {
            provider: input.provider,
            resource: input.resource,
            ...input.context,
          };
          const { idempotencyKey } = await persistSinkItem(sink, input.raw, context);
          return {
            sinkId: sink.id,
            idempotencyKey,
          };
        },
      },
    },

    // Workflow management
    workflows: {
      list: (options) => workflowEngine.list(options),
      get: (id) => workflowEngine.get(id),
      rehydrateTriggers: () => workflowEngine.rehydrateEnabledTriggers(),
      enable: (id) => workflowEngine.enable(id),
      disable: (id) => workflowEngine.disable(id),
      delete: (id) => workflowEngine.delete(id),
      getStats: (id) => workflowEngine.getStats(id),
    },

    // Webhook management
    webhooks: {
      on: (provider, event, handler) => webhookHandler.on(provider, event, handler),
      off: (provider, event, handler) => webhookHandler.off(provider, event, handler),
      handle: (provider, event, payload, headers, secret, options) =>
        webhookHandler.handleWebhook(provider, event, payload, headers, secret, options),
      verify: (provider, event, payload, headers, secret, options) =>
        webhookHandler.verifyWebhook(provider, event, payload, headers, secret, options),
    },

    // Provider management
    providers: {
      list: () => providerRegistry.list(),
      get: (name) => providerRegistry.get(name),
      register: (provider) => {
        providerRegistry.register(provider);
      },
    },

    use: (provider) => {
      providerRegistry.register(provider);
      return proxyApi;
    },

    action: async (provider, action, options) => {
      const result = await actionExecutor.execute(provider, action, options);
      if (!result.success) {
        throw result.error;
      }
      return result.data as any;
    },

    sync: {
      backfill: (options) => runSyncJob('full', options),
      incremental: (options) => runSyncJob('incremental', options),
      enqueue: (options) => enqueueSyncJob(options.mode, options),
      processQueued: (options) => processQueuedSyncJobs(options),
    },

    // Batch execution
    batch: (actions) => actionExecutor.batch(actions),

    // Metrics
    getMetrics: async (options) => actionExecutor.getMetrics(options),

    // Event handling
    on: (event: string, handler: (event: any) => void) => {
      if (!eventHandlers.has(event)) {
        eventHandlers.set(event, new Set());
      }
      eventHandlers.get(event)!.add(handler);
    },

    off: (event: string, handler: (event: any) => void) => {
      const handlers = eventHandlers.get(event);
      if (handlers) {
        handlers.delete(handler);
      }
    },
  };

  async function runSyncJob(
    mode: PlugFnSyncJob['mode'],
    options: PlugFnSyncRunOptions
  ): Promise<PlugFnSyncJob> {
    const job = await enqueueSyncJob(mode, options);
    return executeQueuedSyncJob(job);
  }

  async function assertSyncConnectionAuthorized(
    connection: Connection,
    actor: PlugFnActor
  ): Promise<void> {
    if (await connectionManager.canActorAccessConnection(connection, actor, 'sync')) {
      return;
    }

    const tenantMismatch =
      !config.authorization?.authorizeConnection &&
      !tenantMatches(connection.tenantId, actor.tenantId);
    throw new PlugFnRuntimeError(
      'TENANT_ACCESS_DENIED',
      tenantMismatch ? 'connection tenant mismatch' : 'connection owner mismatch',
      403
    );
  }

  async function enqueueSyncJob(
    mode: PlugFnSyncJob['mode'],
    options: PlugFnSyncRunOptions
  ): Promise<PlugFnSyncJob> {
    const connection = await connectionManager.get(options.connectionId);
    if (connection.provider !== options.provider) {
      throw new PlugFnRuntimeError('VALIDATION_ERROR', 'connection provider mismatch', 400);
    }

    if (options.actor) {
      await assertSyncConnectionAuthorized(connection, options.actor);
    }

    const persistedCheckpoint =
      mode === 'incremental' && options.checkpoint === undefined
        ? await runtimeStorage.getSyncCheckpoint(options.connectionId, options.resource)
        : null;

    return runtimeStorage.createSyncJob({
      provider: options.provider,
      connectionId: options.connectionId,
      resource: options.resource,
      mode,
      owner: connectionToOwner(connection),
      cursor: options.cursor,
      checkpoint:
        options.checkpoint !== undefined ? options.checkpoint : persistedCheckpoint?.checkpoint,
      metadata: {
        ...(options.metadata ?? {}),
        plugfnSync: {
          sinkId: options.sinkId,
          maxPages: options.maxPages,
          actor: options.actor,
        },
      },
    });
  }

  async function processQueuedSyncJobs(
    options: PlugFnSyncWorkerOptions = {}
  ): Promise<PlugFnSyncWorkerResult> {
    const leaseMs = Math.max(30, options.leaseMs ?? 5 * 60 * 1000);
    const queued = await runtimeStorage.claimQueuedSyncJobs(options.limit ?? 25, leaseMs);
    const jobs: PlugFnSyncJob[] = [];
    let completed = 0;
    let cancelled = 0;
    let failed = 0;

    for (const job of queued) {
      try {
        const processedJob = await executeSyncJob(job, { claimed: true, leaseMs });
        if (processedJob.status === 'completed') {
          completed += 1;
        } else if (processedJob.status === 'cancelled') {
          cancelled += 1;
        } else if (processedJob.status === 'failed') {
          failed += 1;
        } else {
          throw new Error(`Sync job ${processedJob.id} ended in ${processedJob.status}`);
        }
        jobs.push(processedJob);
      } catch {
        const updated = await runtimeStorage.getSyncJob(job.id);
        if (updated) {
          jobs.push(updated);
        }
        failed += 1;
      }
    }

    return {
      processed: queued.length,
      completed,
      cancelled,
      failed,
      jobs,
    };
  }

  async function executeQueuedSyncJob(job: PlugFnSyncJob): Promise<PlugFnSyncJob> {
    return executeSyncJob(job, { claimed: false, leaseMs: 5 * 60 * 1000 });
  }

  async function executeSyncJob(
    job: PlugFnSyncJob,
    options: { claimed: boolean; leaseMs: number }
  ): Promise<PlugFnSyncJob> {
    let claimToken = job.claimToken;
    if (!options.claimed) {
      claimToken = `direct:${job.id}:${Date.now()}`;
      job = await runtimeStorage.updateSyncJob(job.id, {
        status: 'running',
        claimToken,
      });
    }
    if (!claimToken) {
      throw syncJobClaimLostError(job.id);
    }

    let heartbeatError: unknown;
    let heartbeatInFlight = false;
    const renewClaim = async (): Promise<void> => {
      if (heartbeatInFlight || heartbeatError) {
        return;
      }
      heartbeatInFlight = true;
      try {
        const renewed = await runtimeStorage.updateClaimedSyncJob(job.id, claimToken!, {});
        if (!renewed) {
          heartbeatError = syncJobClaimLostError(job.id);
        }
      } catch (error) {
        heartbeatError = error;
      } finally {
        heartbeatInFlight = false;
      }
    };
    const heartbeatIntervalMs = Math.max(10, Math.floor(options.leaseMs / 3));
    const heartbeatTimer = setInterval(() => {
      void renewClaim();
    }, heartbeatIntervalMs);
    heartbeatTimer.unref?.();

    try {
      const connection = await connectionManager.get(job.connectionId);
      if (connection.provider !== job.provider) {
        throw new PlugFnRuntimeError('VALIDATION_ERROR', 'connection provider mismatch', 400);
      }

      const workerOptions = readSyncJobWorkerMetadata(job);
      if (workerOptions.actor) {
        await assertSyncConnectionAuthorized(connection, workerOptions.actor);
      }

      const result = await executeSyncResource({
        providerRegistry,
        actionExecutor,
        persistenceSinks,
        provider: job.provider,
        connectionId: job.connectionId,
        resource: job.resource,
        mode: job.mode,
        userId: connection.userId,
        tenantId: connection.tenantId ?? workerOptions.actor?.tenantId,
        sinkId: workerOptions.sinkId,
        cursor: job.cursor,
        checkpoint: job.checkpoint,
        maxPages: workerOptions.maxPages ?? 50,
        shouldContinue: async () => {
          if (heartbeatError) {
            throw heartbeatError;
          }
          const currentJob = await runtimeStorage.getSyncJob(job.id);
          if (currentJob?.status === 'cancelled') {
            return false;
          }
          if (currentJob?.status !== 'running' || currentJob.claimToken !== claimToken) {
            throw syncJobClaimLostError(job.id);
          }
          return true;
        },
        onPage: async (progress) => {
          const updated = await runtimeStorage.checkpointClaimedSyncJob(
            job.id,
            claimToken!,
            {
              cursor: progress.cursor,
              checkpoint: progress.checkpoint,
              fetchedCount: progress.fetchedCount,
              persistedCount: progress.persistedCount,
              skippedCount: progress.skippedCount,
            },
            progress.checkpoint === undefined
              ? undefined
              : {
                  provider: job.provider,
                  connectionId: job.connectionId,
                  resource: job.resource,
                  checkpoint: progress.checkpoint,
                }
          );
          if (!updated) {
            throw syncJobClaimLostError(job.id);
          }
        },
      });

      clearInterval(heartbeatTimer);
      if (heartbeatError) {
        throw heartbeatError;
      }
      const completedJob = await runtimeStorage.completeSyncJob(
        job.id,
        {
          cursor: result.cursor,
          checkpoint: result.checkpoint,
          fetchedCount: result.fetchedCount,
          persistedCount: result.persistedCount,
          skippedCount: result.skippedCount,
        },
        claimToken
      );

      if (result.checkpoint !== undefined) {
        await runtimeStorage.upsertSyncCheckpoint({
          provider: job.provider,
          connectionId: job.connectionId,
          resource: job.resource,
          checkpoint: result.checkpoint,
        });
      }

      return completedJob;
    } catch (error) {
      if (isSyncCancelledError(error)) {
        const cancelledJob = await runtimeStorage.updateClaimedSyncJob(job.id, claimToken, {
          status: 'cancelled',
          error: undefined,
        });
        if (!cancelledJob) {
          const currentJob = await runtimeStorage.getSyncJob(job.id);
          if (currentJob?.status === 'cancelled') {
            return currentJob;
          }
          throw syncJobClaimLostError(job.id);
        }
        return cancelledJob;
      }
      const currentJob = await runtimeStorage.getSyncJob(job.id);
      if (currentJob?.status === 'cancelled') {
        return currentJob;
      }
      if (currentJob?.status !== 'running' || currentJob.claimToken !== claimToken) {
        throw syncJobClaimLostError(job.id);
      }
      const failedJob = await runtimeStorage.failSyncJob(
        job.id,
        error instanceof Error ? error.message : 'sync failed',
        claimToken
      );
      if (failedJob.status === 'cancelled') {
        return failedJob;
      }
      throw error;
    } finally {
      clearInterval(heartbeatTimer);
    }
  }

  async function processDueWebhookDeliveries(
    handler: PlugFnWebhookDeliveryHandler,
    options: PlugFnWebhookDeliveryWorkerOptions = {}
  ): Promise<PlugFnWebhookDeliveryWorkerResult> {
    const maxAttempts = Math.max(1, options.maxAttempts ?? 5);
    const baseDelayMs = Math.max(1000, options.baseDelayMs ?? 30_000);
    const leaseMs = Math.max(30, options.leaseMs ?? 5 * 60 * 1000);
    const dueDeliveries = await runtimeStorage.claimWebhookDeliveriesForRetry(
      new Date(),
      options.limit ?? 100,
      undefined,
      leaseMs
    );
    const deliveries: PlugFnWebhookDelivery[] = [];
    let succeeded = 0;
    let failed = 0;
    let deadLettered = 0;

    for (const delivery of dueDeliveries) {
      const attempt = delivery.attempts;
      const claimToken = delivery.claimToken;
      if (!claimToken) {
        failed += 1;
        continue;
      }

      const updateClaimed = (updates: Partial<PlugFnWebhookDelivery>) =>
        runtimeStorage.updateClaimedWebhookDelivery(delivery.id, claimToken, {
          ...updates,
          claimToken: undefined,
        });
      const receipt = await runtimeStorage.getWebhookReceipt(delivery.receiptId);
      if (!receipt) {
        const deadLetter = await updateClaimed({
          status: 'dead-lettered',
          attempts: attempt,
          error: 'webhook receipt not found',
          metadata: withoutWebhookReplayBody(delivery.metadata),
        });
        if (deadLetter) {
          deliveries.push(deadLetter);
          deadLettered += 1;
        } else {
          failed += 1;
        }
        continue;
      }

      const receiptDeliveries = await runtimeStorage.listWebhookDeliveries(receipt.id);
      if (
        receiptDeliveries.some(
          (receiptDelivery) =>
            receiptDelivery.id !== delivery.id &&
            receiptDelivery.status === 'success' &&
            receiptDelivery.sinkId === delivery.sinkId &&
            receiptDelivery.handlerName === delivery.handlerName
        )
      ) {
        const superseded = await updateClaimed({
          status: 'dead-lettered',
          attempts: attempt,
          error: 'webhook receipt was already delivered successfully',
          nextAttemptAt: undefined,
          metadata: withoutWebhookReplayBody(delivery.metadata),
        });
        if (superseded) {
          deliveries.push(superseded);
          deadLettered += 1;
        } else {
          failed += 1;
        }
        continue;
      }

      let leaseLost = false;
      let heartbeatInFlight: Promise<void> | undefined;
      const heartbeat = () => {
        if (heartbeatInFlight) return;
        heartbeatInFlight = runtimeStorage
          .updateClaimedWebhookDelivery(delivery.id, claimToken, {})
          .then((renewed) => {
            if (!renewed) leaseLost = true;
          })
          .catch(() => {
            leaseLost = true;
          })
          .finally(() => {
            heartbeatInFlight = undefined;
          });
      };
      const heartbeatTimer = setInterval(heartbeat, Math.max(10, Math.floor(leaseMs / 3)));
      const finishClaim = async (updates: Partial<PlugFnWebhookDelivery>) => {
        clearInterval(heartbeatTimer);
        await heartbeatInFlight;
        if (leaseLost) return null;
        return updateClaimed(updates);
      };

      try {
        if (webhookReplayBodyExpired(delivery)) {
          throw new Error('webhook retry payload expired');
        }
        await handler({
          delivery,
          receipt,
          provider: receipt.provider,
          event: receipt.event,
          headers: receipt.headersRedacted ?? {},
          rawBody: decodeWebhookDeliveryBody(delivery),
        });
        const updated = await finishClaim({
          status: 'success',
          attempts: attempt,
          metadata: withoutWebhookReplayBody(delivery.metadata),
        });
        if (updated) {
          deliveries.push(updated);
          succeeded += 1;
        } else {
          failed += 1;
        }
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'webhook delivery failed';
        const status =
          webhookReplayBodyExpired(delivery) || attempt >= maxAttempts ? 'dead-lettered' : 'failed';
        const nextAttemptAt =
          status === 'failed'
            ? new Date(Date.now() + baseDelayMs * 2 ** Math.max(0, attempt - 1))
            : undefined;
        const updated = await finishClaim({
          status,
          attempts: attempt,
          error: errorMessage,
          nextAttemptAt,
          ...(status === 'dead-lettered'
            ? { metadata: withoutWebhookReplayBody(delivery.metadata) }
            : {}),
        });
        if (updated) {
          deliveries.push(updated);
          if (status === 'dead-lettered') {
            deadLettered += 1;
          } else {
            failed += 1;
          }
        } else {
          failed += 1;
        }
      }
    }

    return {
      processed: dueDeliveries.length,
      succeeded,
      failed,
      deadLettered,
      deliveries,
    };
  }

  function decodeWebhookDeliveryBody(delivery: PlugFnWebhookDelivery): Uint8Array {
    const encoded = delivery.metadata?.rawBodyBase64;
    if (typeof encoded !== 'string') {
      return new Uint8Array();
    }
    return Buffer.from(encoded, 'base64');
  }

  function webhookReplayBodyExpired(delivery: PlugFnWebhookDelivery): boolean {
    const expiresAt = delivery.metadata?.rawBodyExpiresAt;
    return typeof expiresAt === 'string' && Date.parse(expiresAt) <= Date.now();
  }

  function withoutWebhookReplayBody(
    metadata: Record<string, unknown> | undefined
  ): Record<string, unknown> | undefined {
    if (!metadata) return undefined;
    return Object.fromEntries(
      Object.entries(metadata).filter(
        ([key]) => key !== 'rawBodyBase64' && key !== 'rawBodyExpiresAt'
      )
    );
  }

  // Create dynamic provider proxies
  proxyApi = new Proxy(api, {
    get(target, prop: string) {
      // If property exists on target, return it
      if (prop in target) {
        return target[prop as keyof typeof target];
      }

      // Check if it's a provider
      const provider = providerRegistry.get(prop);
      if (!provider) {
        return undefined;
      }

      // Create provider action proxy
      const providerProxy: any = {
        on: (event: string, handler: TriggerHandler) => {
          webhookHandler.on(prop, event, handler);
        },
      };

      // Add all actions
      for (const [actionName, _action] of Object.entries(provider.actions)) {
        providerProxy[actionName] = async (options: ActionOptions) => {
          const result = await actionExecutor.execute(prop, actionName, options);
          if (!result.success) {
            throw result.error;
          }
          return result.data;
        };
      }

      return providerProxy;
    },
  }) as PlugFn;

  return proxyApi;
}

function resolvePersistenceSink(
  sinks: Map<string, PlugFnPersistenceSink>,
  input: {
    sinkId?: string;
    provider: string;
    resource: string;
  }
): PlugFnPersistenceSink {
  if (input.sinkId) {
    const sink = sinks.get(input.sinkId);
    if (!sink) {
      throw new Error(`Persistence sink ${input.sinkId} not found`);
    }
    return sink;
  }

  const sink = [...sinks.values()].find((candidate) => {
    return candidate.provider === input.provider && candidate.resource === input.resource;
  });
  if (!sink) {
    throw new Error(`Persistence sink not found for ${input.provider}.${input.resource}`);
  }
  return sink;
}

async function persistSinkItem(
  sink: PlugFnPersistenceSink,
  raw: unknown,
  context: PlugFnSinkContext
): Promise<{ idempotencyKey: string }> {
  if (sink.idempotencyKeyForRecord) {
    const record = await sink.transform(raw, context);
    const idempotencyKey = sink.idempotencyKeyForRecord(record, context);
    await sink.upsert(record, {
      ...context,
      metadata: {
        ...(context.metadata ?? {}),
        idempotencyKey,
      },
    });
    return { idempotencyKey };
  }

  const idempotencyKey = sink.idempotencyKey(raw, context);
  const record = await sink.transform(raw, {
    ...context,
    metadata: {
      ...(context.metadata ?? {}),
      idempotencyKey,
    },
  });
  await sink.upsert(record, context);
  return { idempotencyKey };
}

async function executeSyncResource(input: {
  providerRegistry: ProviderRegistry;
  actionExecutor: ActionExecutor;
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  connectionId: string;
  resource: string;
  mode: PlugFnSyncJob['mode'];
  userId: string;
  tenantId?: string;
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages: number;
  onPage?: (progress: {
    fetchedCount: number;
    persistedCount: number;
    skippedCount: number;
    cursor?: string;
    checkpoint?: unknown;
  }) => Promise<void> | void;
  shouldContinue?: () => Promise<boolean> | boolean;
}): Promise<{
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  cursor?: string;
  checkpoint?: unknown;
}> {
  const provider = input.providerRegistry.get(input.provider);
  if (!provider) {
    throw {
      code: 'PROVIDER_NOT_REGISTERED',
      message: `provider ${input.provider} is not registered`,
      status: 404,
    };
  }

  const syncDefinition = provider.sync?.[input.resource];
  if (syncDefinition) {
    return executeProviderSyncDefinition({ ...input, syncDefinition });
  }

  const fallbackAction = resolveSyncActionName(provider, input.resource);
  if (!fallbackAction) {
    throw {
      code: 'SYNC_RESOURCE_NOT_FOUND',
      message: `sync resource ${input.provider}.${input.resource} is not registered`,
      status: 404,
    };
  }

  if (input.shouldContinue && !(await input.shouldContinue())) {
    throw syncCancelledError();
  }

  const result = await input.actionExecutor.execute(input.provider, fallbackAction, {
    userId: input.userId,
    connectionId: input.connectionId,
    params: {
      tenantId: input.tenantId,
      mode: input.mode,
      checkpoint: input.checkpoint,
      cursor: input.cursor,
    },
    cache: false,
  });

  if (!result.success) {
    throw result.error;
  }

  const data = (result.data ?? {}) as Record<string, unknown>;
  const fallbackItems = resolveFallbackSyncItems(data);
  const fallbackSink = resolveFallbackSyncSink(input);
  const persistedCount = fallbackSink
    ? await persistFallbackSyncItems(fallbackSink, fallbackItems, input, fallbackAction)
    : (asNumber(data.upserted) ?? asNumber(data.persistedCount) ?? 0);

  return {
    fetchedCount:
      asNumber(data.fetched) ??
      asNumber(data.fetchedCount) ??
      asNumber(data.count) ??
      fallbackItems?.length ??
      0,
    persistedCount,
    skippedCount: asNumber(data.skipped) ?? asNumber(data.skippedCount) ?? 0,
    checkpoint: data.checkpoint,
    cursor: typeof data.cursor === 'string' ? data.cursor : undefined,
  };
}

function resolveFallbackSyncSink(input: {
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  resource: string;
  sinkId?: string;
}): PlugFnPersistenceSink | undefined {
  if (input.sinkId) {
    const sink = input.persistenceSinks.get(input.sinkId);
    if (!sink) {
      throw new PlugFnRuntimeError(
        'SYNC_SINK_NOT_FOUND',
        `persistence sink ${input.sinkId} is not registered`,
        404
      );
    }
    return sink;
  }

  return [...input.persistenceSinks.values()].find((candidate) => {
    return candidate.provider === input.provider && candidate.resource === input.resource;
  });
}

async function persistFallbackSyncItems(
  sink: PlugFnPersistenceSink,
  items: unknown[] | undefined,
  input: { provider: string; resource: string; connectionId: string },
  fallbackAction: string
): Promise<number> {
  if (!items) {
    throw new PlugFnRuntimeError(
      'SYNC_FALLBACK_ITEMS_REQUIRED',
      `fallback action ${input.provider}.${fallbackAction} must return items for persistence`,
      500
    );
  }

  for (const item of items) {
    await persistSinkItem(sink, item, {
      provider: input.provider,
      resource: input.resource,
      connectionId: input.connectionId,
    });
  }
  return items.length;
}

function resolveFallbackSyncItems(data: Record<string, unknown>): unknown[] | undefined {
  if (Array.isArray(data.items)) {
    return data.items;
  }
  if (Array.isArray(data.messages)) {
    return data.messages;
  }
  return undefined;
}

async function executeProviderSyncDefinition(input: {
  syncDefinition: NonNullable<Provider['sync']>[string];
  persistenceSinks: Map<string, PlugFnPersistenceSink>;
  provider: string;
  connectionId: string;
  resource: string;
  mode: PlugFnSyncJob['mode'];
  sinkId?: string;
  cursor?: string;
  checkpoint?: unknown;
  maxPages: number;
  onPage?: (progress: {
    fetchedCount: number;
    persistedCount: number;
    skippedCount: number;
    cursor?: string;
    checkpoint?: unknown;
  }) => Promise<void> | void;
  shouldContinue?: () => Promise<boolean> | boolean;
}): Promise<{
  fetchedCount: number;
  persistedCount: number;
  skippedCount: number;
  cursor?: string;
  checkpoint?: unknown;
}> {
  if (input.sinkId && !input.persistenceSinks.has(input.sinkId)) {
    throw new PlugFnRuntimeError(
      'SYNC_SINK_NOT_FOUND',
      `persistence sink ${input.sinkId} is not registered`,
      404
    );
  }

  let fetchedCount = 0;
  let persistedCount = 0;
  let skippedCount = 0;
  let cursor = input.cursor;
  let checkpoint = input.checkpoint ?? input.syncDefinition.initialCheckpoint;
  let pages = 0;

  while (pages < input.maxPages) {
    if (input.shouldContinue && !(await input.shouldContinue())) {
      throw syncCancelledError();
    }

    pages += 1;
    const result: PlugFnSyncFetchResult = await input.syncDefinition.fetch({
      provider: input.provider,
      resource: input.resource,
      connectionId: input.connectionId,
      mode: input.mode,
      checkpoint,
      cursor,
    });

    if (input.shouldContinue && !(await input.shouldContinue())) {
      throw syncCancelledError();
    }

    fetchedCount += result.items.length;
    checkpoint = result.checkpoint ?? checkpoint;
    cursor = result.cursor;

    const sinkId = input.sinkId ?? result.sinkId ?? input.syncDefinition.defaultSinkId;
    if (sinkId && !input.persistenceSinks.has(sinkId)) {
      throw new PlugFnRuntimeError(
        'SYNC_SINK_NOT_FOUND',
        `persistence sink ${sinkId} is not registered`,
        404
      );
    }
    if (sinkId || input.persistenceSinks.size > 0) {
      const sink = sinkId
        ? input.persistenceSinks.get(sinkId)
        : [...input.persistenceSinks.values()].find((candidate) => {
            return candidate.provider === input.provider && candidate.resource === input.resource;
          });

      if (sink) {
        for (const item of result.items) {
          if (input.shouldContinue && !(await input.shouldContinue())) {
            throw syncCancelledError();
          }
          const context: PlugFnSinkContext = {
            provider: input.provider,
            resource: input.resource,
            connectionId: input.connectionId,
          };
          await persistSinkItem(sink, item, context);
          persistedCount += 1;
        }
      } else {
        skippedCount += result.items.length;
      }
    } else {
      skippedCount += result.items.length;
    }

    if (result.done !== false || !cursor) {
      await input.onPage?.({
        fetchedCount,
        persistedCount,
        skippedCount,
        cursor,
        checkpoint,
      });
      break;
    }

    await input.onPage?.({
      fetchedCount,
      persistedCount,
      skippedCount,
      cursor,
      checkpoint,
    });
  }

  return {
    fetchedCount,
    persistedCount,
    skippedCount,
    cursor,
    checkpoint,
  };
}

function syncCancelledError(): { code: string; message: string; status: number } {
  return {
    code: 'SYNC_CANCELLED',
    message: 'sync job was cancelled',
    status: 409,
  };
}

function syncJobClaimLostError(jobId: string): PlugFnRuntimeError {
  return new PlugFnRuntimeError(
    'SYNC_JOB_CLAIM_LOST',
    `sync job ${jobId} claim is no longer owned by this worker`,
    409
  );
}

class PlugFnRuntimeError extends Error {
  readonly retryable = false;

  constructor(
    readonly code: string,
    message: string,
    readonly status: number
  ) {
    super(message);
    this.name = 'PlugFnRuntimeError';
  }
}

function isSyncCancelledError(error: unknown): boolean {
  return (
    !!error &&
    typeof error === 'object' &&
    'code' in error &&
    (error as { code?: unknown }).code === 'SYNC_CANCELLED'
  );
}

function resolveSyncActionName(provider: Provider, resource: string): string | undefined {
  const candidates = [
    `${resource}.sync`,
    `sync.${resource}`,
    resource === 'messages' ? 'mail.sync' : undefined,
  ].filter((candidate): candidate is string => typeof candidate === 'string');

  return candidates.find((candidate) => candidate in provider.actions);
}

function readSyncJobWorkerMetadata(job: PlugFnSyncJob): {
  sinkId?: string;
  maxPages?: number;
  actor?: PlugFnSyncRunOptions['actor'];
} {
  const raw = job.metadata?.plugfnSync;
  if (!raw || typeof raw !== 'object') {
    return {};
  }

  const record = raw as Record<string, unknown>;
  return {
    sinkId: typeof record.sinkId === 'string' ? record.sinkId : undefined,
    maxPages: typeof record.maxPages === 'number' ? record.maxPages : undefined,
    actor: isSyncActor(record.actor) ? record.actor : undefined,
  };
}

function isSyncActor(value: unknown): value is PlugFnSyncRunOptions['actor'] {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as { userId?: unknown }).userId === 'string'
  );
}

function connectionToOwner(connection: Connection): PlugFnConnectionOwner {
  if (
    connection.ownerKind === 'organization' &&
    connection.organizationId &&
    connection.installedByUserId
  ) {
    return {
      kind: 'organization',
      organizationId: connection.organizationId,
      installedByUserId: connection.installedByUserId,
      tenantId: connection.tenantId,
    };
  }

  if (
    connection.ownerKind === 'delegated' &&
    connection.organizationId &&
    connection.installedByUserId &&
    connection.delegatedToUserId
  ) {
    return {
      kind: 'delegated',
      organizationId: connection.organizationId,
      installedByUserId: connection.installedByUserId,
      delegatedToUserId: connection.delegatedToUserId,
      grants: connection.grants ?? [],
      tenantId: connection.tenantId,
    };
  }

  return {
    kind: 'user',
    userId: connection.ownerId ?? connection.userId,
    tenantId: connection.tenantId,
  };
}

function asNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function normalizeAuthProvider(configuredAuth: PlugFnConfig['auth']): {
  authenticate(request: Request): Promise<PlugFnPrincipal | null>;
} {
  if (typeof configuredAuth.authenticate === 'function') {
    return {
      authenticate: async (request: Request) => {
        const principal = await configuredAuth.authenticate!(request);
        return normalizePrincipal(principal);
      },
    };
  }

  return {
    authenticate: async (request: Request) => {
      if (typeof configuredAuth.getUserId === 'function') {
        const userId = await configuredAuth.getUserId(request);
        return normalizePrincipal(userId);
      }

      if (typeof configuredAuth.requireAuth === 'function') {
        try {
          const userId = await configuredAuth.requireAuth(request);
          return normalizePrincipal(userId);
        } catch {
          return null;
        }
      }

      return null;
    },
  };
}

function normalizePrincipal(
  value: PlugFnPrincipal | AuthSession | string | null | undefined
): PlugFnPrincipal | null {
  if (!value) {
    return null;
  }

  if (typeof value === 'string') {
    return value.length > 0 ? { userId: value } : null;
  }

  if (
    typeof value === 'object' &&
    'userId' in value &&
    typeof value.userId === 'string' &&
    value.userId.length > 0
  ) {
    return value as PlugFnPrincipal;
  }

  const subject =
    typeof value === 'object' && 'subject' in value
      ? (value as Partial<AuthSession>).subject
      : null;
  if (
    subject !== null &&
    typeof subject === 'object' &&
    typeof subject.actorId === 'string' &&
    subject.actorId.length > 0
  ) {
    const session = value as AuthSession;
    return {
      userId: session.subject.actorId,
      tenantId: session.subject.tenantId,
      roles: session.resourceIds,
      grants: session.scopes,
      metadata: session.metadata,
    };
  }

  return null;
}

import type {
  Workflow,
  WorkflowContext,
  WorkflowExecution,
  WorkflowStats,
  ListWorkflowsOptions,
  WorkflowStep,
  WorkflowAction,
  WorkflowCondition,
  WorkflowErrorHandlerFn,
  WorkflowRuntimeRegistry,
} from '../types/workflow.js';
import { WorkflowStatus, WorkflowExecutionStatus } from '../types/workflow.js';
import type { Logger } from '../types/action.js';
import { WorkflowStorage } from '../storage/workflow-storage.js';
import { WebhookHandler } from '../webhooks/webhook-handler.js';
import type { TriggerHandler } from '../types/trigger.js';

interface PersistedWorkflowState {
  idempotencyKey?: string;
  completedStepIds: string[];
  retriable: boolean;
  resumed: boolean;
  failedStepId?: string;
  errorCode?: string;
}

interface WorkflowTriggerBinding {
  backend: 'webhook-handler';
  provider: string;
  event: string;
  handler: TriggerHandler;
}

export class WorkflowEngineError extends Error {
  readonly code:
    | 'WORKFLOW_TRIGGER_UNREGISTER_FAILED'
    | 'WORKFLOW_DURABILITY_UNSUPPORTED'
    | 'WORKFLOW_DEFINITION_INVALID';
  readonly status: number;
  readonly retryable = false;
  readonly details: Record<string, unknown>;

  constructor(
    code:
      | 'WORKFLOW_TRIGGER_UNREGISTER_FAILED'
      | 'WORKFLOW_DURABILITY_UNSUPPORTED'
      | 'WORKFLOW_DEFINITION_INVALID',
    message: string,
    details: Record<string, unknown> = {}
  ) {
    super(message);
    this.name = 'WorkflowEngineError';
    this.code = code;
    this.status = 409;
    this.details = details;
  }
}

export class WorkflowEngine {
  private readonly triggerBindings = new Map<string, WorkflowTriggerBinding>();
  private readonly executionLocks = new Map<string, Promise<void>>();

  constructor(
    private workflowStorage: WorkflowStorage,
    private webhookHandler: WebhookHandler,
    private logger: Logger,
    private runtime: WorkflowRuntimeRegistry = {}
  ) {}

  async create(workflow: Omit<Workflow, 'id' | 'createdAt' | 'updatedAt'>): Promise<Workflow> {
    assertUniqueWorkflowStepIds(workflow.definition.steps);
    const created = await this.workflowStorage.create(workflow);

    if (workflow.status === WorkflowStatus.Enabled) {
      await this.registerTrigger(created);
    }

    this.logger.info(`Workflow created: ${created.name}`, { workflowId: created.id });
    return created;
  }

  async get(id: string): Promise<Workflow | null> {
    return this.workflowStorage.get(id);
  }

  async list(options?: ListWorkflowsOptions): Promise<Workflow[]> {
    return this.workflowStorage.list(options?.userId, options?.status);
  }

  async rehydrateEnabledTriggers(): Promise<{ registered: number; failed: number }> {
    const workflows = await this.workflowStorage.list(undefined, WorkflowStatus.Enabled);
    let registered = 0;
    let failed = 0;

    for (const workflow of workflows) {
      try {
        await this.registerTrigger(workflow);
        registered += 1;
      } catch (error) {
        failed += 1;
        this.logger.error('Workflow trigger rehydration failed', {
          workflowId: workflow.id,
          error,
        });
      }
    }

    return { registered, failed };
  }

  async enable(id: string): Promise<void> {
    const workflow = await this.workflowStorage.get(id);
    if (!workflow) {
      throw new Error(`Workflow ${id} not found`);
    }
    assertUniqueWorkflowStepIds(workflow.definition.steps);

    const updated = await this.workflowStorage.update(id, { status: WorkflowStatus.Enabled });
    await this.registerTrigger(updated);

    this.logger.info(`Workflow enabled: ${workflow.name}`, { workflowId: id });
  }

  async disable(id: string): Promise<void> {
    const workflow = await this.workflowStorage.get(id);
    if (!workflow) {
      throw new Error(`Workflow ${id} not found`);
    }

    const updated = await this.workflowStorage.update(id, { status: WorkflowStatus.Disabled });
    await this.unregisterTrigger(updated);

    this.logger.info(`Workflow disabled: ${workflow.name}`, { workflowId: id });
  }

  async delete(id: string): Promise<void> {
    const workflow = await this.workflowStorage.get(id);
    if (
      workflow &&
      (workflow.status === WorkflowStatus.Enabled || this.triggerBindings.has(workflow.id))
    ) {
      await this.unregisterTrigger(workflow);
    }

    await this.workflowStorage.delete(id);
    this.logger.info(`Workflow deleted`, { workflowId: id });
  }

  async execute(workflowId: string, triggerPayload: any): Promise<WorkflowExecution> {
    const workflow = await this.workflowStorage.get(workflowId);
    if (!workflow) {
      throw new Error(`Workflow ${workflowId} not found`);
    }

    if (workflow.status !== WorkflowStatus.Enabled) {
      throw new Error(`Workflow ${workflowId} is not enabled`);
    }
    assertUniqueWorkflowStepIds(workflow.definition.steps);

    const idempotencyKey = this.resolveIdempotencyKey(triggerPayload);
    const lockKey = idempotencyKey ? `${workflowId}:${idempotencyKey}` : undefined;
    const previousExecution = lockKey
      ? (this.executionLocks.get(lockKey) ?? Promise.resolve())
      : Promise.resolve();
    let releaseExecutionLock: (() => void) | undefined;
    let queueTail: Promise<void> | undefined;
    if (lockKey) {
      const current = new Promise<void>((resolve) => {
        releaseExecutionLock = resolve;
      });
      queueTail = previousExecution.catch(() => {}).then(() => current);
      this.executionLocks.set(lockKey, queueTail);
    }

    await previousExecution.catch(() => {});

    try {
      const existingExecution = idempotencyKey
        ? await this.workflowStorage.findExecutionByIdempotencyKey(workflowId, idempotencyKey)
        : null;

      if (existingExecution && existingExecution.status === WorkflowExecutionStatus.Completed) {
        return existingExecution;
      }

      const resumed = Boolean(existingExecution);
      const execution =
        existingExecution ??
        (await this.workflowStorage.createExecution({
          workflowId,
          status: WorkflowExecutionStatus.Running,
          input: this.buildExecutionInput(triggerPayload, idempotencyKey),
        }));

      if (existingExecution) {
        await this.workflowStorage.updateExecution(existingExecution.id, {
          status: WorkflowExecutionStatus.Running,
          error: undefined,
        });
      }

      const executionState = this.readExecutionState(existingExecution ?? null);
      const completedStepIds = [...executionState.completedStepIds];
      const contextData = { ...executionState.data };

      const context: WorkflowContext = {
        workflowId,
        executionId: execution.id,
        userId: workflow.userId,
        trigger: {
          provider: workflow.definition.trigger.provider,
          event: workflow.definition.trigger.event,
          payload: triggerPayload,
        },
        data: contextData,
      };
      const checkpointStep = async (stepId: string): Promise<void> => {
        if (!completedStepIds.includes(stepId)) {
          completedStepIds.push(stepId);
        }
        await this.workflowStorage.updateExecution(execution.id, {
          status: WorkflowExecutionStatus.Running,
          output: this.buildExecutionOutput(context.data, {
            idempotencyKey,
            completedStepIds,
            retriable: false,
            resumed,
          }),
        });
      };

      const startedAtMs = execution.startedAt ? execution.startedAt.getTime() : Date.now();
      let activeStepId: string | undefined;

      try {
        if (workflow.definition.trigger.filter) {
          const shouldRun = this.resolveCondition(
            workflow.definition.trigger.filter,
            'workflow trigger filter'
          )(context);
          if (!shouldRun) {
            await this.workflowStorage.updateExecution(execution.id, {
              status: WorkflowExecutionStatus.Completed,
              output: this.buildExecutionOutput(context.data, {
                idempotencyKey,
                completedStepIds,
                retriable: false,
                resumed,
              }),
              completedAt: new Date(),
              durationMs: Date.now() - startedAtMs,
            });

            const skippedExecution = await this.getExecutionById(workflowId, execution.id);
            return skippedExecution ?? execution;
          }
        }

        for (const step of workflow.definition.steps) {
          activeStepId = step.id;
          if (completedStepIds.includes(step.id)) {
            continue;
          }

          await this.executeStep(step, context, completedStepIds, checkpointStep);
          await checkpointStep(step.id);
        }

        await this.workflowStorage.updateExecution(execution.id, {
          status: WorkflowExecutionStatus.Completed,
          output: this.buildExecutionOutput(context.data, {
            idempotencyKey,
            completedStepIds,
            retriable: false,
            resumed,
          }),
          completedAt: new Date(),
          durationMs: Date.now() - startedAtMs,
        });

        this.logger.info(`Workflow executed successfully: ${workflow.name}`, {
          workflowId,
          executionId: execution.id,
          duration: Date.now() - startedAtMs,
          resumed,
        });

        const completedExecution = await this.getExecutionById(workflowId, execution.id);
        return completedExecution ?? execution;
      } catch (error) {
        const failure = normalizeWorkflowExecutionFailure(error);
        this.logger.error(`Workflow execution failed: ${workflow.name}`, {
          workflowId,
          executionId: execution.id,
          error: failure.error,
        });

        if (workflow.definition.errorHandlers) {
          for (const errorHandler of workflow.definition.errorHandlers) {
            try {
              await this.resolveErrorHandler(
                errorHandler.handler,
                `workflow error handler${errorHandler.stepId ? ` for ${errorHandler.stepId}` : ''}`
              )(failure.error, context);
            } catch (handlerError) {
              this.logger.error('Error handler failed', { handlerError });
            }
          }
        }

        await this.workflowStorage.updateExecution(execution.id, {
          status: WorkflowExecutionStatus.Failed,
          error: `${failure.code}:${failure.error.message}`,
          output: this.buildExecutionOutput(context.data, {
            idempotencyKey,
            completedStepIds,
            retriable: failure.retriable,
            resumed,
            failedStepId: activeStepId,
            errorCode: failure.code,
          }),
          completedAt: new Date(),
          durationMs: Date.now() - startedAtMs,
        });

        throw failure.error;
      }
    } finally {
      if (lockKey && releaseExecutionLock) {
        releaseExecutionLock();
        if (this.executionLocks.get(lockKey) === queueTail) {
          this.executionLocks.delete(lockKey);
        }
      }
    }
  }

  private async executeStep(
    step: WorkflowStep,
    context: WorkflowContext,
    completedStepIds: string[],
    checkpointStep: (stepId: string) => Promise<void>
  ): Promise<void> {
    switch (step.type) {
      case 'action': {
        const result = await this.resolveAction(step.action, `action step ${step.id}`)(context);
        Object.assign(context.data, result);
        break;
      }

      case 'filter': {
        const shouldContinue = this.resolveCondition(
          step.condition,
          `filter step ${step.id}`
        )(context);
        if (!shouldContinue) {
          throw new Error('Filter condition not met');
        }
        break;
      }

      case 'branch': {
        await this.executeBranchStep(step, context, completedStepIds, checkpointStep);
        break;
      }

      case 'parallel': {
        await this.executeParallelStep(step, context, completedStepIds, checkpointStep);
        break;
      }

      case 'delay': {
        const ms = this.convertDelayToMs(step);
        throw new WorkflowEngineError(
          'WORKFLOW_DURABILITY_UNSUPPORTED',
          `delay step ${step.id} requires a durable scheduler`,
          {
            stepId: step.id,
            durationMs: ms,
          }
        );
      }

      default: {
        const unsupportedType = (step as { type?: unknown }).type;
        throw new Error(`Unknown workflow step type: ${String(unsupportedType)}`);
      }
    }
  }

  private async executeBranchStep(
    step: Extract<WorkflowStep, { type: 'branch' }>,
    context: WorkflowContext,
    completedStepIds: string[],
    checkpointStep: (stepId: string) => Promise<void>
  ): Promise<void> {
    const branch = this.resolveCondition(step.condition, `branch step ${step.id}`)(context)
      ? step.then
      : step.else;
    if (!branch) {
      return;
    }

    for (const branchStep of branch) {
      if (completedStepIds.includes(branchStep.id)) {
        continue;
      }
      await this.executeStep(branchStep, context, completedStepIds, checkpointStep);
      await checkpointStep(branchStep.id);
    }
  }

  private async executeParallelStep(
    step: Extract<WorkflowStep, { type: 'parallel' }>,
    context: WorkflowContext,
    completedStepIds: string[],
    checkpointStep: (stepId: string) => Promise<void>
  ): Promise<void> {
    const pendingActions = step.actions
      .map((action, index) => ({
        action: this.resolveAction(action, `parallel step ${step.id} action ${index}`),
        checkpointId: parallelActionCheckpointId(step.id, index),
      }))
      .filter(({ checkpointId }) => !completedStepIds.includes(checkpointId));
    const results = await Promise.allSettled(pendingActions.map(({ action }) => action(context)));

    for (const [index, result] of results.entries()) {
      if (result.status === 'fulfilled') {
        await checkpointStep(pendingActions[index].checkpointId);
      }
    }

    const failure = results.find(
      (result): result is PromiseRejectedResult => result.status === 'rejected'
    );
    if (failure) {
      throw failure.reason;
    }
  }

  private convertDelayToMs(step: any): number {
    const { duration, unit = 'ms' } = step;

    switch (unit) {
      case 'ms':
        return duration;
      case 'seconds':
        return duration * 1000;
      case 'minutes':
        return duration * 60 * 1000;
      case 'hours':
        return duration * 60 * 60 * 1000;
      case 'days':
        return duration * 24 * 60 * 60 * 1000;
      default:
        return duration;
    }
  }

  private resolveAction(action: string | WorkflowAction, location: string): WorkflowAction {
    if (typeof action === 'function') {
      return action;
    }
    const resolved = this.runtime.actions?.[action];
    if (!resolved) {
      throw this.missingRuntimeReference('action', action, location);
    }
    return resolved;
  }

  private resolveCondition(
    condition: WorkflowCondition,
    location: string
  ): Exclude<WorkflowCondition, string> {
    if (typeof condition === 'function') {
      return condition;
    }
    const resolved = this.runtime.conditions?.[condition];
    if (!resolved) {
      throw this.missingRuntimeReference('condition', condition, location);
    }
    return resolved;
  }

  private resolveErrorHandler(
    handler: string | WorkflowErrorHandlerFn,
    location: string
  ): WorkflowErrorHandlerFn {
    if (typeof handler === 'function') {
      return handler;
    }
    const resolved = this.runtime.errorHandlers?.[handler];
    if (!resolved) {
      throw this.missingRuntimeReference('error handler', handler, location);
    }
    return resolved;
  }

  private missingRuntimeReference(
    kind: string,
    reference: string,
    location: string
  ): WorkflowEngineError {
    return new WorkflowEngineError(
      'WORKFLOW_DEFINITION_INVALID',
      `${location} references unregistered ${kind} ${reference}`,
      { kind, reference, location }
    );
  }

  async getStats(workflowId: string): Promise<WorkflowStats> {
    const executions = await this.workflowStorage.listExecutions(workflowId, 1000);

    const totalExecutions = executions.length;
    const successfulExecutions = executions.filter(
      (execution) => execution.status === WorkflowExecutionStatus.Completed
    ).length;
    const failedExecutions = executions.filter(
      (execution) => execution.status === WorkflowExecutionStatus.Failed
    ).length;

    const successRate = totalExecutions > 0 ? (successfulExecutions / totalExecutions) * 100 : 0;

    const durations = executions
      .filter((execution) => execution.durationMs)
      .map((execution) => execution.durationMs as number);
    const avgDuration =
      durations.length > 0
        ? durations.reduce((left, right) => left + right, 0) / durations.length
        : 0;

    const lastExecutedAt = executions.length > 0 ? executions[0].startedAt : undefined;

    return {
      totalExecutions,
      successfulExecutions,
      failedExecutions,
      successRate,
      avgDuration,
      lastExecutedAt,
    };
  }

  private async registerTrigger(workflow: Workflow): Promise<void> {
    assertUniqueWorkflowStepIds(workflow.definition.steps);
    if (this.triggerBindings.has(workflow.id)) {
      await this.unregisterTrigger(workflow, { allowMissing: true });
    }

    const handler: TriggerHandler = async (event: any) => {
      try {
        await this.execute(workflow.id, event);
      } catch (error) {
        this.logger.error(`Workflow trigger execution failed`, { workflow: workflow.id, error });
        throw error;
      }
    };

    this.webhookHandler.on(
      workflow.definition.trigger.provider,
      workflow.definition.trigger.event,
      handler
    );

    this.triggerBindings.set(workflow.id, {
      backend: 'webhook-handler',
      provider: workflow.definition.trigger.provider,
      event: workflow.definition.trigger.event,
      handler,
    });

    this.logger.info('Workflow trigger registered', {
      workflowId: workflow.id,
      backend: 'webhook-handler',
      provider: workflow.definition.trigger.provider,
      event: workflow.definition.trigger.event,
    });
  }

  private async unregisterTrigger(
    workflow: Workflow,
    options: { allowMissing?: boolean } = {}
  ): Promise<void> {
    const binding = this.triggerBindings.get(workflow.id);

    if (!binding) {
      this.logger.error('Workflow trigger unregister failed: missing active binding', {
        workflowId: workflow.id,
        provider: workflow.definition.trigger.provider,
        event: workflow.definition.trigger.event,
      });

      if (options.allowMissing) {
        return;
      }

      throw new WorkflowEngineError(
        'WORKFLOW_TRIGGER_UNREGISTER_FAILED',
        `active trigger binding not found for workflow ${workflow.id}`,
        {
          workflowId: workflow.id,
          provider: workflow.definition.trigger.provider,
          event: workflow.definition.trigger.event,
          backend: 'webhook-handler',
        }
      );
    }

    this.webhookHandler.off(binding.provider, binding.event, binding.handler);
    this.triggerBindings.delete(workflow.id);

    this.logger.info('Workflow trigger unregistered', {
      workflowId: workflow.id,
      backend: binding.backend,
      provider: binding.provider,
      event: binding.event,
    });
  }

  private buildExecutionInput(triggerPayload: any, idempotencyKey?: string): any {
    return {
      ...triggerPayload,
      __workflow: {
        idempotencyKey,
      },
    };
  }

  private buildExecutionOutput(data: Record<string, any>, state: PersistedWorkflowState): any {
    return {
      data,
      __workflow: {
        idempotencyKey: state.idempotencyKey,
        completedStepIds: [...state.completedStepIds],
        retriable: state.retriable,
        resumed: state.resumed,
        failedStepId: state.failedStepId,
        errorCode: state.errorCode,
      },
    };
  }

  private readExecutionState(execution: WorkflowExecution | null): {
    data: Record<string, any>;
    completedStepIds: string[];
  } {
    if (!execution || !execution.output || typeof execution.output !== 'object') {
      return {
        data: {},
        completedStepIds: [],
      };
    }

    const output = execution.output as Record<string, any>;
    const workflowState = output.__workflow as Record<string, any> | undefined;
    const completedStepIds = Array.isArray(workflowState?.completedStepIds)
      ? workflowState?.completedStepIds.filter((value: unknown): value is string => {
          return typeof value === 'string' && value.length > 0;
        })
      : [];

    const data =
      output.data && typeof output.data === 'object' ? (output.data as Record<string, any>) : {};

    return {
      data,
      completedStepIds,
    };
  }

  private resolveIdempotencyKey(triggerPayload: any): string | undefined {
    if (!triggerPayload || typeof triggerPayload !== 'object') {
      return undefined;
    }

    const explicit = triggerPayload.idempotencyKey;
    if (typeof explicit === 'string' && explicit.length > 0) {
      return explicit;
    }

    const payloadId = triggerPayload.id;
    if (typeof payloadId === 'string' && payloadId.length > 0) {
      return payloadId;
    }

    return undefined;
  }

  private async getExecutionById(
    workflowId: string,
    executionId: string
  ): Promise<WorkflowExecution | null> {
    const execution = await this.workflowStorage.getExecution(executionId);
    if (!execution || execution.workflowId !== workflowId) {
      return null;
    }

    return execution;
  }
}

const PARALLEL_ACTION_CHECKPOINT_PREFIX = '__parallel__:';

function parallelActionCheckpointId(stepId: string, actionIndex: number): string {
  return `${PARALLEL_ACTION_CHECKPOINT_PREFIX}${stepId}:${actionIndex}`;
}

function assertUniqueWorkflowStepIds(steps: WorkflowStep[]): void {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  const reserved = new Set<string>();

  const visit = (step: WorkflowStep): void => {
    if (typeof step.id !== 'string') {
      throw new WorkflowEngineError(
        'WORKFLOW_DEFINITION_INVALID',
        'workflow step IDs must be strings',
        { stepId: step.id }
      );
    }
    if (step.id.startsWith(PARALLEL_ACTION_CHECKPOINT_PREFIX)) {
      reserved.add(step.id);
    }
    if (seen.has(step.id)) {
      duplicates.add(step.id);
    } else {
      seen.add(step.id);
    }

    if (step.type === 'branch') {
      for (const nested of [...step.then, ...(step.else ?? [])]) {
        visit(nested);
      }
    }
  };

  for (const step of steps) {
    visit(step);
  }

  if (reserved.size > 0) {
    const reservedStepIds = [...reserved].sort((left, right) => left.localeCompare(right));
    throw new WorkflowEngineError(
      'WORKFLOW_DEFINITION_INVALID',
      `workflow step IDs cannot use the reserved ${PARALLEL_ACTION_CHECKPOINT_PREFIX} prefix: ${reservedStepIds.join(', ')}`,
      { reservedStepIds }
    );
  }

  if (duplicates.size > 0) {
    const duplicateStepIds = [...duplicates].sort((left, right) => left.localeCompare(right));
    throw new WorkflowEngineError(
      'WORKFLOW_DEFINITION_INVALID',
      `workflow step IDs must be unique: ${duplicateStepIds.join(', ')}`,
      { duplicateStepIds }
    );
  }
}

function normalizeWorkflowExecutionFailure(error: unknown): {
  code: string;
  retriable: boolean;
  error: Error;
} {
  if (error instanceof WorkflowEngineError) {
    return {
      code: error.code,
      retriable: false,
      error,
    };
  }

  if (error instanceof Error) {
    return {
      code: 'WORKFLOW_STEP_FAILED',
      retriable: true,
      error,
    };
  }

  return {
    code: 'WORKFLOW_STEP_FAILED',
    retriable: true,
    error: new Error('workflow execution failed'),
  };
}

import type { Logger } from './action.js';
import type { RetryOptions } from './action.js';
import type { RateLimitConfig } from './provider.js';
import type { Adapter as DbAdapter, KVStoreAdapter } from '@superfunctions/db';
import type { AuthSession } from '@superfunctions/auth';
import type { PlugFnOAuthClientConfig, PlugFnSecretResolverConfig } from './runtime.js';
import type { Connection } from './connection.js';
import type { WorkflowRuntimeRegistry } from './workflow.js';

export type PlugFnDatabaseAdapter = DbAdapter;
export type Adapter = PlugFnDatabaseAdapter;

export interface PlugFnPrincipal {
  userId: string;
  tenantId?: string;
  organizationId?: string;
  roles?: string[];
  grants?: string[];
  metadata?: Record<string, unknown>;
}

export type PlugFnConnectionOperation =
  | 'read'
  | 'disconnect'
  | 'revoke'
  | 'sync'
  | 'action'
  | 'checkpoint';

export interface PlugFnAuthorizationOptions {
  authorizeConnection?(input: {
    actor: PlugFnPrincipal;
    connection: Connection;
    operation: PlugFnConnectionOperation;
  }): Promise<boolean> | boolean;
}

/**
 * Auth provider interface
 */
export interface AuthProvider {
  authenticate?(
    request: Request
  ): Promise<PlugFnPrincipal | AuthSession | null> | PlugFnPrincipal | AuthSession | null;
  getUserId?(request: any): Promise<string | null>;
  requireAuth?(request: any): Promise<string>;
}

/**
 * Integration configuration per provider
 */
export type IntegrationConfig =
  | OAuth2IntegrationConfig
  | PlugFnSecretResolverConfig
  | ApiKeyIntegrationConfig
  | JWTIntegrationConfig
  | BasicAuthIntegrationConfig;

export interface OAuth2IntegrationConfig extends PlugFnOAuthClientConfig {
  type?: 'oauth2';
}

export interface ApiKeyIntegrationConfig {
  type: 'api-key';
  apiKey: string;
}

export interface JWTIntegrationConfig {
  type: 'jwt';
  privateKey: string;
  publicKey?: string;
}

export interface BasicAuthIntegrationConfig {
  type: 'basic';
  username: string;
  password: string;
}

/**
 * Webhook configuration
 */
export interface WebhookOptions {
  verifySignatures?: boolean;
  allowedIPs?: string[];
  maxPayloadSize?: number;
}

/**
 * Global cache configuration
 */
export interface GlobalCacheConfig {
  enabled: boolean;
  ttl?: number;
  instance?: any;
  defaultTTL?: number;
  store?: KVStoreAdapter;
  keyPrefix?: string;
}

/**
 * Global rate limit configuration
 */
export interface GlobalRateLimitConfig {
  enabled: boolean;
  respectProviderLimits?: boolean;
  global?: RateLimitConfig;
}

/**
 * Global retry configuration
 */
export interface GlobalRetryConfig extends RetryOptions {
  enabled?: boolean;
}

/**
 * Main PlugFn configuration
 */
export interface PlugFnConfig {
  database: DbAdapter;
  cacheStore?: KVStoreAdapter;
  auth: AuthProvider;
  baseUrl: string;
  encryptionKey: string;
  integrations: Record<string, IntegrationConfig>;
