function createPlug(webhooks?: {
  verifySignatures?: boolean;
  allowedIPs?: string[];
  maxPayloadSize?: number;
}) {
  return plugFn({
    database: new MemoryAdapter(),
    auth: {
      async authenticate() {
        return {
          userId: 'user_e2e',
        };
      },
    },
    baseUrl: 'https://app.example.com',
    encryptionKey: '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef',
    integrations: {
      github: {
        type: 'oauth2',
        clientId: 'github-client-id',
        clientSecret: 'github-client-secret',
        redirectUris: ['https://app.example.com/oauth/callback'],
        webhookSecret: 'whsec_github',
      },
      slack: {
        type: 'oauth2',
        clientId: 'slack-client-id',
        clientSecret: 'slack-client-secret',
        redirectUris: ['https://app.example.com/oauth/callback'],
        webhookSecret: 'whsec_slack',
      },
    },
    webhooks,
  });
}

function signRawBody(rawBody: string, secret: string): string {
  const digest = createHmac('sha256', secret).update(rawBody).digest('hex');
  return `sha256=${digest}`;
}

function signLinearRawBody(rawBody: string, secret: string): string {
  return createHmac('sha256', secret).update(rawBody).digest('hex');
}

function signSlackRawBody(rawBody: string, secret: string, timestamp: string): string {
  const digest = createHmac('sha256', secret).update(`v0:${timestamp}:${rawBody}`).digest('hex');
  return `v0=${digest}`;
}

function signStripeRawBody(rawBody: string, secret: string, timestamp: string): string {
  const digest = createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  return `t=${timestamp},v1=${digest}`;
}

/**
 * Workflow status
 */
export enum WorkflowStatus {
  Enabled = 'enabled',
  Disabled = 'disabled',
  Draft = 'draft',
}

/**
 * Workflow execution status
 */
export enum WorkflowExecutionStatus {
  Pending = 'pending',
  Running = 'running',
  Completed = 'completed',
  Failed = 'failed',
  Cancelled = 'cancelled',
}

/**
 * Workflow definition stored in database
 */
export interface Workflow {
  id: string;
  userId: string;
  name: string;
  description?: string;
  definition: WorkflowDefinition;
  status: WorkflowStatus;
  metadata?: Record<string, any>;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Workflow definition structure
 */
export interface WorkflowDefinition {
  trigger: WorkflowTrigger;
  steps: WorkflowStep[];
  errorHandlers?: WorkflowErrorHandler[];
}

/**
 * Workflow trigger configuration
 */
export interface WorkflowTrigger {
  provider: string;
  event: string;
  filter?: WorkflowCondition;
}

export type WorkflowAction = (context: WorkflowContext) => Promise<any>;
export type WorkflowCondition = string | ((context: WorkflowContext) => boolean);
export type WorkflowErrorHandlerFn = (error: Error, context: WorkflowContext) => Promise<void>;

/** Runtime implementations for serializable workflow references. */
export interface WorkflowRuntimeRegistry {
  actions?: Record<string, WorkflowAction>;
  conditions?: Record<string, Exclude<WorkflowCondition, string>>;
  errorHandlers?: Record<string, WorkflowErrorHandlerFn>;
}

/**
 * Workflow step types
 */
export type WorkflowStep = ActionStep | FilterStep | BranchStep | ParallelStep | DelayStep;

export interface ActionStep {
  type: 'action';
  id: string;
  action: string | WorkflowAction;
}

export interface FilterStep {
  type: 'filter';
  id: string;
  condition: WorkflowCondition;
}

export interface BranchStep {
  type: 'branch';
  id: string;
  condition: WorkflowCondition;
  then: WorkflowStep[];
  else?: WorkflowStep[];
}

export interface ParallelStep {
  type: 'parallel';
  id: string;
  actions: Array<string | WorkflowAction>;
}

export interface DelayStep {
  type: 'delay';
  id: string;
  duration: number;
  unit?: 'ms' | 'seconds' | 'minutes' | 'hours' | 'days';
}

/**
 * Workflow execution context
 */
export interface WorkflowContext {
  workflowId: string;
  executionId: string;
  userId: string;
  trigger: {
    provider: string;
    event: string;
    payload: any;
  };
  data: Record<string, any>;
  metadata?: Record<string, any>;
}

/**
 * Error handler
 */
export interface WorkflowErrorHandler {
  stepId?: string;
  handler: string | WorkflowErrorHandlerFn;
}

/**
 * Workflow execution record
 */
export interface WorkflowExecution {
  id: string;
  workflowId: string;
  status: WorkflowExecutionStatus;
  input?: any;
  output?: any;
  error?: string;
  durationMs?: number;
  startedAt: Date;
  completedAt?: Date;
}

/**
 * Workflow statistics
 */
export interface WorkflowStats {
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  successRate: number;
  avgDuration: number;
  lastExecutedAt?: Date;
}

/**
 * List workflows options
 */
export interface ListWorkflowsOptions {
  userId?: string;
  status?: WorkflowStatus;
  provider?: string;
}

export type PlugFnOwnerKind = 'user' | 'organization' | 'delegated';

export type PlugFnConnectionOwner =
  | { kind: 'user'; userId: string; tenantId?: string }
  | { kind: 'organization'; organizationId: string; installedByUserId: string; tenantId?: string }
  | {
      kind: 'delegated';
      organizationId: string;
      delegatedToUserId: string;
      installedByUserId: string;
      grants: string[];
      tenantId?: string;
    };

export interface PlugFnActor {
