    });
  }

  async upsertSecretRef(secretRef: PlugFnSecretRef): Promise<PlugFnSecretRef> {
    return this.database.upsert<PlugFnSecretRef>({
      model: this.models.secretRefs,
      where: [{ field: 'id', operator: 'eq', value: secretRef.id }],
      create: cloneRecord(secretRef),
      update: cloneRecord({
        keyRef: secretRef.keyRef,
        metadata: secretRef.metadata,
        updatedAt: secretRef.updatedAt,
      }),
      conflictTarget: 'id',
    });
  }

  async listSecretRefs(filters: Record<string, unknown> = {}): Promise<PlugFnSecretRef[]> {
    return this.database.findMany<PlugFnSecretRef>({
      model: this.models.secretRefs,
      where: toWhereClauses(filters),
      orderBy: [{ field: 'createdAt', direction: 'desc' }],
    });
  }
}

function cloneRecord<T>(value: T): T {
  if (value === undefined || value === null) {
    return value;
  }

  if (typeof structuredClone === 'function') {
    return structuredClone(value);
  }

  return JSON.parse(JSON.stringify(value)) as T;
}

function cloneWorkflowRecord<T>(value: T, seen = new WeakMap<object, unknown>()): T {
  if (typeof value === 'function' || value === undefined || value === null) {
    return value;
  }
  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }
  if (Array.isArray(value)) {
    const existing = seen.get(value);
    if (existing) {
      return existing as T;
    }
    const clone: unknown[] = [];
    seen.set(value, clone);
    for (const entry of value) {
      clone.push(cloneWorkflowRecord(entry, seen));
    }
    return clone as T;
  }
  if (typeof value === 'object') {
    const existing = seen.get(value);
    if (existing) {
      return existing as T;
    }
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      return cloneRecord(value);
    }
    const clone: Record<string, unknown> = {};
    seen.set(value, clone);
    for (const [key, entry] of Object.entries(value)) {
      clone[key] = cloneWorkflowRecord(entry, seen);
    }
    return clone as T;
  }
  return value;
}

function assertWorkflowRecordPersistable(database: DbAdapter, value: unknown): void {
  if (database.id === 'memory') {
    return;
  }

  const ancestors = new WeakSet<object>();
  const visit = (entry: unknown, path: string): void => {
    if (typeof entry === 'function') {
      throw new TypeError(
        `Persistent PlugFn workflow storage cannot serialize callback at ${path}; use a memory adapter for executable callback workflows`
      );
    }
    if (typeof entry === 'bigint' || typeof entry === 'symbol') {
      throw new TypeError(`Persistent PlugFn workflow storage cannot serialize ${typeof entry} at ${path}`);
    }
    if (entry === null || typeof entry !== 'object' || entry instanceof Date) {
      return;
    }
    if (!Array.isArray(entry)) {
      const prototype = Object.getPrototypeOf(entry);
      if (prototype !== Object.prototype && prototype !== null) {
        const typeName = entry.constructor?.name ?? 'object';
        throw new TypeError(
          `Persistent PlugFn workflow storage cannot serialize ${typeName} at ${path}; use plain JSON-compatible objects`
        );
      }
    }
    if (ancestors.has(entry)) {
      throw new TypeError(`Persistent PlugFn workflow storage cannot serialize cyclic value at ${path}`);
    }

    ancestors.add(entry);
    if (Array.isArray(entry)) {
      entry.forEach((item, index) => visit(item, `${path}[${index}]`));
    } else {
      for (const [key, item] of Object.entries(entry)) {
        visit(item, `${path}.${key}`);
      }
    }
    ancestors.delete(entry);
  };

  visit(value, 'workflow');
}

function toWhereClauses(filters: Record<string, unknown>): WhereClause[] {
  const where: WhereClause[] = [];

  for (const [field, value] of Object.entries(filters)) {
    if (value === undefined) {
      continue;
    }
    where.push({ field, operator: 'eq', value });
  }

  return where;
}

function claimMetadata(
  metadata: Record<string, unknown> | undefined,
  workerId: string,
  claimedAt: Date
): Record<string, unknown> {
  return {
    ...(metadata ?? {}),
    workerClaim: {
      workerId,
      claimedAt: claimedAt.toISOString(),
    },
  };
}

function toTime(value: Date | string): number {
  return value instanceof Date ? value.getTime() : new Date(value).getTime();
}

import { describe, expect, it } from 'vitest';
import { NoopLogger, ProviderRegistry, WebhookHandler } from 'plugfn';
import { outlookProvider } from '../src/outlook/index.js';

describe('Outlook webhook verification', () => {
  it('requires a client state when creating subscriptions', () => {
    expect(() =>
      outlookProvider.actions['mail.subscription.ensure'].parameters.parse({
        tenantId: 'tenant-1',
        notificationUrl: 'https://app.example.com/webhooks/outlook',
      })
    ).toThrow();
  });

  it('accepts subscription notifications with the configured client state', async () => {
    const handler = createHandler();

    await expect(
      handler.handleWebhook(
        'outlook',
        'mail.update',
        notification('expected-client-state'),
        {},
        'expected-client-state'
      )
    ).resolves.toMatchObject({ verified: true });
  });

  it.each([undefined, 'wrong-client-state'])(
    'rejects subscription notifications with client state %s',
    async (clientState) => {
      await expect(
        createHandler().handleWebhook(
          'outlook',
          'mail.update',
          notification(clientState),
          {},
          'expected-client-state'
        )
      ).rejects.toMatchObject({ code: 'WEBHOOK_SIGNATURE_INVALID' });
    }
  );
});

function createHandler(): WebhookHandler {
  const logger = new NoopLogger();
  const registry = new ProviderRegistry(logger);
  registry.register(outlookProvider);
  return new WebhookHandler(registry, logger);
}

function notification(clientState: string | undefined) {
  return {
    value: [
      {
        subscriptionId: 'sub-1',
        resource: "/me/mailFolders('Inbox')/messages/m1",
        ...(clientState ? { clientState } : {}),
      },
    ],
  };
}

