export class OutlookProviderError extends Error {
  readonly code:
    | 'VALIDATION_ERROR'
    | 'OAUTH_SCOPE_DISALLOWED'
    | 'MAIL_SYNC_CHECKPOINT_INVALID'
    | 'PROVIDER_POLICY_BLOCKED';
  readonly status: number;

  constructor(
    code:
      | 'VALIDATION_ERROR'
      | 'OAUTH_SCOPE_DISALLOWED'
      | 'MAIL_SYNC_CHECKPOINT_INVALID'
      | 'PROVIDER_POLICY_BLOCKED',
    message: string
  ) {
    super(message);
    this.name = 'OutlookProviderError';
    this.code = code;
    this.status = code === 'MAIL_SYNC_CHECKPOINT_INVALID' ? 409 : 400;
  }
}

export interface OutlookProviderConfig {
  clientId: string;
  clientSecret: string;
  redirectUris: string[];
}

export function assertOutlookProviderConfig(config: unknown): OutlookProviderConfig {
  if (!config || typeof config !== 'object') {
    throw new OutlookProviderError('VALIDATION_ERROR', 'outlook provider config is required');
  }

  const asRecord = config as Record<string, unknown>;
  const clientId = typeof asRecord.clientId === 'string' ? asRecord.clientId.trim() : '';
  const clientSecret = typeof asRecord.clientSecret === 'string' ? asRecord.clientSecret.trim() : '';
  const redirectUris = Array.isArray(asRecord.redirectUris)
    ? asRecord.redirectUris.filter((value): value is string => {
        return typeof value === 'string' && value.trim().length > 0;
      })
    : [];

  if (!clientId || !clientSecret || redirectUris.length === 0) {
    throw new OutlookProviderError('VALIDATION_ERROR', 'outlook provider config is invalid');
  }

  return {
    clientId,
    clientSecret,
    redirectUris,
  };
}

export function resolveOutlookScopes(
  features: string[] = ['mail.read.metadata', 'profile.basic']
): string[] {
  const policy = defaultPolicyRegistry.getPolicy('microsoft');
  const scopes = new Set<string>();

  for (const feature of features) {
    const featurePolicy = policy.featureScopes[feature];
    if (!featurePolicy) {
      throw new OutlookProviderError(
        'OAUTH_SCOPE_DISALLOWED',
        `feature scope policy not found: ${feature}`
      );
    }

    for (const scope of featurePolicy.allowedScopes) {
      scopes.add(scope);
    }
  }

  return [...scopes];
}

export const outlookProvider: Provider = {
  name: 'outlook',
  displayName: 'Outlook',
  version: '1.0.0',
  description: 'Microsoft Graph mail delta and subscription adapter for Outlook',
  iconUrl: 'https://res.cdn.office.net/assets/mail/pwa/v3/pngs/logo_mail_5x.png',
  baseUrl: 'https://graph.microsoft.com',
  auth: {
    type: AuthType.OAuth2,
    config: {
      authorizationUrl: 'https://login.microsoftonline.com/common/oauth2/v2.0/authorize',
      tokenUrl: 'https://login.microsoftonline.com/common/oauth2/v2.0/token',
      scopes: resolveOutlookScopes(),
      scopeSeparator: ' ',
    },
  },
  actions: {
    'mail.sync': {
      name: 'mail.sync',
      displayName: 'Sync Mail',
      description: 'Sync Outlook messages using Graph delta checkpoints',
      idempotent: true,
      parameters: syncParamsSchema,
      returns: z.object({
        checkpoint: z.string(),
        fetched: z.number().int().nonnegative(),
        upserted: z.number().int().nonnegative(),
        skipped: z.number().int().nonnegative(),
        partial: z.boolean(),
        messages: z.array(NormalizedMailMessageSchema),
      }),
      execute: async (
        params: z.infer<typeof syncParamsSchema>,
        context: ActionContext
      ) => {
        const connectionId = requireConnectionId(context);
        const source = createOutlookDeltaSource(context);
        const result = await runOutlookDeltaSync(
          {
            tenantId: params.tenantId,
            userId: context.userId,
            connectionId,
            mode: params.mode,
            checkpoint: params.checkpoint,
            maxMessages: params.maxMessages,
            featureMode: params.featureMode,
          },
          {
            source,
            checkpointStore: defaultDeltaTokenStore,
            messageStore: defaultMessageStore,
            policyRegistry: defaultPolicyRegistry,
          }
        );

        return {
          checkpoint: result.checkpoint,
          fetched: result.fetched,
          upserted: result.upserted,
          skipped: result.skipped,
          partial: result.partial,
          messages: result.messages,
        };
      },
    },
    'mail.subscription.ensure': {
      name: 'mail.subscription.ensure',
      displayName: 'Ensure Subscription',
      description: 'Create or renew Graph change notification subscription',
      parameters: subscriptionParamsSchema,
      returns: z.object({
        renewed: z.boolean(),
        subscriptionId: z.string(),
        expirationDateTime: z.string().datetime({ offset: true }),
        policyVersion: z.string(),
      }),
      execute: async (
        params: z.infer<typeof subscriptionParamsSchema>,
        context: ActionContext
      ) => {
        const connectionId = requireConnectionId(context);
        const subscriptionClient = createOutlookSubscriptionClient(context);
        const ensured = await ensureOutlookSubscription(
          {
            tenantId: params.tenantId,
            userId: context.userId,
            connectionId,
            resource: params.resource,
            notificationUrl: params.notificationUrl,
            expirationDateTime: params.expirationDateTime,
            clientState: params.clientState,
            renewThresholdMs: params.renewThresholdMs,
            forceRenew: params.forceRenew,
            featureMode: params.featureMode,
          },
          {
            subscriptionStore: defaultSubscriptionStore,
            subscriptionClient,
            policyRegistry: defaultPolicyRegistry,
          }
        );

        return {
          renewed: ensured.renewed,
          subscriptionId: ensured.subscription.subscriptionId,
          expirationDateTime: ensured.subscription.expirationDateTime,
          policyVersion: ensured.subscription.policyVersion,
        };
      },
    },
    'mail.subscription.handlePush': {
      name: 'mail.subscription.handlePush',
      displayName: 'Handle Subscription Push',
      description: 'Handle Graph push notifications and trigger incremental sync',
      parameters: subscriptionNotificationParamsSchema,
      returns: z.object({
        triggered: z.boolean(),
        count: z.number().int().nonnegative(),
      }),
      execute: async (
        params: z.infer<typeof subscriptionNotificationParamsSchema>,
        context: ActionContext
      ) => {
        const connectionId = requireConnectionId(context);
        const source = createOutlookDeltaSource(context);
        const result = await handleOutlookSubscriptionNotification(
          {
            tenantId: params.tenantId,
            userId: context.userId,
            connectionId,
            payload: params.payload,
          },
          {
            subscriptionStore: defaultSubscriptionStore,
            triggerDeltaSync: async ({ tenantId, userId, connectionId: syncConnectionId }) => {
              await runOutlookDeltaSync(
                {
                  tenantId,
                  userId,
                  connectionId: syncConnectionId,
                  mode: 'incremental',
                },
                {
                  source,
                  checkpointStore: defaultDeltaTokenStore,
                  messageStore: defaultMessageStore,
                  policyRegistry: defaultPolicyRegistry,
                }
              );
            },
          }
        );

        return result;
      },
    },
  },
  triggers: {
    'mail.update': {
      name: 'mail.update',
      displayName: 'Mail Update',
      description: 'Triggered from Graph subscription notifications',
      type: TriggerType.Webhook,
      webhookConfig: {
        path: '/webhooks/outlook/mail-update',
        method: 'POST',
        verifySignature: (payload, _signature, secret) =>
          verifyOutlookClientState(payload, secret),
      },
      schema: z.object({
        value: z.array(z.unknown()),
      }),
      handler: async (payload: unknown) => {
        const notifications = parseOutlookSubscriptionNotifications(payload);
        return {
          event: 'mail.update',
          data: notifications,
        };
      },
    },
  },
  rateLimit: {
    requests: 1000,
    window: 60000,
  },
};

export function verifyOutlookClientState(
  payload: unknown,
  expectedClientState: string
): boolean {
  if (!payload || typeof payload !== 'object' || !expectedClientState) {
    return false;
  }

  const entries = (payload as Record<string, unknown>).value;
  if (!Array.isArray(entries) || entries.length === 0) {
    return false;
  }

  return entries.every((entry) => {
    if (!entry || typeof entry !== 'object') {
      return false;
    }
    const clientState = (entry as Record<string, unknown>).clientState;
    return (
      typeof clientState === 'string' && secureStringEqual(clientState, expectedClientState)
    );
  });
}

function requireConnectionId(context: ActionContext): string {
  if (context.connectionId && context.connectionId.length > 0) {
    return context.connectionId;
  }

  throw new OutlookProviderError(
    'VALIDATION_ERROR',
    'outlook action requires explicit connectionId when multiple connections may exist'
  );
}

function createOutlookDeltaSource(context: ActionContext): OutlookDeltaSource {
  return {
    listDelta: async ({ deltaToken, maxMessages }) => {
      const url = resolveOutlookDeltaRequestUrl(context.provider.baseUrl, deltaToken);

      try {
        const response = await context.http.get<{
          value?: Array<Record<string, unknown>>;
          '@odata.nextLink'?: string;
          '@odata.deltaLink'?: string;
        }>(url, {
          params: deltaToken
            ? undefined
            : {
                '$top': maxMessages,
              },
        });

        const nextDeltaToken = response.data['@odata.deltaLink'] ?? response.data['@odata.nextLink'];
        if (!nextDeltaToken || nextDeltaToken.length === 0) {
          throw new OutlookProviderError('VALIDATION_ERROR', 'graph delta response missing checkpoint token');
        }

        return {
          messages: (response.data.value ?? []) as any,
          nextDeltaToken,
          partial: Boolean(response.data['@odata.nextLink']),
        };
      } catch (error) {
        const httpError = error as HttpError & {
          status?: number;
          data?: Record<string, unknown>;
        };
        if (httpError.status === 429) {
          throw {
            status: 429,
            retryAfterSeconds: extractRetryAfterSeconds(httpError.data),
            message: 'graph throttled',
          };
        }

        if (httpError.status === 404 || httpError.status === 410) {
          throw new OutlookDeltaSyncError('MAIL_SYNC_CHECKPOINT_INVALID', 'outlook delta token invalid');
        }

        throw error;
      }
    },
  };
}

export function resolveOutlookDeltaRequestUrl(
  baseUrl: string,
  deltaToken?: string
): string {
  const normalizedBaseUrl = baseUrl.replace(/\/$/, '');
  const defaultUrl = `${normalizedBaseUrl}/v1.0/me/messages/delta`;
  if (!deltaToken) {
    return defaultUrl;
  }

  let requestUrl: URL;
  let providerUrl: URL;
  try {
    providerUrl = new URL(normalizedBaseUrl);
    requestUrl = new URL(deltaToken, `${normalizedBaseUrl}/`);
  } catch {
    throw new OutlookProviderError(
      'VALIDATION_ERROR',
      'outlook delta checkpoint URL is invalid'
    );
  }

  if (requestUrl.origin !== providerUrl.origin) {
    throw new OutlookProviderError(
      'VALIDATION_ERROR',
      'outlook delta checkpoint URL must use the Microsoft Graph origin'
    );
  }

  return requestUrl.toString();
}

function createOutlookSubscriptionClient(context: ActionContext): OutlookSubscriptionClient {
  return {
    createOrRenew: async ({
      subscriptionId,
      resource,
      notificationUrl,
      expirationDateTime,
      clientState,
    }) => {
      const payload = {
        changeType: 'created,updated',
        resource,
        notificationUrl,
        expirationDateTime,
        clientState,
      };

      try {
        const response = subscriptionId
          ? await context.http.patch<{
              id: string;
              expirationDateTime: string;
            }>(`${context.provider.baseUrl}/v1.0/subscriptions/${subscriptionId}`, payload)
          : await context.http.post<{
              id: string;
              expirationDateTime: string;
            }>(`${context.provider.baseUrl}/v1.0/subscriptions`, payload);

        return {
          subscriptionId: response.data.id,
          expirationDateTime: response.data.expirationDateTime,
        };
      } catch (error) {
        const httpError = error as HttpError & {
          status?: number;
          data?: Record<string, unknown>;
        };
        if (httpError.status === 429) {
          throw {
            status: 429,
            retryAfterSeconds: extractRetryAfterSeconds(httpError.data),
            message: 'graph throttled',
          };
        }

        throw error;
      }
    },
  };
}

function extractRetryAfterSeconds(data: Record<string, unknown> | undefined): number | undefined {
  if (!data) {
    return undefined;
  }

  const topLevelRetryAfter = data.retryAfter;
  if (typeof topLevelRetryAfter === 'number' && Number.isFinite(topLevelRetryAfter)) {
    return topLevelRetryAfter;
  }

  if (typeof topLevelRetryAfter === 'string') {
    const parsed = Number(topLevelRetryAfter);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }

  const nestedError = data.error;
  if (nestedError && typeof nestedError === 'object') {
    const nestedRetryAfter = (nestedError as Record<string, unknown>).retryAfter;
    if (typeof nestedRetryAfter === 'number' && Number.isFinite(nestedRetryAfter)) {
      return nestedRetryAfter;
    }
    if (typeof nestedRetryAfter === 'string') {
      const parsed = Number(nestedRetryAfter);
      if (Number.isFinite(parsed)) {
        return parsed;
      }
    }
  }

  return undefined;
}

import { describe, expect, it } from 'vitest';
import { WorkflowEngine } from '../src/core/workflow-engine.js';
import { ProviderRegistry } from '../src/core/provider-registry.js';
import { WebhookHandler } from '../src/webhooks/webhook-handler.js';
import type { WorkflowStorage } from '../src/storage/workflow-storage.js';
import { NoopLogger } from '../src/utils/logger.js';
import {
  WorkflowExecutionStatus,
  WorkflowStatus,
  type Workflow,
  type WorkflowExecution,
} from '../src/types/workflow.js';

describe('workflow durability semantics', () => {
  it('resumes a failed execution after restart and prevents duplicate completed execution', async () => {
    const { storage, logger } = createHarness();
    const firstEngine = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger
    );

    const sideEffects: string[] = [];
    let failStepTwoOnce = true;
    const workflow = await firstEngine.create({
      userId: 'user-1',
      name: 'workflow-durability-resume',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: {
          provider: 'github',
          event: 'issues.opened',
        },
        steps: [
          {
            id: 'step-1',
            type: 'action',
            action: async () => {
              sideEffects.push('step-1');
              return { first: true };
            },
          },
          {
            id: 'step-2',
            type: 'action',
            action: async () => {
              if (failStepTwoOnce) {
                failStepTwoOnce = false;
                throw new Error('step two failed');
              }
              sideEffects.push('step-2');
              return { second: true };
            },
          },
        ],
      },
    });

    await expect(
      firstEngine.execute(workflow.id, {
        idempotencyKey: 'evt_01',
      })
    ).rejects.toThrow('step two failed');

    const resumedEngine = new WorkflowEngine(
      storage,
      new WebhookHandler(new ProviderRegistry(logger), logger),
      logger
    );
    const resumed = await resumedEngine.execute(workflow.id, {
      idempotencyKey: 'evt_01',
    });
    const duplicate = await resumedEngine.execute(workflow.id, {
      idempotencyKey: 'evt_01',
    });

    expect(resumed.status).toBe(WorkflowExecutionStatus.Completed);
    expect(duplicate.id).toBe(resumed.id);
    expect(duplicate.status).toBe(WorkflowExecutionStatus.Completed);
    expect(resumed.output.__workflow).toMatchObject({
      idempotencyKey: 'evt_01',
      completedStepIds: ['step-1', 'step-2'],
      resumed: true,
      retriable: false,
    });
    expect(sideEffects).toEqual(['step-1', 'step-2']);
  });

  it('fails closed on delay steps with WORKFLOW_DURABILITY_UNSUPPORTED', async () => {
    const { engine, storage } = createHarness();

    const workflow = await engine.create({
      userId: 'user-1',
      name: 'workflow-delay-unsupported',
      status: WorkflowStatus.Enabled,
      definition: {
        trigger: {
          provider: 'github',
          event: 'issues.opened',
        },
        steps: [
          {
            id: 'delay-1',
            type: 'delay',
            duration: 5,
            unit: 'seconds',
          },
        ],
      },
    });

    await expect(
      engine.execute(workflow.id, {
        idempotencyKey: 'evt_delay',
      })
    ).rejects.toMatchObject({
      code: 'WORKFLOW_DURABILITY_UNSUPPORTED',
    });

    const execution = await storage.findExecutionByIdempotencyKey(workflow.id, 'evt_delay');
    expect(execution?.status).toBe(WorkflowExecutionStatus.Failed);
    expect(execution?.error).toBe(
      'WORKFLOW_DURABILITY_UNSUPPORTED:delay step delay-1 requires a durable scheduler'
    );
    expect(execution?.output.__workflow).toMatchObject({
      idempotencyKey: 'evt_delay',
      errorCode: 'WORKFLOW_DURABILITY_UNSUPPORTED',
      retriable: false,
      failedStepId: 'delay-1',
    });
  });

  it('rejects duplicate step IDs across top-level and nested branches', async () => {
    const { engine } = createHarness();

    await expect(
      engine.create({
        userId: 'user-1',
        name: 'workflow-duplicate-step-ids',
        status: WorkflowStatus.Enabled,
        definition: {
          trigger: { provider: 'github', event: 'issues.opened' },
          steps: [
            {
              id: 'duplicate',
              type: 'action',
              action: async () => ({}),
            },
            {
              id: 'branch',
              type: 'branch',
              condition: () => true,
              then: [
                {
                  id: 'duplicate',
                  type: 'action',
                  action: async () => ({}),
                },
              ],
            },
          ],
        },
      })
    ).rejects.toMatchObject({
      code: 'WORKFLOW_DEFINITION_INVALID',
      details: { duplicateStepIds: ['duplicate'] },
    });
  });
});

function createHarness() {
  const storage = new InMemoryWorkflowStorage();
  const logger = new NoopLogger();
  const providerRegistry = new ProviderRegistry(logger);
  const webhookHandler = new WebhookHandler(providerRegistry, logger);
  const engine = new WorkflowEngine(storage, webhookHandler, logger);

  return {
    storage,
    logger,
    webhookHandler,
    engine,
  };
}

class InMemoryWorkflowStorage implements WorkflowStorage {
  private readonly workflows = new Map<string, Workflow>();
  private readonly executions = new Map<string, WorkflowExecution>();
  private workflowCounter = 0;
  private executionCounter = 0;

  async create(workflow: Omit<Workflow, 'id' | 'createdAt' | 'updatedAt'>): Promise<Workflow> {
    const created: Workflow = {
      ...workflow,
      id: `wf_${++this.workflowCounter}`,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.workflows.set(created.id, created);
    return created;
  }

  async get(id: string): Promise<Workflow | null> {
    return this.workflows.get(id) ?? null;
  }

  async list(userId?: string, status?: WorkflowStatus): Promise<Workflow[]> {
    return [...this.workflows.values()].filter((workflow) => {
      if (userId && workflow.userId !== userId) {
        return false;
      }
      if (status && workflow.status !== status) {
        return false;
      }
      return true;
    });
  }

  async update(id: string, updates: Partial<Workflow>): Promise<Workflow> {
    const current = this.workflows.get(id);
    if (!current) {
      throw new Error(`Workflow ${id} not found`);
    }

    const updated: Workflow = {
      ...current,
      ...updates,
      id: current.id,
      updatedAt: new Date(),
    };
    this.workflows.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<void> {
    this.workflows.delete(id);
  }

  async createExecution(
    execution: Omit<WorkflowExecution, 'id' | 'startedAt'>
  ): Promise<WorkflowExecution> {
    const created: WorkflowExecution = {
      ...execution,
      id: `wfx_${++this.executionCounter}`,
      startedAt: new Date(),
    };
    this.executions.set(created.id, created);
    return created;
  }

  async getExecution(id: string): Promise<WorkflowExecution | null> {
    return this.executions.get(id) ?? null;
  }

  async updateExecution(id: string, updates: Partial<WorkflowExecution>): Promise<void> {
    const current = this.executions.get(id);
    if (!current) {
      throw new Error(`Workflow execution ${id} not found`);
    }

    this.executions.set(id, {
      ...current,
      ...updates,
      id: current.id,
      workflowId: current.workflowId,
      startedAt: current.startedAt,
    });
  }

  async listExecutions(workflowId: string, limit = 50): Promise<WorkflowExecution[]> {
    return [...this.executions.values()]
      .filter((execution) => execution.workflowId === workflowId)
      .sort((left, right) => right.startedAt.getTime() - left.startedAt.getTime())
      .slice(0, limit);
  }

  async findExecutionByIdempotencyKey(
    workflowId: string,
    idempotencyKey: string
  ): Promise<WorkflowExecution | null> {
    const executions = await this.listExecutions(workflowId, 1000);

    for (const execution of executions) {
      const input = execution.input as Record<string, unknown> | undefined;
      const workflowInput = input?.__workflow as Record<string, unknown> | undefined;
      const inputKey =
        typeof workflowInput?.idempotencyKey === 'string'
          ? workflowInput.idempotencyKey
          : typeof input?.idempotencyKey === 'string'
            ? input.idempotencyKey
            : undefined;
      if (inputKey === idempotencyKey) {
        return execution;
      }

      const output = execution.output as Record<string, unknown> | undefined;
      const workflowOutput = output?.__workflow as Record<string, unknown> | undefined;
      if (workflowOutput?.idempotencyKey === idempotencyKey) {
        return execution;
      }
    }

    return null;
  }
}

