      processed: 1,
      completed: 0,
      cancelled: 1,
      failed: 0,
      jobs: [{ status: 'cancelled' }],
    });
    await expect(plug.runtime.sync.getJob(job!.id)).resolves.toMatchObject({
      status: 'cancelled',
    });
  });

